insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class5-evs', 'Our Environment', 'Science', 'class', 'Class 5', '', 'Our body, plants and animals, water, fuels, maps and our country.', 0) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-1', 3, 'class5-evs', 'Our five senses', 'Our body', 'Science', 0, 'You can see me, hear me… but can you smell me? Let’s explore our five senses!', '["We have five senses: sight, hearing, smell, taste and touch.","The sense organs are the eyes, ears, nose, tongue and skin.","The skin is the largest sense organ; it feels heat, cold, pain and touch.","Our tongue can taste sweet, salty, sour and bitter.","Smell and taste work together: food tastes dull when your nose is blocked."]'::jsonb, 'People who cannot see can read using Braille, a system of raised dots felt with the fingers.', '[{"heading":"How senses help us","text":"Our senses tell us what is happening around us. Eyes show colours and shapes, ears catch sounds, the nose picks up smells, the tongue tastes food, and the skin feels whether things are hot, cold, rough or smooth."},{"heading":"Taste and smell","text":"Tiny taste buds on the tongue sense sweet, salty, sour and bitter tastes. When you have a cold, food seems to lose its taste, because much of what we call taste is really smell."},{"heading":"Taking care of our senses","text":"Never look straight at the Sun. Don’t put sharp things in your ears. Read in good light, and keep loud music low. Our senses keep us safe, so we must keep them safe too."}]'::jsonb, '[{"topic":"Science","question":"Which is the largest sense organ of the body?","options":["Eyes","Tongue","Skin","Nose"],"correct_index":2,"explanation":"The skin covers the whole body and feels touch."},{"topic":"Science","question":"Which sense organ helps us hear?","options":["Ears","Eyes","Nose","Skin"],"correct_index":0,"explanation":"We hear with our ears."},{"topic":"Science","question":"Braille helps people who cannot…","options":["hear","see","smell","walk"],"correct_index":1,"explanation":"Braille uses raised dots that can be read by touch."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-2', 3, 'class5-evs', 'From eating to digesting', 'Our body', 'Science', 1, 'Where does your lunch go after you swallow it? Let’s follow it on its journey!', '["Digestion starts in the mouth: teeth break food and saliva makes it soft.","Food goes down a pipe called the food pipe (oesophagus) to the stomach.","The stomach churns food and mixes it with digestive juices.","In the small intestine, food is broken down fully and taken into the blood.","Chewing food well and drinking clean water keep us healthy."]'::jsonb, 'The small intestine is the longest part of the digestive system.', '[{"heading":"In the mouth","text":"When you chew, your teeth cut and grind the food. Saliva, the watery juice in the mouth, makes food wet and soft, and even starts to change starch into sugar. That is why a roti tastes sweet if you chew it for a long time."},{"heading":"Stomach and intestines","text":"Swallowed food travels down the food pipe into the stomach. The stomach squeezes it and mixes it with juices. Then the small intestine takes the useful parts into the blood, which carries them all over the body."},{"heading":"Energy from food","text":"Food gives us energy to play, study and grow. Glucose, a kind of sugar, gives quick energy, which is why doctors sometimes give it to tired or sick people."}]'::jsonb, '[{"topic":"Science","question":"Where does digestion begin?","options":["Stomach","Mouth","Small intestine","Heart"],"correct_index":1,"explanation":"It begins in the mouth, with chewing and saliva."},{"topic":"Science","question":"Why does a roti taste sweet if you chew it for long?","options":["It has sugar in it","Saliva changes starch into sugar","The teeth make it sweet","It gets cold"],"correct_index":1,"explanation":"Saliva starts changing starch into sugar."},{"topic":"Science","question":"Which is the longest part of the digestive system?","options":["Food pipe","Stomach","Small intestine","Mouth"],"correct_index":2,"explanation":"The small intestine is the longest part."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-3', 3, 'class5-evs', 'Bones and muscles', 'Our body', 'Science', 2, 'Bend, jump, wave! Bones and muscles make every move possible. Let’s see how!', '["All the bones together make the skeleton, which gives our body its shape.","An adult has 206 bones; a baby is born with about 300, and some join together as it grows.","The skull protects the brain, and the ribs protect the heart and lungs.","Joints, like the knee and elbow, are where bones meet so we can bend.","Muscles pull on bones to move them; exercise makes them strong."]'::jsonb, 'The smallest bone in the body is inside the ear, and the longest is the thigh bone.', '[{"heading":"Our skeleton","text":"Without bones we would be floppy like a sack. The skeleton holds us up, protects soft parts inside, and helps us move. The backbone is made of many small bones, so we can bend and twist."},{"heading":"Joints","text":"A joint is where two bones meet. The knee and elbow bend like a door hinge. The shoulder can move in a circle, like a ball in a cup. The bones of the skull are joined so they cannot move."},{"heading":"Muscles and health","text":"Muscles are attached to bones. When a muscle gets shorter, it pulls the bone. Milk, curd and green vegetables help keep bones strong, and playing and exercise keep muscles fit."}]'::jsonb, '[{"topic":"Science","question":"How many bones does an adult have?","options":["106","206","300","360"],"correct_index":1,"explanation":"An adult has 206 bones."},{"topic":"Science","question":"Which bones protect the heart and lungs?","options":["Skull","Ribs","Backbone","Thigh bone"],"correct_index":1,"explanation":"The ribs form a cage around the heart and lungs."},{"topic":"Science","question":"The knee and elbow are examples of…","options":["muscles","joints","sense organs","teeth"],"correct_index":1,"explanation":"They are joints, where bones meet and can bend."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-4', 3, 'class5-evs', 'Seeds and how they travel', 'Plants and animals', 'Science', 3, 'A seed is a baby plant packed for a journey! Let’s see how seeds travel.', '["A seed needs water, air and warmth to grow; this is called germination.","Light, fluffy seeds, like cotton and dandelion, are carried by the wind.","A coconut can float, so it travels by water.","Some seeds have hooks that stick to animals’ fur; others are spread when birds eat fruit.","Pea and balsam pods burst open and throw their seeds away."]'::jsonb, 'Many foods we eat, like chillies, potatoes and tomatoes, first came to India from other lands.', '[{"heading":"Why seeds travel","text":"If all the seeds fell under the parent plant, they would fight for light, water and space. So plants have clever ways to send their seeds far away."},{"heading":"Wind, water and animals","text":"Wind carries light seeds with wings or hairs, like the drumstick seed. Water carries seeds that float. Animals carry sticky or hooked seeds on their bodies, or drop seeds after eating fruit."},{"heading":"A seed wakes up","text":"Soak some moong seeds in water overnight and keep them on a wet cloth. In a day or two, tiny shoots come out. The seed has germinated. People eat these as sprouts too!"}]'::jsonb, '[{"topic":"Science","question":"How does a coconut usually travel?","options":["By wind","By water","By bursting","By insects"],"correct_index":1,"explanation":"A coconut floats and can be carried by water."},{"topic":"Science","question":"What does a seed need to germinate?","options":["Water, air and warmth","Only sunlight","Only soil","Salt and sugar"],"correct_index":0,"explanation":"A seed needs water, air and warmth."},{"topic":"Science","question":"Cotton seeds are spread mainly by…","options":["animals","water","wind","bursting"],"correct_index":2,"explanation":"Fluffy cotton seeds float away on the wind."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-5', 3, 'class5-evs', 'Super senses of animals', 'Plants and animals', 'Science', 4, 'Some animals can see, hear and smell much better than us! Let’s meet the champions.', '["Eagles and kites can spot small animals on the ground from very high up.","Owls have big eyes that help them see at night.","Dogs have a very strong sense of smell; police use them to find things.","Bats make sounds and listen to the echoes to find their way in the dark.","Ants leave a smell trail on the ground so other ants can follow them."]'::jsonb, 'Animals that are awake at night are called nocturnal, like owls and bats.', '[{"heading":"Sharp eyes and ears","text":"Birds of prey, like eagles, have eyes that can see far and clearly. Owls see well in dim light. Many animals, like deer and dogs, can move their ears to catch faint sounds."},{"heading":"Smelling the world","text":"A dog can smell things we cannot even notice, so trained dogs help find lost people. Ants find their way by smell, and a mosquito finds us by the smell and warmth of our bodies."},{"heading":"Animals in danger","text":"Many animals are losing their homes as forests are cut. Hunting has also made animals like tigers rare. India protects them in national parks and sanctuaries, and it is our duty to care for them."}]'::jsonb, '[{"topic":"Science","question":"How do bats find their way in the dark?","options":["By smelling","By listening to echoes","By seeing colours","By touching walls"],"correct_index":1,"explanation":"Bats make sounds and listen to the echoes."},{"topic":"Science","question":"Animals that are awake at night are called…","options":["nocturnal","herbivores","reptiles","pets"],"correct_index":0,"explanation":"Night-time animals are nocturnal."},{"topic":"Science","question":"Why do ants walk in a line?","options":["They follow a smell trail","They are afraid","They can see far","The wind pushes them"],"correct_index":0,"explanation":"Ants follow the smell trail left by other ants."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-6', 3, 'class5-evs', 'Water, every drop counts', 'Water and fuel', 'Science', 5, 'There’s so much water on Earth, so why do we need to save it? Let’s find out!', '["Most of the Earth’s water is salty sea water; only a small part is fresh water we can use.","Much of the fresh water is frozen as ice.","Rainwater harvesting means collecting rainwater to use later or to fill the ground.","Long ago, people built stepwells (baolis) and tanks to store water.","Mosquitoes breed in still water; the female Anopheles mosquito spreads malaria."]'::jsonb, 'Rani ki Vav, a beautiful stepwell at Patan in Gujarat, is a UNESCO World Heritage Site.', '[{"heading":"Fresh water is precious","text":"We drink, cook, wash and grow food with fresh water from rivers, lakes and under the ground. Only a little of the world’s water is fresh and easy to reach, so we must not waste it."},{"heading":"Old and new ways to save water","text":"In dry places like Rajasthan, people built stepwells, tanks and underground tanks to catch rain. Today, many homes collect rainwater from rooftops. Closing taps and fixing leaks also save a lot of water."},{"heading":"Clean water, healthy life","text":"Dirty water can make us sick. Boiling or filtering water kills or removes germs. Don’t let water collect in old tyres or pots, as mosquitoes lay eggs there."}]'::jsonb, '[{"topic":"Science","question":"Which mosquito spreads malaria?","options":["Female Anopheles","Male Anopheles","Housefly","Honeybee"],"correct_index":0,"explanation":"The female Anopheles mosquito spreads malaria."},{"topic":"Science","question":"Collecting rainwater to use later is called…","options":["rainwater harvesting","irrigation","evaporation","flooding"],"correct_index":0,"explanation":"That is rainwater harvesting."},{"topic":"Science","question":"Rani ki Vav, a famous stepwell, is in…","options":["Rajasthan","Gujarat","Kerala","Bihar"],"correct_index":1,"explanation":"It is at Patan in Gujarat."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-7', 3, 'class5-evs', 'Fuels and saving energy', 'Water and fuel', 'Science', 6, 'Cars, buses and cooking stoves all need fuel. Let’s see where fuel comes from!', '["Coal, petrol and diesel are fossil fuels, formed from plants and animals buried millions of years ago.","Fossil fuels will run out one day, and burning them makes the air dirty.","LPG is used for cooking; CNG is a cleaner fuel for buses and autos.","The Sun, wind and flowing water give energy that never runs out.","Walking, cycling, sharing rides and switching off lights save energy."]'::jsonb, 'Petrol and diesel are made from crude oil, which is pumped up from deep under the ground or the sea.', '[{"heading":"Fuels from long ago","text":"Millions of years ago, plants and animals died and were buried under layers of mud. Slowly, heat and pressure turned them into coal, oil and gas. That is why we call them fossil fuels, and why they cannot be made again quickly."},{"heading":"Fuel and our air","text":"Burning fuel gives off smoke and gases that pollute the air and warm the Earth. Cleaner fuels like CNG and electric buses help cities breathe better."},{"heading":"Energy that lasts","text":"Solar panels turn sunlight into electricity, and windmills use the wind. Using these, and wasting less, means there will be enough energy for the future."}]'::jsonb, '[{"topic":"Science","question":"Which of these is a fossil fuel?","options":["Sunlight","Wind","Coal","Water"],"correct_index":2,"explanation":"Coal formed from plants buried millions of years ago."},{"topic":"Science","question":"Which fuel is cleaner for buses and autos?","options":["Diesel","CNG","Coal","Wood"],"correct_index":1,"explanation":"CNG burns more cleanly than diesel."},{"topic":"Science","question":"Which of these energy sources will never run out?","options":["Petrol","Coal","The Sun","Diesel"],"correct_index":2,"explanation":"Sunlight is a source that never runs out."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-8', 3, 'class5-evs', 'Maps and directions', 'Our country', 'Geography', 7, 'A map is like a bird’s-eye picture of a place. Let’s learn to read one!', '["The four main directions are North, South, East and West.","On most maps, North is at the top.","The Sun rises in the East and sets in the West.","A compass needle always points North–South.","Maps use symbols and colours, explained in a key, and a scale shows real distances."]'::jsonb, 'On maps, blue usually shows water, green shows plains and brown shows mountains.', '[{"heading":"Finding directions","text":"Stand facing the rising Sun in the morning: you face East. West is behind you, North is on your left and South is on your right."},{"heading":"Reading a map","text":"A map is a drawing of a place as seen from above. Small symbols show things like schools, rivers and railways, and the map key tells you what each symbol means."},{"heading":"Scale","text":"A big area is drawn small on a map. The scale tells you how much real distance a small length on the map stands for, like 1 cm = 10 km."}]'::jsonb, '[{"topic":"Geography","question":"If you face the rising Sun, which direction is on your left?","options":["North","South","West","East"],"correct_index":0,"explanation":"Facing East, North is on your left."},{"topic":"Geography","question":"What does a compass needle point to?","options":["East–West","North–South","Up","The Sun"],"correct_index":1,"explanation":"A compass needle points North–South."},{"topic":"Geography","question":"On a map, blue colour usually shows…","options":["mountains","water","roads","forests"],"correct_index":1,"explanation":"Blue usually shows rivers, lakes and seas."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class5-evs-9', 3, 'class5-evs', 'India, our country', 'Our country', 'Politics', 8, 'India is a land of many states, languages and festivals. Let’s learn about our country!', '["New Delhi is the capital of India.","India is divided into states and union territories; each state has its own capital.","The Constitution lists 22 languages in its Eighth Schedule.","The national animal is the tiger, the national bird is the peacock, and the national flower is the lotus.","“Jana Gana Mana”, written by Rabindranath Tagore, is our national anthem; “Vande Mataram”, by Bankim Chandra Chattopadhyay, is our national song."]'::jsonb, 'The Ashoka Chakra in the middle of our national flag has 24 spokes.', '[{"heading":"States and capitals","text":"India is a big country, so it is divided into states and union territories. Each state has its own government and capital, like Mumbai for Maharashtra, Chennai for Tamil Nadu and Lucknow for Uttar Pradesh."},{"heading":"Many languages, one nation","text":"People in India speak hundreds of languages, such as Hindi, Bengali, Tamil, Telugu, Marathi and many more. We also celebrate many festivals, like Diwali, Eid, Christmas, Guru Nanak Jayanti, Pongal and Bihu. Unity in diversity is India’s strength."},{"heading":"Our national symbols","text":"Our flag has three colours: saffron at the top, white in the middle with a navy blue Ashoka Chakra, and green at the bottom. The national emblem comes from the Lion Capital of Ashoka at Sarnath. These symbols remind us that we are one country."}]'::jsonb, '[{"topic":"Politics","question":"Who wrote our national anthem, “Jana Gana Mana”?","options":["Bankim Chandra Chattopadhyay","Rabindranath Tagore","Mahatma Gandhi","Sarojini Naidu"],"correct_index":1,"explanation":"Rabindranath Tagore wrote Jana Gana Mana."},{"topic":"Politics","question":"What is India’s national bird?","options":["Parrot","Peacock","Eagle","Sparrow"],"correct_index":1,"explanation":"The peacock is our national bird."},{"topic":"Politics","question":"How many spokes does the Ashoka Chakra have?","options":["12","20","24","32"],"correct_index":2,"explanation":"The Ashoka Chakra has 24 spokes."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class6-history-ancient-india', 'Ancient India', 'History', 'class', 'Class 6', '', 'From the Stone Age to the Gupta Empire.', 1) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-1', 3, 'class6-history-ancient-india', 'The Stone Age in India', 'Ancient India', 'History', 0, 'Let’s go back to the very beginning, when people made their tools from stone.', '["The Stone Age is the long period when people made their tools from stone.","It is divided into the Old (Palaeolithic), Middle (Mesolithic) and New (Neolithic) Stone Age.","Early people were hunter-gatherers who moved from place to place in search of food.","The rock shelters of Bhimbetka in Madhya Pradesh have paintings made thousands of years ago.","In the New Stone Age, people began farming, keeping animals and living in villages.","Mehrgarh, in present-day Pakistan, is one of the earliest farming villages in South Asia."]'::jsonb, 'The Bhimbetka rock shelters are a UNESCO World Heritage Site.', '[{"heading":"Life with stone tools","text":"For hundreds of thousands of years, people in India lived by hunting animals, fishing and gathering fruits, roots and seeds. They made tools by chipping stones into sharp edges, and moved from place to place following food, water and the seasons."},{"heading":"Three stages","text":"Historians divide the Stone Age into three stages. The Old Stone Age (Palaeolithic) was the longest. In the Middle Stone Age (Mesolithic), tools became small and sharp, called microliths. In the New Stone Age (Neolithic), people began farming, herding animals and making polished stone tools."},{"heading":"Paintings and first villages","text":"At Bhimbetka in Madhya Pradesh, rock shelters have paintings of animals, hunting and dancing made thousands of years ago. Once people started growing crops such as wheat and barley, they settled in villages. Mehrgarh, in present-day Pakistan, is one of the earliest such farming villages in South Asia."},{"heading":"Finding food","text":"Stone Age people did not grow their own food. They hunted animals like deer and wild pigs, caught fish, and gathered fruits, nuts, roots, seeds and honey. Because plants ripened in different seasons and animals moved from place to place, people also had to move. They usually lived in small groups and shared what they found. Knowing which plants were safe to eat and where water could be found was knowledge passed down from parents to children."},{"heading":"Fire and shelter","text":"Learning to control fire was one of the greatest discoveries of early humans. Fire gave light and warmth, kept wild animals away and let people cook food, which made it easier to eat and digest. Traces of ash found in the Kurnool caves of Andhra Pradesh show that people there used fire. Early humans often lived in natural caves and rock shelters near rivers and lakes, where they were protected from rain and cold."},{"heading":"Better tools","text":"Over thousands of years, tools improved. In the earliest period, people used big, rough stones as hand axes and choppers to cut meat, dig roots and shape wood. Later, in the Mesolithic period, they made tiny, sharp stone tools called microliths, often fixed onto handles of wood or bone to make spears, arrows and sickles. In the Neolithic period, tools were ground and polished, making them smoother and stronger."},{"heading":"From hunters to farmers","text":"Slowly, people noticed that seeds dropped on the ground grew into plants. They began to sow seeds and grow crops such as wheat, barley and rice. They also tamed animals like sheep, goats, cattle and dogs. Farming meant staying in one place to look after crops, so people built houses and lived in villages. At Mehrgarh, people were farming very early, and at Burzahom in Kashmir, people lived in pit houses dug into the ground."},{"heading":"Why the Stone Age matters","text":"The Stone Age was the longest part of human history. During this time, people learnt to make tools, use fire, paint, grow crops, tame animals and live together in villages. Every later achievement, from cities to computers, was built on these first steps. Archaeologists still study stone tools, bones and paintings to understand how our ancestors lived and changed."}]'::jsonb, '[{"topic":"History","question":"Where are India’s famous Stone Age rock shelters?","options":["Bhimbetka","Ajanta","Sanchi","Hampi"],"correct_index":0,"explanation":"The Bhimbetka rock shelters in Madhya Pradesh have very old cave paintings."},{"topic":"History","question":"In which age did people start farming?","options":["Old Stone Age","Middle Stone Age","New Stone Age","None"],"correct_index":2,"explanation":"Farming began in the New Stone Age, also called the Neolithic Age."},{"topic":"History","question":"Mehrgarh is known as one of the earliest…","options":["Ports","Farming villages","Temples","Forts"],"correct_index":1,"explanation":"Mehrgarh is one of the earliest farming villages in South Asia."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-2', 3, 'class6-history-ancient-india', 'The Indus Valley Civilisation', 'Ancient India', 'History', 1, 'Think of it as India’s earliest city planners. Let’s see what they built.', '["One of the world’s earliest urban civilisations, about 4,500 years ago.","Famous sites include Harappa, Mohenjo-daro, Dholavira and Lothal.","Cities were planned, with grid-like streets and covered drains.","Mohenjo-daro had the Great Bath, a large public water tank.","Lothal in Gujarat had a dockyard, which shows they traded by sea.","Their writing, the Indus script, has still not been deciphered."]'::jsonb, 'Harappa gave this civilisation its other name, the Harappan civilisation.', '[{"heading":"Cities by the rivers","text":"Around 4,500 years ago, large planned cities grew up along the Indus river and its neighbours, in parts of today’s Pakistan and north-west India. Harappa was the first of these cities to be found, in the 1920s, so this is also called the Harappan civilisation."},{"heading":"Well-planned towns","text":"Streets crossed each other at right angles, like a grid. Houses were built with baked bricks of a standard size, and covered drains carried away dirty water. Mohenjo-daro had the Great Bath, a large brick tank that may have been used for special ceremonies."},{"heading":"Work and trade","text":"People farmed, kept animals, made beads, pottery, seals and metal objects. Lothal in Gujarat had a dockyard, and Harappan goods have been found as far away as Mesopotamia. Their script is seen on many seals, but nobody has been able to read it yet."},{"heading":"How the cities were found","text":"For thousands of years, the Harappan cities lay buried and forgotten. In the 1920s, archaeologists began digging at Harappa in Punjab (now in Pakistan) and then at Mohenjo-daro in Sindh. They were amazed to find well-planned cities built about 4,500 years ago. Since Harappa was found first, the whole civilisation is often called the Harappan civilisation. Later, many more sites were discovered in India, such as Dholavira and Lothal in Gujarat, Kalibangan in Rajasthan and Rakhigarhi in Haryana."},{"heading":"Inside a Harappan city","text":"Many cities were divided into two parts. A raised western part, called the citadel, had special buildings, like the Great Bath at Mohenjo-daro. A larger lower town had houses for ordinary people. Houses were made of baked bricks of the same size and often had a courtyard, a well and a bathroom. Streets were straight and crossed each other at right angles, and covered drains ran along them."},{"heading":"Farmers and herders","text":"The cities depended on villages nearby. Farmers grew wheat, barley, peas, sesame and cotton, and kept cattle, sheep and goats. Ploughed fields have been found at Kalibangan. Food grains were stored in large buildings called granaries. Without the surplus food grown by farmers, the people in the cities, such as crafts-people, traders and priests, could not have lived."},{"heading":"Crafts and seals","text":"Harappan crafts-people were very skilled. They made beautiful beads from carnelian and other stones, pots with black designs, tools of copper and bronze, and toys and figurines of clay. They also made square stone seals with animals like the bull and the unicorn, and a short line of writing. Seals may have been used by traders to stamp their goods. Their script has not yet been read."},{"heading":"The end of the cities","text":"Around 3,900 years ago, many Harappan cities began to decline. People stopped building big houses and drains, and many left for smaller villages. Historians are not sure why. Some think rivers dried up or changed course, others think forests were cut, floods came or trade fell. Whatever the reasons, the people moved east and south, and many of their skills lived on in later Indian culture."}]'::jsonb, '[{"topic":"History","question":"Where was the Great Bath found?","options":["Harappa","Mohenjo-daro","Lothal","Kalibangan"],"correct_index":1,"explanation":"The Great Bath, a large public water tank, was found at Mohenjo-daro."},{"topic":"History","question":"Which Indus Valley site had a dockyard?","options":["Harappa","Rakhigarhi","Lothal","Dholavira"],"correct_index":2,"explanation":"Lothal in Gujarat had a dockyard, a sign of trade by sea."},{"topic":"History","question":"Why is it also called the Harappan civilisation?","options":["Harappa was its capital","Harappa was the first site found","Harappa was its largest port","A king named Harappa ruled it"],"correct_index":1,"explanation":"Harappa was the first site to be discovered, so the civilisation is named after it."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-3', 3, 'class6-history-ancient-india', 'The Vedic Age', 'Ancient India', 'History', 2, 'This age is named after some of the oldest books in the world. Let’s open them!', '["The Vedic Age is named after the Vedas, the oldest sacred texts of India.","There are four Vedas: the Rigveda, Samaveda, Yajurveda and Atharvaveda.","The Rigveda is the oldest of the four.","The Vedas were composed in Sanskrit and passed on by word of mouth for centuries.","Early Vedic people were mainly cattle herders; later they settled down as farmers."]'::jsonb, 'The Gayatri Mantra comes from the Rigveda.', '[{"heading":"The Vedas","text":"The Vedas are the oldest sacred texts of India, composed in Sanskrit. There are four: the Rigveda, Samaveda, Yajurveda and Atharvaveda. The Rigveda, a collection of hymns to gods such as Agni, Indra and Soma, is the oldest."},{"heading":"Remembered by heart","text":"For many centuries the Vedas were not written down. Students learned them by listening to teachers and repeating every word with great care, so they were passed on by word of mouth."},{"heading":"How people lived","text":"Early Vedic people kept cattle, horses, sheep and goats, and cattle were a measure of wealth. Over time they settled down and became farmers. Later, society came to be divided into four groups called varnas."},{"heading":"The four Vedas","text":"The Vedas are among the oldest books in the world. There are four: the Rigveda, the Samaveda, the Yajurveda and the Atharvaveda. The Rigveda is the oldest and has more than a thousand hymns praising gods such as Agni (fire), Indra (a warrior god) and Soma (a plant drink). The Samaveda has hymns set to music, the Yajurveda has prayers for rituals, and the Atharvaveda has charms and spells."},{"heading":"Life in early Vedic times","text":"In the early Vedic period, people were mostly herders and farmers. Cattle were their most important wealth, and many hymns pray for more cows and horses. People lived in small groups called janas, led by a chief called a raja. The raja was not a powerful king with a palace; he led people in battles and was helped by assemblies called the sabha and samiti, where men discussed matters together."},{"heading":"Changes in later Vedic times","text":"Over time, people moved east into the Ganga plains. They used iron tools to clear forests and grow more crops like rice. Small groups grew into larger kingdoms, and rajas became more powerful, performing big rituals to show their power. Society became divided into four groups, called varnas: priests, warriors, traders and farmers, and those who served the others. Over time, these divisions became more rigid."},{"heading":"Language and learning","text":"The Vedas were composed in early Sanskrit, an old Indian language. Many modern Indian languages, such as Hindi, Bengali and Marathi, grew from languages related to it. Learning happened through gurus, or teachers, who taught students by heart. Students lived with their teachers, helped with work and memorised hymns exactly, word for word, which is how the Vedas survived for thousands of years without being written down."},{"heading":"Women in Vedic times","text":"Some women in Vedic times were learned and took part in discussions. Hymns were composed by a few women, and later texts mention wise women like Gargi and Maitreyi, who asked deep questions about life and the universe. However, women generally had fewer rights than men, and over time their position became weaker. Studying these texts helps us understand how society changed."},{"heading":"Why the Vedic age matters","text":"Many ideas from the Vedic age are still part of Indian life. Some hymns are recited at weddings and festivals even today. Words in many Indian languages come from Vedic Sanskrit. Studying this period helps us understand how villages, kingdoms, rituals and social groups developed in early India, and how they changed over time."}]'::jsonb, '[{"topic":"History","question":"Which is the oldest of the four Vedas?","options":["Samaveda","Rigveda","Yajurveda","Atharvaveda"],"correct_index":1,"explanation":"The Rigveda is the oldest of the four Vedas."},{"topic":"History","question":"How many Vedas are there?","options":["Two","Three","Four","Six"],"correct_index":2,"explanation":"There are four Vedas: Rigveda, Samaveda, Yajurveda and Atharvaveda."},{"topic":"History","question":"In which language were the Vedas composed?","options":["Pali","Prakrit","Sanskrit","Tamil"],"correct_index":2,"explanation":"The Vedas were composed in Sanskrit."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-4', 3, 'class6-history-ancient-india', 'Buddhism and Jainism', 'Ancient India', 'History', 3, 'Two great teachers showed people a peaceful way to live. Let’s meet them.', '["Gautama Buddha founded Buddhism. He was born at Lumbini, in present-day Nepal.","He gained enlightenment under a Bodhi tree at Bodh Gaya, in Bihar.","He gave his first sermon at Sarnath, near Varanasi.","Vardhamana Mahavira was the 24th and last tirthankara of Jainism.","Both taught ahimsa, which means non-violence."]'::jsonb, 'The Buddha taught the Middle Path, a life without extremes.', '[{"heading":"The Buddha","text":"Siddhartha Gautama was born at Lumbini, in present-day Nepal. He left his comfortable life to understand why people suffer. After long meditation under a Bodhi tree at Bodh Gaya, he gained enlightenment and became the Buddha, “the awakened one”."},{"heading":"His teaching","text":"The Buddha gave his first sermon at Sarnath, near Varanasi. He taught kindness to all living beings and the Middle Path, a life that avoids extremes. He taught in Prakrit, the language of ordinary people, so everyone could understand."},{"heading":"Mahavira and Jainism","text":"Vardhamana Mahavira was the 24th and last tirthankara, or great teacher, of Jainism. He taught that people should not harm any living being. This idea, ahimsa or non-violence, is central to both Jainism and Buddhism."},{"heading":"The prince who left home","text":"Siddhartha Gautama was born about 2,500 years ago into a ruling family of the Sakya clan, at Lumbini in present-day Nepal. He lived a comfortable life, but he was troubled when he saw old age, sickness and death. At the age of about 29, he left his palace to find the answer to why people suffer. He wandered for years, meditating and talking to teachers, before finding his answer at Bodh Gaya."},{"heading":"The middle path","text":"The Buddha taught that life is full of suffering, and that suffering comes from our endless desires. If we learn to control our desires, we can find peace. He asked people to follow a middle path, neither too much luxury nor too much hardship, and to be kind, truthful and non-violent. He gave his first sermon at Sarnath, near Varanasi, and taught in Pali and Prakrit, the languages ordinary people spoke."},{"heading":"The sangha","text":"Followers of the Buddha who left their homes to live as monks and nuns formed a community called the sangha. They lived simply, begged for food, and spent time meditating and teaching. Rules for the sangha were written in a book called the Vinaya Pitaka. Many people, including kings, merchants, farmers and even former servants, joined the sangha. Monasteries, called viharas, were built for them to live in during the rainy season."},{"heading":"Mahavira’s teaching","text":"Vardhamana Mahavira, born a prince of the Vajji confederacy, also left home to seek truth. He became the 24th and last tirthankara of the Jains. He taught that people should not harm any living thing, not even insects. Jains were asked to be truthful, not steal, and give up greed. Because farming could harm small creatures, many Jains became traders. Jain teachings were later written down at Valabhi in Gujarat."},{"heading":"How the ideas spread","text":"Both Buddhism and Jainism spread far and wide. Monks and nuns travelled from place to place, teaching people. Kings like Ashoka supported Buddhism and sent messengers to other lands, including Sri Lanka. Stupas, such as the one at Sanchi, were built to hold relics of the Buddha. Over centuries, Buddhism spread to China, Japan, Tibet and South-East Asia, and both faiths continue to be followed today."}]'::jsonb, '[{"topic":"History","question":"Where did the Buddha give his first sermon?","options":["Bodh Gaya","Lumbini","Sarnath","Kushinagar"],"correct_index":2,"explanation":"The Buddha gave his first sermon at Sarnath."},{"topic":"History","question":"Mahavira was which tirthankara of Jainism?","options":["1st","12th","23rd","24th"],"correct_index":3,"explanation":"Vardhamana Mahavira was the 24th and last tirthankara."},{"topic":"History","question":"Where did the Buddha gain enlightenment?","options":["Sarnath","Bodh Gaya","Rajgir","Vaishali"],"correct_index":1,"explanation":"He gained enlightenment under a Bodhi tree at Bodh Gaya."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-5', 3, 'class6-history-ancient-india', 'The Mauryan Empire', 'Ancient India', 'History', 4, 'Here comes one of India’s first big empires, and a king who chose peace.', '["Chandragupta Maurya founded the Mauryan Empire around 321 BCE.","His adviser Chanakya, also called Kautilya, is linked with the Arthashastra, a book on running a state.","The capital was Pataliputra, near today’s Patna.","Ashoka, Chandragupta’s grandson, fought the Kalinga War and then turned to Buddhism.","Ashoka’s messages, called edicts, were carved on rocks and pillars across the empire."]'::jsonb, 'The Lion Capital of Ashoka at Sarnath is India’s National Emblem.', '[{"heading":"A big empire","text":"Chandragupta Maurya founded the Mauryan Empire around 321 BCE, with the help of his adviser Chanakya, also called Kautilya. Its capital was Pataliputra, near today’s Patna. The empire grew to cover most of the Indian subcontinent."},{"heading":"Ashoka changes his mind","text":"Ashoka, Chandragupta’s grandson, fought a terrible war to win Kalinga, in today’s Odisha. Seeing so much death and suffering, he decided never to fight wars of conquest again and turned to the Buddha’s teachings."},{"heading":"Messages on stone","text":"Ashoka had his messages, called edicts, carved on rocks and tall pillars across his empire. They asked people to be kind, respect elders and all religions, and treat animals well. The Lion Capital of his pillar at Sarnath is now India’s National Emblem."},{"heading":"Chandragupta and Chanakya","text":"Around 2,300 years ago, Chandragupta Maurya founded a great empire in north India, with the help of a wise adviser named Chanakya, also known as Kautilya. Chanakya’s ideas about how to rule are collected in a book called the Arthashastra. Chandragupta defeated the Nanda kings of Magadha and made Pataliputra, near modern Patna, his capital. His empire stretched from the north-west to the Deccan."},{"heading":"Ruling a huge empire","text":"The empire was too big to rule from one city alone. The area around Pataliputra was ruled directly by the emperor. Other areas were ruled from provincial capitals like Taxila and Ujjain, by princes sent as governors. Officials collected taxes from farmers, herders, crafts-people and traders, and messengers and spies kept the emperor informed. Megasthenes, a Greek ambassador, described Pataliputra as a large city with a wooden wall and many gates."},{"heading":"The Kalinga war","text":"Chandragupta’s grandson, Ashoka, is the most famous ruler of the dynasty. About eight years after becoming king, he attacked Kalinga, which is in present-day Odisha. The war was terrible: many thousands of people were killed, wounded or taken away as prisoners. Ashoka was filled with sorrow when he saw the suffering. He decided never to fight a war of conquest again. He is the only king in history known to give up war after winning one."},{"heading":"Ashoka’s dhamma","text":"Ashoka wanted people to follow dhamma, a set of good values. He asked people to respect elders, be kind to servants and slaves, treat animals gently, and respect all religions. He appointed officials called dhamma mahamattas to spread these ideas. He also built roads, rest houses and wells, planted trees and opened hospitals for people and animals. He sent messengers to Sri Lanka, Syria, Egypt and Greece to spread his message."},{"heading":"Reading the inscriptions","text":"Ashoka’s messages were carved on rocks and polished stone pillars across his empire, mostly in the Prakrit language and the Brahmi script. For centuries, nobody could read Brahmi. In the 19th century, a scholar named James Prinsep finally deciphered it, and people could read Ashoka’s own words again. The lion capital from his pillar at Sarnath, with four lions, is today the national emblem of India."}]'::jsonb, '[{"topic":"History","question":"What was the capital of the Mauryan Empire?","options":["Ujjain","Taxila","Pataliputra","Kannauj"],"correct_index":2,"explanation":"The Mauryan capital was Pataliputra, near today’s Patna."},{"topic":"History","question":"After which war did Ashoka turn to Buddhism?","options":["Kalinga War","Battle of Panipat","Kurukshetra War","Battle of Hydaspes"],"correct_index":0,"explanation":"The suffering of the Kalinga War led Ashoka to turn to Buddhism."},{"topic":"History","question":"The Arthashastra is linked with…","options":["Ashoka","Kautilya","Kalidasa","Megasthenes"],"correct_index":1,"explanation":"The Arthashastra is linked with Kautilya, also called Chanakya."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-6', 3, 'class6-history-ancient-india', 'The Gupta Empire', 'Ancient India', 'History', 5, 'Welcome to a time of great art, poetry and science. Some call it a golden age!', '["The Gupta Empire became powerful under Chandragupta I, from about 320 CE.","This period is often called the “Golden Age” of ancient India.","Samudragupta was a great conqueror. His coins show him playing the veena.","Aryabhata, the famous mathematician and astronomer, lived in this period.","The poet Kalidasa wrote the play Abhijnanashakuntalam."]'::jsonb, 'The Chinese traveller Faxian (Fa-Hien) visited India during the Gupta period.', '[{"heading":"The Gupta kings","text":"The Gupta Empire grew powerful under Chandragupta I, from about 320 CE. His son Samudragupta won many battles and was also a musician: his coins show him playing the veena. Chandragupta II later ruled a large and wealthy kingdom."},{"heading":"A golden age","text":"This period is often called the Golden Age of ancient India because of its great works in art, literature and science. The poet Kalidasa wrote plays such as Abhijnanashakuntalam, and Aryabhata wrote on mathematics and astronomy."},{"heading":"A visitor from China","text":"The Chinese Buddhist traveller Faxian (Fa-Hien) visited India during the Gupta period to collect Buddhist texts, and wrote about what he saw on his journey."},{"heading":"Samudragupta","text":"The Gupta dynasty began with Chandragupta I, but his son Samudragupta made the kingdom into a great empire about 1,700 years ago. A court poet named Harishena wrote a long poem in praise of him, carved on an Ashokan pillar at Prayagraj. It tells us that Samudragupta defeated many kings, made others pay tribute, and was also a fine poet and musician. Some of his coins show him playing the veena."},{"heading":"Chandragupta II","text":"Samudragupta’s son, Chandragupta II, also called Vikramaditya, expanded the empire further west. His court is said to have had many learned people. During his rule, the Chinese pilgrim Faxian visited India to collect Buddhist texts. Faxian wrote that the people were prosperous and that there were free hospitals in some cities. The famous iron pillar at Mehrauli in Delhi, which has not rusted for centuries, is from this period."},{"heading":"Science and mathematics","text":"The Gupta period is famous for science. Aryabhata, a great mathematician and astronomer, wrote that the Earth rotates on its axis and explained eclipses scientifically. Indian mathematicians used the decimal place-value system and the zero, ideas that later spread to the Arab world and Europe and are used everywhere today. Varahamihira wrote about astronomy and nature, and doctors like Sushruta and Charaka had written about medicine and surgery."},{"heading":"Art and literature","text":"Great poems and plays were written in Sanskrit. Kalidasa, perhaps India’s most famous poet, wrote the play Abhijnana Shakuntalam and the poem Meghaduta, in which a cloud carries a message. Beautiful paintings on the walls of the Ajanta caves in Maharashtra show stories from the Buddha’s life. Temples began to be built of stone, such as the early temple at Deogarh in Uttar Pradesh."},{"heading":"Learning at Nalanda","text":"Nalanda, in Bihar, grew into one of the world’s greatest centres of learning in this period and after. Students came from China, Korea and other lands to study Buddhism, medicine, mathematics, logic and grammar. Later, the Chinese pilgrim Xuanzang studied there and wrote about its huge libraries and strict entrance tests. Today, a new Nalanda University stands near the ruins of the old one."},{"heading":"Life of ordinary people","text":"Not everyone lived like kings and poets. Most people were farmers, crafts-people and labourers who paid taxes and worked hard. Some groups were treated as untouchable and had to live outside towns, as Faxian noticed. Remembering their lives gives us a fuller and fairer picture of the past."}]'::jsonb, '[{"topic":"History","question":"The Gupta period is often called the…","options":["Iron Age","Golden Age","Dark Age","Stone Age"],"correct_index":1,"explanation":"The Gupta period is often called the Golden Age of ancient India."},{"topic":"History","question":"Which famous astronomer lived in the Gupta period?","options":["Aryabhata","Bhaskara II","C. V. Raman","Ramanujan"],"correct_index":0,"explanation":"Aryabhata, a mathematician and astronomer, lived in the Gupta period."},{"topic":"History","question":"Who wrote Abhijnanashakuntalam?","options":["Banabhatta","Kalidasa","Tulsidas","Kautilya"],"correct_index":1,"explanation":"The poet Kalidasa wrote Abhijnanashakuntalam."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class6-geography', 'The Earth and Us', 'Geography', 'class', 'Class 6', '', 'The Earth in space, globes, maps and landforms.', 2) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-1', 3, 'class6-geography', 'The Earth in the Solar System', 'The Earth in space', 'Geography', 0, 'Look up at the night sky! Let’s find our place among the stars and planets.', '["Stars, like the Sun, give out their own light and heat.","Groups of stars that form patterns are called constellations; the Saptarishi (Big Dipper) is one.","The Pole Star stays in the same place in the sky and shows the north.","The Earth is the third planet from the Sun and the only one known to have life.","The Moon is the Earth’s natural satellite; it has no air or water and shines with the Sun’s light."]'::jsonb, 'From space, the Earth looks blue because water covers most of it; it is called the “blue planet”.', '[{"heading":"Stars and planets","text":"Stars make their own light. Planets do not; they shine because sunlight falls on them. Eight planets go around the Sun in fixed paths called orbits."},{"heading":"Why life is possible on Earth","text":"The Earth is neither too hot nor too cold. It has water and air with oxygen. These conditions let plants, animals and people live."},{"heading":"The Moon and satellites","text":"The Moon goes around the Earth in about 27 days. Man-made satellites, launched by countries like India, also circle the Earth and help with weather forecasts, TV and phones."},{"heading":"The Sun, our star","text":"The Sun is a star, a giant ball of very hot gases. It is about 150 million kilometres away from the Earth, and its light takes about eight minutes to reach us. The Sun gives the Earth light and heat, without which nothing could live. All the planets, their moons and many smaller objects move around the Sun. Together they make up the solar system, which means the family of the Sun."},{"heading":"The eight planets","text":"The planets, in order from the Sun, are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. Mercury is the closest and smallest. Venus is the hottest and is often called the Earth’s twin because it is nearly the same size. Jupiter is the biggest, and Saturn is famous for its beautiful rings. Pluto was once called a planet, but in 2006 scientists decided to call it a dwarf planet."},{"heading":"Other members of the family","text":"Besides planets, the solar system has many smaller bodies. Asteroids are rocky pieces that mostly move around the Sun between Mars and Jupiter, in a belt called the asteroid belt. Comets are balls of ice and dust; when they come near the Sun, they grow long, shining tails. Meteoroids are tiny pieces of rock. When they burn up in our air, we see a streak of light, called a shooting star."},{"heading":"Watching the night sky","text":"On a clear night, away from city lights, you can see thousands of stars. People long ago grouped stars into patterns called constellations, like the Saptarishi (Great Bear), which looks like a big ladle, and Orion, the hunter. Travellers used the Pole Star to find north. The Moon changes its shape every night, from new moon to full moon and back, over about a month."},{"heading":"The Earth, our home","text":"The Earth is the fifth largest planet. Seen from space it looks blue because about two-thirds of it is covered by water. It has just the right temperature, air with oxygen and plenty of water, so plants, animals and people can live here. As far as we know, it is the only planet with life. That is why we must take care of it and keep its air, water and land clean."},{"heading":"Exploring space","text":"India explores space through its space agency, ISRO. It launched its first satellite, Aryabhata, in 1975. Chandrayaan missions have studied the Moon, and in 2023 Chandrayaan-3 landed near the Moon’s south pole. Mangalyaan reached Mars in 2014. These missions help us learn more about our solar system."}]'::jsonb, '[{"topic":"Geography","question":"Which star shows the direction north?","options":["The Sun","The Pole Star","Sirius","The Moon"],"correct_index":1,"explanation":"The Pole Star stays fixed over the north."},{"topic":"Geography","question":"The Earth is which planet from the Sun?","options":["First","Second","Third","Fourth"],"correct_index":2,"explanation":"The Earth is the third planet from the Sun."},{"topic":"Geography","question":"Why does the Moon shine?","options":["It burns like the Sun","It reflects sunlight","It has lights on it","It is a star"],"correct_index":1,"explanation":"The Moon reflects the light of the Sun."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-2', 3, 'class6-geography', 'Globe: latitudes and longitudes', 'The Earth in space', 'Geography', 1, 'A globe is a tiny model of the Earth. Let’s learn the lines drawn on it!', '["The Equator (0°) divides the Earth into the Northern and Southern Hemispheres.","Lines parallel to the Equator are latitudes; the Tropic of Cancer and Tropic of Capricorn are at about 23.5° N and S.","The Torrid Zone near the Equator is the hottest; the Frigid Zones near the poles are the coldest.","Lines from pole to pole are longitudes; the Prime Meridian (0°) passes through Greenwich.","India’s Standard Time is based on 82.5° E."]'::jsonb, 'The Earth’s axis is an imaginary line; the globe is tilted to show it.', '[{"heading":"Lines of latitude","text":"Latitudes are circles that get smaller towards the poles. Important ones are the Equator, the two Tropics, and the Arctic and Antarctic Circles."},{"heading":"Heat zones","text":"The Sun is overhead somewhere between the Tropics, so that belt, the Torrid Zone, is hot. Between the Tropics and the Polar Circles are the mild Temperate Zones, and near the poles are the cold Frigid Zones."},{"heading":"Longitude and time","text":"Places on the same longitude have the same time. As the Earth turns 15° each hour, places to the east see sunrise earlier. That is why countries use a standard time."},{"heading":"What a globe shows","text":"A globe is a small model of the Earth. It shows the shapes of continents and oceans correctly, because the Earth itself is nearly round, like a ball slightly flattened at the poles. A needle runs through the globe at a tilt, showing the Earth’s axis, an imaginary line around which the Earth spins. The two ends of the axis are the North Pole and the South Pole."},{"heading":"Important latitudes","text":"Lines of latitude are measured in degrees from the Equator. The Equator is 0 degrees. The Tropic of Cancer, at about 23.5 degrees north, passes through the middle of India. The Tropic of Capricorn is at about 23.5 degrees south. The Arctic Circle, near the North Pole, and the Antarctic Circle, near the South Pole, are at about 66.5 degrees. The poles themselves are at 90 degrees."},{"heading":"The heat zones","text":"The Sun’s rays fall straight on the area between the two Tropics at some time of the year, so it is hot: this is the Torrid Zone. Near the poles, the Sun’s rays are always slanting and weak, so these areas are very cold: these are the Frigid Zones. Between them are the Temperate Zones, with mild weather. Most of India lies in the Torrid Zone."},{"heading":"Lines of longitude","text":"Lines of longitude, also called meridians, run from the North Pole to the South Pole. Unlike latitudes, they are all the same length. The meridian passing through Greenwich, near London, is taken as 0 degrees and is called the Prime Meridian. There are 180 degrees to its east and 180 degrees to its west. Using both latitude and longitude, we can find the exact location of any place on Earth, like an address."},{"heading":"Time zones and India","text":"The Earth turns 360 degrees in 24 hours, so places 15 degrees apart in longitude have a time difference of one hour. Places to the east see the Sun earlier. India stretches over about 30 degrees of longitude, which could mean a two-hour difference between east and west. To avoid confusion, India uses one standard time, based on 82.5 degrees east, which passes near Mirzapur. Indian Standard Time is 5 hours 30 minutes ahead of Greenwich time."},{"heading":"Using a globe","text":"Try this with a globe: find the Equator, the two Tropics and the Prime Meridian. Then find India and see that the Tropic of Cancer passes through it. Spin the globe slowly from west to east, and imagine how places see sunrise one after another."}]'::jsonb, '[{"topic":"Geography","question":"Which line is at 0° latitude?","options":["Tropic of Cancer","Equator","Prime Meridian","Arctic Circle"],"correct_index":1,"explanation":"The Equator is 0° latitude."},{"topic":"Geography","question":"Which heat zone is the hottest?","options":["Frigid","Temperate","Torrid","Polar"],"correct_index":2,"explanation":"The Torrid Zone, between the Tropics, is hottest."},{"topic":"Geography","question":"The Prime Meridian passes through…","options":["New Delhi","Greenwich","Paris","New York"],"correct_index":1,"explanation":"It passes through Greenwich, near London."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-3', 3, 'class6-geography', 'Day, night and seasons', 'The Earth in space', 'Geography', 2, 'Why does night come, and why is summer hot? The Earth’s two motions explain it!', '["Rotation is the Earth spinning on its axis; one turn takes about 24 hours and gives day and night.","Revolution is the Earth moving around the Sun; one trip takes about 365¼ days.","A leap year has 366 days, with 29 days in February.","Seasons change because the Earth’s axis is tilted.","Around 21 June is the longest day in the Northern Hemisphere; around 22 December is the shortest."]'::jsonb, 'The line between day and night on the globe is called the circle of illumination.', '[{"heading":"Rotation","text":"Only half of the Earth faces the Sun at a time. As the Earth turns, places move from day into night and back again."},{"heading":"Revolution","text":"While spinning, the Earth also travels around the Sun. The extra quarter of a day each year adds up, so every fourth year has one extra day."},{"heading":"Seasons","text":"Because of the tilt, the northern half leans towards the Sun in June (summer) and away in December (winter). On about 21 March and 23 September, day and night are equal everywhere."},{"heading":"Day and night","text":"The Earth spins on its axis from west to east, completing one turn in about 24 hours. This movement is called rotation. At any time, the half of the Earth facing the Sun has day, while the other half has night. The line that separates day and night is called the circle of illumination. If the Earth did not rotate, one side would always be hot and bright and the other always cold and dark."},{"heading":"Why the Sun seems to move","text":"When we watch the Sun rise in the east and set in the west, it looks as if the Sun is moving across the sky. In fact, it is the Earth that is turning. It is like sitting in a moving train: trees outside seem to move backwards, though it is the train that moves. Because the Earth turns from west to east, the Sun appears to move from east to west."},{"heading":"A trip around the Sun","text":"While spinning, the Earth also travels around the Sun in a fixed path called its orbit. One full trip takes 365 days and about 6 hours. This movement is called revolution. We count a year as 365 days and add the extra hours together every four years, making February 29 days long. That year, with 366 days, is called a leap year."},{"heading":"Summer and winter","text":"The Earth’s axis is tilted, always pointing in the same direction in space. So during one part of the year, the Northern Hemisphere leans towards the Sun and gets more direct sunlight and longer days: it is summer there. Around 21 June the Northern Hemisphere has its longest day. Around 22 December, it leans away from the Sun, so days are short and it is winter, while the Southern Hemisphere has summer."},{"heading":"Equal days and nights","text":"On two days of the year, around 21 March and 23 September, the Sun shines directly over the Equator. Neither hemisphere leans towards the Sun, so day and night are almost equal all over the world. These days are called equinoxes. The changing seasons, caused by the tilt and the revolution of the Earth, bring the rhythm of sowing, harvesting and festivals in our lives."},{"heading":"Seasons in India","text":"In India we feel these changes as summer, the rainy season and winter. Our long, hot summer comes in May and June, when the Sun is high overhead in the north. The monsoon follows, and the cool winter months come in December and January."}]'::jsonb, '[{"topic":"Geography","question":"Day and night are caused by the Earth’s…","options":["revolution","rotation","size","shape"],"correct_index":1,"explanation":"Rotation, spinning on its axis, causes them."},{"topic":"Geography","question":"How many days does a leap year have?","options":["364","365","366","367"],"correct_index":2,"explanation":"A leap year has 366 days."},{"topic":"Geography","question":"Why do seasons change?","options":["The Earth’s axis is tilted","The Moon moves","The Sun gets bigger","Clouds block the Sun"],"correct_index":0,"explanation":"The tilt of the axis causes the seasons."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-4', 3, 'class6-geography', 'Maps', 'Maps and the Earth', 'Geography', 3, 'Maps help us find our way. Let’s learn their kinds and their parts!', '["Physical maps show natural features like mountains, rivers and plains.","Political maps show countries, states, cities and borders.","Thematic maps show one topic, like rainfall, roads or forests.","The three parts of a map are distance (scale), direction and symbols.","A sketch is drawn from memory, without scale; a plan is a drawing of a small area, like a house, to scale."]'::jsonb, 'The four main directions are called cardinal points: North, South, East and West.', '[{"heading":"Map or globe?","text":"A globe shows the whole Earth correctly but is hard to carry. A map is flat, can show any area, and can show more detail."},{"heading":"Parts of a map","text":"The scale tells us real distances. An arrow marked N shows north. Symbols, explained in the map key, show things like railways, temples and wells."},{"heading":"Colours on maps","text":"Blue is used for water, brown for mountains, yellow for plateaus and green for plains. These same colours are used on maps all over the world."},{"heading":"Why we need maps","text":"A map is a drawing of the whole or a part of the Earth’s surface on a flat sheet. A globe is useful for seeing the whole Earth, but it is hard to carry and cannot show small details. Maps can show a country, a city, or even your school, in as much detail as we need. Many maps together are put into a book called an atlas."},{"heading":"Kinds of maps","text":"Physical maps show natural features like mountains, plateaus, plains, rivers and oceans. Political maps show countries, states, cities and towns, with their boundaries. Thematic maps focus on one topic, such as rainfall, forests, roads, or where crops are grown. When you look at a map, the first thing to check is its title, so you know what it is showing."},{"heading":"Distance and scale","text":"A real place is much bigger than its map, so distances are reduced. The scale is the ratio between the distance on the map and the actual distance on the ground. For example, 1 centimetre on a map may stand for 1 kilometre on the ground. A large-scale map shows a small area in great detail, like a town, while a small-scale map shows a big area, like a country, with less detail."},{"heading":"Direction and symbols","text":"Most maps have an arrow marked N, showing north. The four main directions, North, South, East and West, are called cardinal points, and between them are north-east, south-east, south-west and north-west. A compass helps us find directions, because its needle always points north. Since there is no space to draw real buildings and roads, maps use symbols. A key, or legend, explains what each symbol means."},{"heading":"Sketches and plans","text":"A sketch is a rough drawing made from memory, without an exact scale, like a quick drawing of the way from your house to school. A plan is a drawing of a small area, such as a room or a building, drawn to scale. Architects use plans to build houses. Learning to read and draw maps, sketches and plans helps us understand places and find our way."},{"heading":"Maps in daily life","text":"We use maps more often than we think. A map on a phone shows the quickest road, a bus route map shows where to get off, and a weather map on TV shows where rain is coming. Pilots, sailors, soldiers, farmers and town planners all depend on maps. Learning to read them carefully is a skill that helps us all our lives."}]'::jsonb, '[{"topic":"Geography","question":"A map showing countries and borders is a…","options":["physical map","political map","thematic map","sketch"],"correct_index":1,"explanation":"Political maps show countries, states and borders."},{"topic":"Geography","question":"On maps, brown colour usually shows…","options":["plains","water","mountains","forests"],"correct_index":2,"explanation":"Brown is used for mountains."},{"topic":"Geography","question":"A drawing made from memory without scale is a…","options":["plan","sketch","globe","atlas"],"correct_index":1,"explanation":"A sketch is drawn from memory, without scale."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-5', 3, 'class6-geography', 'Land, water and air', 'Maps and the Earth', 'Geography', 4, 'The Earth has four “spheres”: rock, water, air and life. Let’s meet them!', '["The lithosphere is the solid rock layer; the hydrosphere is all the water; the atmosphere is the air around us.","The biosphere is the narrow zone where land, water and air meet and life exists.","There are seven continents; Asia is the largest and Australia the smallest.","There are five oceans; the Pacific is the largest.","Air is mostly nitrogen (about 78%) and oxygen (about 21%)."]'::jsonb, 'Asia and Europe together are sometimes called Eurasia.', '[{"heading":"Land","text":"Land covers less than a third of the Earth. It is divided into seven continents: Asia, Africa, North America, South America, Antarctica, Europe and Australia."},{"heading":"Water","text":"Most of the Earth is covered by oceans: the Pacific, Atlantic, Indian, Southern and Arctic. The Indian Ocean is the only ocean named after a country."},{"heading":"Air and life","text":"The atmosphere protects us from the Sun’s harmful rays and keeps the Earth warm. Where land, water and air meet, plants, animals and people live together in the biosphere."},{"heading":"The four realms","text":"The surface of the Earth has four main parts, called realms. The lithosphere is the solid land, the hydrosphere is all the water, and the atmosphere is the blanket of air around the Earth. The biosphere is the narrow zone where these three meet, and where life exists. Plants, animals and people depend on all three realms for food, water and air."},{"heading":"Continents","text":"The great land masses are called continents. Asia is the largest and has the most people; it is separated from Europe by the Ural Mountains. Africa is the second largest, crossed by the Equator, and has the world’s largest hot desert, the Sahara. North and South America are joined by a narrow strip of land. Australia is the smallest continent, and Antarctica, around the South Pole, is covered with thick ice."},{"heading":"Oceans","text":"The oceans are huge water bodies that are connected to each other. The Pacific Ocean is the largest and deepest; its deepest point, the Mariana Trench, is nearly 11 kilometres deep. The Atlantic Ocean is shaped like the letter S. The Indian Ocean is the only ocean named after a country. The Arctic Ocean, around the North Pole, is the smallest. The Southern Ocean surrounds Antarctica."},{"heading":"The air around us","text":"The atmosphere stretches hundreds of kilometres above us, but most air is close to the ground. It is made mostly of nitrogen and oxygen, with small amounts of carbon dioxide and other gases. We breathe oxygen, while plants use carbon dioxide to make food. The atmosphere also protects us from the harmful rays of the Sun and keeps the Earth warm. As we go higher, the air becomes thinner."},{"heading":"Protecting the biosphere","text":"All living things in the biosphere are linked. If forests are cut, animals lose their homes and soil is washed away. If rivers are polluted, fish die and people fall ill. Burning fuels makes the air dirty. By planting trees, saving water, reducing waste and keeping our surroundings clean, we can help protect the land, water and air on which all life depends."},{"heading":"Land and water on the globe","text":"Only about 29 per cent of the Earth’s surface is land; the rest is water. The Northern Hemisphere has much more land than the Southern Hemisphere, which is why it is sometimes called the land hemisphere, while the Southern Hemisphere is called the water hemisphere."}]'::jsonb, '[{"topic":"Geography","question":"The layer of air around the Earth is the…","options":["lithosphere","hydrosphere","atmosphere","biosphere"],"correct_index":2,"explanation":"The atmosphere is the blanket of air."},{"topic":"Geography","question":"Which is the smallest continent?","options":["Europe","Australia","Antarctica","Africa"],"correct_index":1,"explanation":"Australia is the smallest continent."},{"topic":"Geography","question":"Which ocean is named after a country?","options":["Pacific","Atlantic","Indian","Arctic"],"correct_index":2,"explanation":"The Indian Ocean is named after India."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-geo-6', 3, 'class6-geography', 'Mountains, plateaus and plains', 'Maps and the Earth', 'Geography', 5, 'The land is not flat everywhere! Let’s explore the three big landforms.', '["A mountain is land that rises much higher than the land around it.","Young fold mountains, like the Himalayas and Alps, are high with sharp peaks; the Aravallis are very old and worn down.","A plateau is a raised, flat-topped area; the Deccan plateau is one.","Plains are large, flat lands, usually made by rivers; they are good for farming and many people live there.","Plateaus are often rich in minerals, like the Chota Nagpur plateau."]'::jsonb, 'The Tibet plateau is the highest plateau in the world.', '[{"heading":"Mountains","text":"Mountains are cold, with steep slopes and little farmland. Some are covered in snow all year, and rivers start from their glaciers. A line of mountains is called a range."},{"heading":"Plateaus","text":"Plateaus can have steep sides and waterfalls, like the Hundru Falls in Jharkhand. Many have mines of coal, iron and other minerals."},{"heading":"Plains","text":"Rivers carry soil down from mountains and spread it over plains, making them fertile. Building houses, roads and railways is easy on flat land, so plains are crowded, like the Ganga plains."},{"heading":"How landforms are made","text":"The land is shaped by forces inside the Earth and on its surface. Movements inside the Earth can lift up land, fold rocks into mountains, or cause earthquakes. On the surface, wind, water and ice slowly wear away rocks and carry the pieces elsewhere. Over millions of years, these forces have created the mountains, plateaus and plains we see today."},{"heading":"Kinds of mountains","text":"Fold mountains form when rocks are pushed and folded, like the Himalayas and the Alps; young fold mountains have tall, sharp peaks. Block mountains form when large blocks of land are lifted or sink, like the Vosges in Europe. Volcanic mountains, like Mount Kilimanjaro in Africa and Mount Fuji in Japan, form from lava. The Aravalli range in India is one of the oldest fold mountains in the world, now worn down."},{"heading":"Life in the mountains","text":"Mountains are cold, and their slopes are steep, so there is little flat land for farming. People in hills grow crops on terraces cut into slopes. Mountains are a store of water: many rivers begin from glaciers in the mountains. They also have forests, which give wood, fruits and medicines. Mountains attract tourists, and people enjoy activities like trekking and skiing there."},{"heading":"Riches of plateaus","text":"Plateaus are raised areas of land with a flat top. They may have steep sides. The Deccan plateau in India is one of the oldest, and the Tibet plateau is the highest in the world. Plateaus are often rich in minerals: the Chota Nagpur plateau has a lot of iron, coal and manganese. Some plateaus have beautiful waterfalls, like the Hundru Falls in Jharkhand and the Jog Falls in Karnataka."},{"heading":"Plains, the busiest lands","text":"Plains are large stretches of flat land, usually not more than 200 metres above sea level. Most plains are made by rivers, which carry soil from the mountains and spread it out. This soil is very fertile. Because farming, building houses and making roads is easy on flat land, plains are thickly populated. The Ganga–Brahmaputra plains in India are among the most crowded places in the world."},{"heading":"Landforms of India","text":"India has all three major landforms. The Himalayas stand in the north, the great Northern Plains lie in the middle, and the ancient Peninsular plateau covers the south. Each landform has shaped how people live, what they grow and where cities have grown."}]'::jsonb, '[{"topic":"Geography","question":"A raised land with a flat top is a…","options":["mountain","plateau","plain","valley"],"correct_index":1,"explanation":"That is a plateau."},{"topic":"Geography","question":"Which of these are very old mountains?","options":["Himalayas","Alps","Aravallis","Andes"],"correct_index":2,"explanation":"The Aravallis are among the oldest mountains."},{"topic":"Geography","question":"Why do many people live on plains?","options":["They are cold","Fertile land and easy building","They have snow","They are high up"],"correct_index":1,"explanation":"Plains have fertile soil and are easy to build on."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class6-civics', 'Living Together', 'Politics', 'class', 'Class 6', '', 'Diversity, equality, government and earning a living.', 3) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-1', 3, 'class6-civics', 'Understanding diversity', 'Diversity and equality', 'Politics', 0, 'In India, people speak many languages and eat many foods. Let’s celebrate our differences!', '["Diversity means having many different kinds of people, languages, religions, foods and festivals.","India has people of many religions, such as Hinduism, Islam, Christianity, Sikhism, Buddhism and Jainism.","Where people live affects their food, clothes and work, like fish and rice in coastal Kerala.","“Unity in diversity” means living together as one nation despite our differences.","During the freedom struggle, people of all backgrounds fought together against British rule."]'::jsonb, 'The phrase “unity in diversity” was used by Jawaharlal Nehru in his book The Discovery of India.', '[{"heading":"Many ways of living","text":"Children in Ladakh and in Kerala live very differently: different weather, foods, languages and festivals. Yet both are Indian. Learning about each other makes us richer."},{"heading":"Why we are different","text":"Over thousands of years, people moved, traded and settled in new places, bringing their ways of life. Geography also shapes how people live."},{"heading":"Together as one","text":"Our national anthem, flag and Constitution belong to all of us. Respecting other people’s beliefs and customs is how we keep our unity."},{"heading":"Many languages, many festivals","text":"India has hundreds of languages, and the Constitution recognises 22 of them in its Eighth Schedule. In one classroom, children may speak Hindi, Tamil, Bengali, Urdu or Punjabi at home. India also celebrates many festivals: Diwali, Eid, Christmas, Guru Nanak Jayanti, Pongal, Onam, Bihu and many more. People of different faiths often join in each other’s celebrations, sharing sweets and greetings."},{"heading":"Diversity in daily life","text":"Diversity is not only about religion and language. Foods, clothes, music, dances, houses and ways of farming also differ from region to region. A family in Ladakh, where it is cold and dry, wears woollen clothes and eats food that keeps well, while a family in Kerala, near the sea, may eat fish and rice. These differences come from history, geography and the choices people make."},{"heading":"Learning from each other","text":"When people from different backgrounds meet, they learn new things. Many foods we eat today, like tea, potatoes and chillies, came from other lands long ago. Music and art in India mix many traditions. Trade, travel and friendships across communities have made Indian culture richer. Being curious and respectful about others’ ways is the best way to enjoy diversity."},{"heading":"Unity in the freedom struggle","text":"During the struggle for independence, people of all religions, regions and languages joined hands against British rule. Songs, poems and slogans in many languages inspired them. At Jallianwala Bagh in 1919, Hindus, Muslims and Sikhs had gathered together when they were fired upon. Such shared experiences built a feeling that, despite differences, all Indians belonged to one nation."},{"heading":"Our national symbols","text":"The national flag, the national anthem Jana Gana Mana, the national song Vande Mataram and the national emblem remind us of our unity. The Constitution gives every citizen equal rights, whatever their religion, caste or language. Respecting diversity is part of being a good citizen: it means treating everyone fairly, learning about others and standing up when someone is treated badly because they are different."},{"heading":"Diversity in your class","text":"Look around your own classroom. Your friends may speak different languages at home, eat different foods and celebrate different festivals. Ask them about their families and traditions. You will be surprised how much you can learn, and how much you have in common."},{"heading":"Think about it","text":"What would India be like if everyone spoke the same language, ate the same food and celebrated only one festival? Our differences make life more colourful and interesting. Unity does not mean being the same; it means respecting each other and working together."}]'::jsonb, '[{"topic":"Politics","question":"What does diversity mean?","options":["Everyone is the same","Many different kinds of people and ways of life","Only one language","Living alone"],"correct_index":1,"explanation":"Diversity means variety: many different ways of life."},{"topic":"Politics","question":"Who wrote The Discovery of India?","options":["Mahatma Gandhi","Jawaharlal Nehru","Dr B. R. Ambedkar","Rabindranath Tagore"],"correct_index":1,"explanation":"Jawaharlal Nehru wrote it."},{"topic":"Politics","question":"“Unity in diversity” means…","options":["everyone must speak one language","living together as one nation despite differences","staying apart","having one religion"],"correct_index":1,"explanation":"We stay united while being different."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-2', 3, 'class6-civics', 'Prejudice and discrimination', 'Diversity and equality', 'Politics', 1, 'Treating people unfairly because they are different is wrong. Let’s see why.', '["Prejudice means judging people badly before knowing them.","A stereotype is fixing one image on a whole group, like “girls can’t play cricket”.","Discrimination is treating people unfairly because of their religion, caste, gender or how rich they are.","Dr B. R. Ambedkar fought against caste discrimination and helped write the Constitution.","The Constitution says all people are equal, and untouchability is a crime."]'::jsonb, 'Article 17 of the Constitution abolished untouchability.', '[{"heading":"Prejudice and stereotypes","text":"If we think people from one place are lazy or one language is inferior, that is prejudice. Stereotypes stop us from seeing each person as an individual."},{"heading":"When it becomes discrimination","text":"When prejudice makes us act unfairly, such as not letting someone use a well or enter a school, that is discrimination. For centuries, Dalits faced this kind of treatment."},{"heading":"Working for equality","text":"Dr Ambedkar, himself a victim of caste discrimination, studied abroad and became a great leader. The Constitution he helped write gives everyone equal rights."},{"heading":"How prejudice starts","text":"Prejudice often begins when we know very little about other people. We may hear jokes or stories that make fun of a group, or believe what others say without checking. Soon we start thinking that our own way of eating, dressing or praying is the only right way. Prejudice can be about religion, caste, the colour of skin, the region someone comes from, whether they are rich or poor, or whether they are a girl or a boy."},{"heading":"Stereotypes around us","text":"A stereotype is fixing one image on a whole group of people. Saying that girls are not good at sports, that boys should not cry, or that people from a certain region are lazy, are all stereotypes. They are unfair because every person is different. Stereotypes stop people from doing what they are good at, and make others treat them badly. Questioning stereotypes is the first step towards fairness."},{"heading":"When people are treated unfairly","text":"Discrimination happens when we act on prejudice: when someone is not allowed into a temple, not given a job, or made to sit separately because of who they are. For centuries, people of some castes, called Dalits, were treated as untouchable. They were not allowed to use village wells, enter temples or study. Such treatment hurts people’s dignity and keeps them poor."},{"heading":"Dr Ambedkar’s story","text":"Dr B. R. Ambedkar was born into a Dalit family in 1891. As a child, he was not allowed to drink water from the school tap and had to sit apart from other children. Despite this, he studied hard, went abroad to study at universities in the USA and Britain, and became a great lawyer and leader. He fought for the rights of Dalits all his life and led the drafting of India’s Constitution."},{"heading":"Equal rights for all","text":"The Constitution says that all people are equal and that untouchability is a crime. It also gives special help, such as reserved seats in schools and jobs, to groups who faced discrimination for a long time. But laws alone are not enough. Each of us can help by treating everyone with respect, sharing food and play with all, and speaking up when we see someone being treated unfairly."},{"heading":"Think about it","text":"Have you ever been teased or left out because of how you look or where you come from? How did it feel? Remembering such feelings can help us understand others, and make us careful never to treat anyone that way."}]'::jsonb, '[{"topic":"Politics","question":"Judging people badly before knowing them is called…","options":["prejudice","equality","diversity","democracy"],"correct_index":0,"explanation":"That is prejudice."},{"topic":"Politics","question":"Which Article abolished untouchability?","options":["Article 14","Article 17","Article 21","Article 32"],"correct_index":1,"explanation":"Article 17 abolished untouchability."},{"topic":"Politics","question":"“Girls can’t play cricket” is an example of a…","options":["fact","stereotype","law","right"],"correct_index":1,"explanation":"It fixes one image on a whole group: a stereotype."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-3', 3, 'class6-civics', 'What is government?', 'Government', 'Politics', 2, 'Who builds roads and runs schools? The government! Let’s learn how it works.', '["The government makes decisions and laws for the country and makes sure they are followed.","There are three levels: local, state and national (Union).","In a democracy, people choose their leaders by voting in elections.","In a monarchy, a king or queen rules and is not chosen by the people.","In India, every citizen aged 18 or above can vote: this is universal adult franchise."]'::jsonb, 'Women in many countries had to struggle for the right to vote; in India, all adults got it together from the start.', '[{"heading":"What governments do","text":"Governments run hospitals and schools, build roads, protect borders, collect taxes and help people during floods or earthquakes."},{"heading":"Kinds of government","text":"In a democracy, leaders must answer to the people and can be voted out. In a monarchy, the ruler does not have to explain decisions to the people."},{"heading":"Every vote counts","text":"In India, everyone 18 and older can vote, whether rich or poor, man or woman. Elections are held at least every five years."},{"heading":"Why we need a government","text":"Imagine a country with no rules and no one to make decisions. Who would build roads, run schools, protect borders or help during floods? Who would settle quarrels? A government is a group of people who make decisions and laws for the country and make sure they are followed. It also provides services like hospitals, railways and the postal system."},{"heading":"Making and following laws","text":"Governments make laws on many matters, such as how fast vehicles can be driven, how old children must be before they work, and how taxes are paid. Police and courts make sure that laws are followed. If people feel a law is unfair, they can go to court or protest peacefully to change it. In this way, laws are made and changed with the people’s involvement."},{"heading":"Three levels of government","text":"In India, government works at three levels. The local level looks after a village, town or city, through panchayats and municipalities. The state level looks after a whole state, like Maharashtra or Assam. The national, or Union, level looks after the whole country, dealing with matters like defence, foreign affairs and money. Each level has its own powers and responsibilities."},{"heading":"Democracy and other kinds","text":"In a democracy, people choose their leaders through elections, and leaders must explain their decisions to the people. In a monarchy, a king or queen rules, often passing power to their children, and does not have to answer to the people. India is a democracy. Every adult citizen, rich or poor, man or woman, has the right to vote. This is called universal adult franchise."},{"heading":"The struggle for the vote","text":"In many countries, the right to vote was given only to rich men at first. Women and poor people had to struggle for a long time. In Britain and the USA, women campaigners, called suffragettes, marched and protested for the vote. When India became independent, its Constitution gave the vote to every adult from the very first election in 1951–52, a big step for equality."},{"heading":"Government around you","text":"You can see the government at work all around you: in the school you go to, the road outside your house, the ration shop, the post office and the hospital. Every time you see a policeman, a traffic signal or a public bus, you are seeing a part of the government’s work. Think about which level of government is responsible for each one."},{"heading":"Think about it","text":"If you could ask your government for one thing for your area, what would it be? In a democracy, you can raise such questions through your representatives."}]'::jsonb, '[{"topic":"Politics","question":"At what age can a citizen vote in India?","options":["16","18","21","25"],"correct_index":1,"explanation":"Every citizen 18 or older can vote."},{"topic":"Politics","question":"In which system do people choose leaders by voting?","options":["Monarchy","Democracy","Dictatorship","Empire"],"correct_index":1,"explanation":"In a democracy people elect their leaders."},{"topic":"Politics","question":"How many levels of government are there in India?","options":["One","Two","Three","Five"],"correct_index":2,"explanation":"Local, state and national."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-4', 3, 'class6-civics', 'Panchayati Raj', 'Government', 'Politics', 3, 'Villages govern themselves! Let’s visit a Gram Sabha meeting.', '["Panchayati Raj is the system of local self-government in villages.","The Gram Sabha is a meeting of all adults in a village who are voters.","The Gram Panchayat is elected by the people and headed by the Sarpanch (Pradhan).","The Panchayat Secretary keeps records and calls meetings.","There are three levels: Gram Panchayat (village), Panchayat Samiti (block) and Zila Parishad (district)."]'::jsonb, 'At least one-third of seats in panchayats are reserved for women.', '[{"heading":"The Gram Sabha","text":"Every adult voter in the village can attend the Gram Sabha. It discusses village problems, checks the panchayat’s work and approves plans."},{"heading":"The Gram Panchayat","text":"The village is divided into wards, and each ward elects a member (Panch). With the Sarpanch, they form the Gram Panchayat, which looks after wells, roads, drains and schools."},{"heading":"Money and work","text":"The panchayat collects some taxes, like house tax, and gets money from the government for schemes. Elections are held every five years."},{"heading":"Self-government in villages","text":"Most Indians live in villages, and many problems, like a broken hand pump or a muddy road, are best solved locally. Panchayati Raj lets villagers take part in governing themselves. It got a place in the Constitution through the 73rd Amendment in 1992. Panchayat elections are held every five years, and a third of the seats are reserved for women."},{"heading":"Why the Gram Sabha matters","text":"The Gram Sabha is a meeting of all adults in a village who have the right to vote. It is the heart of Panchayati Raj. At its meetings, people discuss village problems, suggest plans, and check what the panchayat has done and how it has spent money. If the Gram Sabha is active, the panchayat must listen to the people and cannot misuse its power."},{"heading":"The Gram Panchayat at work","text":"The village is divided into wards, and each ward elects a member called a Panch. Together with the Sarpanch, or Pradhan, they form the Gram Panchayat. A secretary, appointed by the government, keeps records and calls meetings. The Gram Panchayat builds and repairs roads, wells and drains, looks after schools and community buildings, and carries out government schemes for the village."},{"heading":"Where the money comes from","text":"The panchayat collects some taxes, such as house tax and market tax. It also gets money from the state and Union governments for schemes such as building roads, toilets and houses, or providing work under MGNREGA. The Gram Sabha must approve plans, and the panchayat must show the accounts. This helps make sure that money meant for the village is spent properly."},{"heading":"Three levels of Panchayati Raj","text":"Panchayati Raj works at three levels. The Gram Panchayat is at the village level. Many Gram Panchayats together form a Panchayat Samiti at the block level. All the Panchayat Samitis of a district form the Zila Parishad at the district level. These bodies plan development work for their area and connect villagers with the state government, so that decisions are made close to the people."},{"heading":"A day at the Gram Sabha","text":"Imagine a Gram Sabha meeting under a big tree. Villagers complain that the well has dried up. The Sarpanch suggests digging a new well, and the secretary reads out how much money is available. People vote, and the work is approved. This is democracy in action, close to home."},{"heading":"Women in panchayats","text":"Because a third of the seats are reserved for women, lakhs of women now serve as Panches and Sarpanches across India. Many have brought clean water, toilets and schools to their villages, and inspired other women to take part in public life."}]'::jsonb, '[{"topic":"Politics","question":"Who heads the Gram Panchayat?","options":["The Collector","The Sarpanch","The MLA","The Mayor"],"correct_index":1,"explanation":"The Sarpanch (Pradhan) heads it."},{"topic":"Politics","question":"A meeting of all adult voters of a village is the…","options":["Gram Sabha","Zila Parishad","Lok Sabha","Panchayat Samiti"],"correct_index":0,"explanation":"That is the Gram Sabha."},{"topic":"Politics","question":"The district level of Panchayati Raj is the…","options":["Gram Panchayat","Panchayat Samiti","Zila Parishad","Gram Sabha"],"correct_index":2,"explanation":"The Zila Parishad works at the district level."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-5', 3, 'class6-civics', 'Local government in cities', 'Government', 'Politics', 4, 'Who cleans the streets and lights them at night in a city? Let’s find out!', '["Big cities have a Municipal Corporation; smaller towns have a Municipal Council.","A city is divided into wards, and each ward elects a councillor.","Councillors make decisions together; many cities have a Mayor.","The Commissioner and officers carry out the work.","Municipal bodies look after water, garbage, street lights, parks and local hospitals, paid for by taxes like property tax."]'::jsonb, 'Local government in cities got a place in the Constitution through the 74th Amendment (1992).', '[{"heading":"Who does what","text":"Councillors are elected by the people of their ward and decide what the city needs. Officers led by the Commissioner make it happen."},{"heading":"Daily services","text":"Collecting garbage, supplying water, repairing roads and running schools and dispensaries are all jobs of the municipality."},{"heading":"Citizens can help","text":"People can complain to their councillor when services fail, and can help keep the city clean by separating dry and wet waste."},{"heading":"Running a city","text":"A city has many needs: clean water, garbage collection, street lights, roads, drains, parks and hospitals. These are looked after by the local government of the city. Big cities, like Mumbai, Delhi and Chennai, have a Municipal Corporation. Smaller towns have a Municipal Council. Local government in cities was given a place in the Constitution by the 74th Amendment in 1992."},{"heading":"Councillors and wards","text":"A city is divided into smaller areas called wards. People in each ward elect a councillor. The councillors meet together to decide what the city needs, such as where a new park or hospital should be built, and how much money should be spent on each work. In many cities, a Mayor is chosen to lead the corporation. Councillors are the people’s link with the city government."},{"heading":"Officers who do the work","text":"The decisions made by councillors are carried out by officers and workers. The Commissioner heads the administration and is appointed by the state government. Engineers, doctors, sanitation workers, gardeners and many others work under them. Sanitation workers who sweep the streets and collect waste do one of the most important jobs, keeping the city clean and healthy."},{"heading":"Paying for city services","text":"The municipality needs money for all its work. It collects property tax from people who own houses and buildings, and other taxes like water tax. Richer people with bigger houses pay more tax. It also gets money from the state government. When citizens pay their taxes honestly, the city has money to provide better services to everyone."},{"heading":"Citizens can make a difference","text":"People can tell their councillor about problems, file complaints and take part in meetings. Sometimes residents come together to demand clean water or garbage collection, and this pressure brings results. Citizens can also help by separating wet and dry waste, not throwing garbage on roads, saving water and reporting broken street lights. A clean, safe city needs both a good government and responsible citizens."},{"heading":"A city’s garbage problem","text":"Cities produce huge amounts of garbage every day. If it is not collected and treated properly, streets become dirty, drains get blocked and diseases spread. Many cities now separate wet waste, which can be turned into compost, from dry waste, like plastic and paper, which can be recycled. When citizens help by sorting their waste at home, cities become cleaner and healthier."},{"heading":"Think about it","text":"Who sweeps the road outside your home, and who brings water to your tap? Find out which ward you live in and who your councillor is. Knowing them helps you get problems solved faster."}]'::jsonb, '[{"topic":"Politics","question":"Big cities are run by a…","options":["Gram Panchayat","Municipal Corporation","Zila Parishad","Lok Sabha"],"correct_index":1,"explanation":"Big cities have a Municipal Corporation."},{"topic":"Politics","question":"Who represents a ward in a city?","options":["A councillor","A Sarpanch","An MP","A judge"],"correct_index":0,"explanation":"Each ward elects a councillor."},{"topic":"Politics","question":"Which tax helps pay for city services?","options":["Property tax","Customs duty","Income tax only","GST only"],"correct_index":0,"explanation":"Municipalities collect property tax."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class6-civics-6', 3, 'class6-civics', 'Livelihoods in villages and cities', 'Earning a living', 'Politics', 5, 'How do people earn a living? Let’s meet farmers, vendors and factory workers!', '["Most people in villages depend on farming and related work.","Some farmers own land; landless labourers work on other people’s fields for wages.","Many farmers take loans for seeds and fertilisers and can fall into debt if crops fail.","In cities, people work as street vendors, shopkeepers, factory workers, drivers and office staff.","Workers with a permanent job get a regular salary and benefits like leave and medical care; casual workers do not."]'::jsonb, 'Fishing, weaving, pottery and dairy are also important village livelihoods.', '[{"heading":"Life in the village","text":"Farmers grow crops, keep animals and sell what they can. Small farmers often need loans, and poor rains can make life very hard."},{"heading":"Life in the city","text":"Street vendors sell vegetables, toys and snacks. Factory and construction workers often have no fixed job. Others work in offices, shops and hospitals."},{"heading":"Fair work","text":"A permanent job gives a monthly salary, a pension and paid holidays. Casual workers are paid only for the days they work, so their income is uncertain."},{"heading":"Life of a farmer","text":"Most people in villages depend on farming. Some farmers own large plots and hire workers; many own only small plots. Small farmers often need loans to buy seeds, fertilisers and pesticides. If the rains fail or prices fall, they may not be able to repay, and fall into debt. Farmers also keep cattle and buffaloes for milk, and many grow vegetables to sell in nearby markets."},{"heading":"Landless labourers","text":"Many villagers do not own any land. They work as labourers on other people’s fields for daily wages. They get work mostly at the time of sowing and harvesting, and may have no work for several months. During those months, some migrate to towns to work at construction sites or brick kilns. Their income is low and uncertain, and they often struggle to meet basic needs."},{"heading":"Other village work","text":"Apart from farming, villagers earn a living in many ways. Some are fishers, potters, weavers, carpenters, blacksmiths or basket makers. Others run small shops, repair cycles or drive tractors. Women often work in fields, look after animals and also do all the housework. Many families depend on more than one kind of work to make ends meet."},{"heading":"Working in cities","text":"In cities, many people work on the streets: vegetable sellers, rickshaw pullers, tea sellers, cobblers and newspaper vendors. They are self-employed and work long hours without fixed pay. Others work in factories, offices, shops, hospitals and schools. Some run businesses, small or large. Every day, cities need the work of millions of people to keep running."},{"heading":"Permanent and casual work","text":"Workers with permanent jobs, such as government employees or workers in big companies, get a regular salary, paid holidays, medical help and pensions. Casual workers, like daily-wage labourers in markets or factories, are paid only for the days they work and can lose their jobs easily. Understanding these differences helps us see why fair wages and safe working conditions matter for everyone."},{"heading":"Dignity of labour","text":"Every kind of honest work is important, whether it is farming, sweeping streets, teaching or running a business. Society depends on all workers. Treating every worker with respect, paying fair wages and ensuring safe conditions are signs of a fair and caring society."},{"heading":"Think about it","text":"Talk to someone who works near your home, such as a vegetable seller, a watchman or a farmer. Ask them about their day, their work hours and the problems they face. You will learn how hard many people work to earn a living."}]'::jsonb, '[{"topic":"Politics","question":"People who work on others’ fields for wages are…","options":["landowners","landless labourers","shopkeepers","officers"],"correct_index":1,"explanation":"Landless labourers work for wages."},{"topic":"Politics","question":"Which of these is a benefit of a permanent job?","options":["No salary","Paid leave and medical care","Work only some days","No holidays"],"correct_index":1,"explanation":"Permanent jobs give regular pay and benefits."},{"topic":"Politics","question":"Most people in villages depend on…","options":["farming","factories","offices","shipping"],"correct_index":0,"explanation":"Farming is the main village livelihood."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class7-history', 'Kings and Kingdoms', 'History', 'class', 'Class 7', '', 'New kingdoms, the Delhi Sultans, the Mughals and after.', 4) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-1', 3, 'class7-history', 'Sources and new kingdoms', 'New kingdoms', 'History', 0, 'How do we know what happened a thousand years ago? Let’s become history detectives!', '["Historians learn about the past from coins, inscriptions, buildings and handwritten books called manuscripts.","Manuscripts were copied by hand, so small changes crept in over time.","From the 7th century, new ruling families, such as the Rajputs, rose to power.","The Cholas of Tamil Nadu built the huge Brihadeeswarar temple at Thanjavur.","Kings gave land grants to Brahmanas and temples, recorded on copper plates."]'::jsonb, 'Paper became cheaper and more common in India from about the 13th century.', '[{"heading":"Clues from the past","text":"Inscriptions on stone and copper, coins and temple walls tell us about kings and their gifts. Travellers’ accounts and chronicles written in courts add more details."},{"heading":"New rulers","text":"Powerful landlords and warriors became kings, such as the Rajput clans, the Palas of Bengal and the Rashtrakutas of the Deccan. They often fought over rich cities like Kannauj."},{"heading":"The Cholas","text":"The Chola kings Rajaraja I and Rajendra I built a strong kingdom with a navy. Their temples were centres of art and village life, and their bronze statues are famous."}]'::jsonb, '[{"topic":"History","question":"Handwritten old books are called…","options":["inscriptions","manuscripts","coins","maps"],"correct_index":1,"explanation":"Handwritten books are manuscripts."},{"topic":"History","question":"The Brihadeeswarar temple is at…","options":["Madurai","Thanjavur","Hampi","Delhi"],"correct_index":1,"explanation":"It was built by the Cholas at Thanjavur."},{"topic":"History","question":"Land grants were often recorded on…","options":["copper plates","paper only","cloth","leaves only"],"correct_index":0,"explanation":"Many grants were written on copper plates."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-2', 3, 'class7-history', 'The Delhi Sultans', 'New kingdoms', 'History', 1, 'Delhi became a capital of a big empire. Let’s meet the Sultans!', '["Delhi first became an important capital under the Tomara Rajputs and the Chauhans.","The Delhi Sultanate began in 1206 and lasted until 1526.","Its dynasties were the Mamluks (Slave dynasty), Khaljis, Tughlaqs, Sayyids and Lodis.","Razia Sultan was the only woman to rule as Sultan of Delhi.","Alauddin Khalji controlled market prices; Muhammad bin Tughlaq moved the capital to Daulatabad for a time."]'::jsonb, 'The Qutb Minar in Delhi was begun by Qutb-ud-din Aibak and finished by Iltutmish.', '[{"heading":"A new capital","text":"After Muhammad Ghori’s victory, his general Qutb-ud-din Aibak became the first Sultan. Over the next 300 years, five dynasties ruled from Delhi."},{"heading":"Ruling a big land","text":"Sultans gave land, called iqtas, to military commanders, who collected taxes and kept soldiers. Alauddin Khalji kept a large army to fight Mongol attacks."},{"heading":"The end of the Sultanate","text":"The last Sultan, Ibrahim Lodi, was defeated by Babur at the First Battle of Panipat in 1526, and the Mughal Empire began."}]'::jsonb, '[{"topic":"History","question":"Who was the only woman Sultan of Delhi?","options":["Nur Jahan","Razia Sultan","Rani Durgavati","Mumtaz"],"correct_index":1,"explanation":"Razia Sultan ruled from 1236 to 1240."},{"topic":"History","question":"Who finished building the Qutb Minar?","options":["Aibak","Iltutmish","Balban","Akbar"],"correct_index":1,"explanation":"Iltutmish completed the Qutb Minar."},{"topic":"History","question":"Land given to commanders by the Sultans was called…","options":["iqta","mansab","jagir","zamindari"],"correct_index":0,"explanation":"Such land was called an iqta."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-3', 3, 'class7-history', 'The Mughal Empire', 'The Mughals', 'History', 2, 'The Mughals ruled a huge empire for over 200 years. Let’s meet the great emperors!', '["Babur founded the Mughal Empire after the First Battle of Panipat (1526).","Akbar ruled from 1556 to 1605 and is famous for his fair policies.","Akbar gave officers ranks called mansabs, and talked with people of all religions; his idea of peace for all was sulh-i kul.","Jahangir, Shah Jahan and Aurangzeb ruled after Akbar.","Shah Jahan built the Taj Mahal at Agra and the Red Fort in Delhi."]'::jsonb, 'Abul Fazl wrote the Akbarnama, a history of Akbar’s rule.', '[{"heading":"Founding the empire","text":"Babur came from Central Asia. His son Humayun lost the throne to Sher Shah Suri but won it back. Humayun’s son Akbar made the empire large and strong."},{"heading":"How the Mughals ruled","text":"Officers called mansabdars held ranks and kept soldiers. Land revenue was carefully measured under Todar Mal. Akbar married into Rajput families and gave them high posts."},{"heading":"After Aurangzeb","text":"Aurangzeb ruled the largest Mughal empire, but long wars weakened it. After his death in 1707, many governors became independent."}]'::jsonb, '[{"topic":"History","question":"Who founded the Mughal Empire?","options":["Akbar","Babur","Humayun","Shah Jahan"],"correct_index":1,"explanation":"Babur founded it in 1526."},{"topic":"History","question":"Akbar’s idea of “peace with all” was called…","options":["sulh-i kul","jizya","iqta","zabt"],"correct_index":0,"explanation":"It was called sulh-i kul."},{"topic":"History","question":"Who built the Taj Mahal?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"correct_index":2,"explanation":"Shah Jahan built it for Mumtaz Mahal."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-4', 3, 'class7-history', 'Forts, temples and tombs', 'The Mughals', 'History', 3, 'Kings built amazing buildings to show their power. Let’s go sightseeing!', '["Rulers built temples, mosques, forts, tombs and gardens.","Arches and domes came into wide use in India from the 13th century.","The Mughals made gardens in the charbagh style, divided into four parts.","Humayun’s Tomb in Delhi inspired the design of the Taj Mahal.","Fatehpur Sikri, built by Akbar, has the huge Buland Darwaza gate."]'::jsonb, 'The Kandariya Mahadeva temple at Khajuraho was built by the Chandela kings.', '[{"heading":"Temples","text":"Kings built grand temples to show devotion and power, like the temples at Khajuraho and Thanjavur. Temples were also centres of learning, music and dance."},{"heading":"Mosques and tombs","text":"Builders used arches and domes. The Mughals built large mosques, like the Jama Masjid in Delhi, and tombs set in gardens."},{"heading":"Forts and cities","text":"The Red Fort, Agra Fort and Fatehpur Sikri show Mughal skill in red sandstone and white marble. Many of these are now World Heritage Sites."}]'::jsonb, '[{"topic":"History","question":"A Mughal garden divided into four parts is called…","options":["charbagh","baoli","mandapa","mihrab"],"correct_index":0,"explanation":"A charbagh is a four-part garden."},{"topic":"History","question":"The Buland Darwaza is at…","options":["Agra","Fatehpur Sikri","Delhi","Lahore"],"correct_index":1,"explanation":"It is the great gate at Fatehpur Sikri."},{"topic":"History","question":"The Khajuraho temples were built by the…","options":["Cholas","Chandelas","Mughals","Marathas"],"correct_index":1,"explanation":"The Chandela kings built them."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-5', 3, 'class7-history', 'Devotional paths to God', 'Culture and new powers', 'History', 4, 'Saints sang songs of love for God in simple words. Let’s listen!', '["The Bhakti movement taught that anyone can reach God through love and devotion.","The Alvars (devotees of Vishnu) and Nayanars (devotees of Shiva) sang in Tamil.","Kabir taught that God is one and criticised empty rituals.","Guru Nanak founded Sikhism; his teachings are in the Guru Granth Sahib.","Sufi saints, like Khwaja Moinuddin Chishti of Ajmer, taught love and service to all."]'::jsonb, 'Mirabai, a Rajput princess, was a devotee of Krishna and wrote many bhajans.', '[{"heading":"Love over ritual","text":"Bhakti saints sang in the languages of ordinary people. They said caste and wealth do not matter to God."},{"heading":"Saints of many regions","text":"Basavanna in Karnataka, Namdev and Tukaram in Maharashtra, Chaitanya in Bengal and Kabir in the north spread these ideas."},{"heading":"The Sufis","text":"Sufis were Muslim mystics. Their dargahs, such as at Ajmer and Nizamuddin in Delhi, are visited by people of all religions."}]'::jsonb, '[{"topic":"History","question":"Who founded Sikhism?","options":["Kabir","Guru Nanak","Tukaram","Basavanna"],"correct_index":1,"explanation":"Guru Nanak founded Sikhism."},{"topic":"History","question":"The Nayanars were devotees of…","options":["Vishnu","Shiva","Krishna","Rama"],"correct_index":1,"explanation":"The Nayanars sang for Shiva."},{"topic":"History","question":"Mirabai was a devotee of…","options":["Shiva","Krishna","the Buddha","Mahavira"],"correct_index":1,"explanation":"Mirabai sang bhajans for Krishna."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-history-6', 3, 'class7-history', 'New powers of the 18th century', 'Culture and new powers', 'History', 5, 'As the Mughals grew weak, new kingdoms rose. Let’s meet them!', '["After 1707, Mughal governors set up their own states, like Hyderabad, Awadh and Bengal.","Shivaji built a Maratha kingdom and was crowned Chhatrapati in 1674.","Later, the Peshwas led the Marathas from Pune.","Maharaja Ranjit Singh united the Sikhs and made Lahore his capital in 1799.","The Jats under Suraj Mal grew powerful around Bharatpur."]'::jsonb, 'The Marathas lost the Third Battle of Panipat to Ahmad Shah Abdali in 1761.', '[{"heading":"Breaking away","text":"Governors in Hyderabad, Awadh and Bengal still sent gifts to Delhi but ruled almost on their own."},{"heading":"The Marathas","text":"Shivaji fought the Mughals with hill forts and quick cavalry. Under the Peshwas, Maratha power spread across much of India."},{"heading":"The Sikhs and Jats","text":"Sikh groups called misls joined under Ranjit Singh. In the region around Delhi and Agra, the Jats became strong."}]'::jsonb, '[{"topic":"History","question":"Who made Lahore his capital in 1799?","options":["Shivaji","Ranjit Singh","Suraj Mal","Baji Rao"],"correct_index":1,"explanation":"Maharaja Ranjit Singh."},{"topic":"History","question":"When was Shivaji crowned Chhatrapati?","options":["1526","1674","1707","1761"],"correct_index":1,"explanation":"Shivaji was crowned in 1674."},{"topic":"History","question":"The Peshwas led the Marathas from…","options":["Delhi","Pune","Lahore","Hyderabad"],"correct_index":1,"explanation":"The Peshwas ruled from Pune."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class7-geography', 'Our Environment', 'Geography', 'class', 'Class 7', '', 'The Earth inside and out, air, water and vegetation.', 5) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-1', 3, 'class7-geography', 'What is environment?', 'Our environment', 'Geography', 0, 'Everything around us, living or not, is our environment. Let’s look closer!', '["The environment is everything around us: land, water, air, plants, animals and people.","The natural environment includes land, water, air and living things.","The human-made environment includes buildings, roads, bridges and factories.","An ecosystem is a community of living things linked with their surroundings, like a pond or a forest.","World Environment Day is celebrated on 5 June."]'::jsonb, 'The four domains of the natural environment are the lithosphere, hydrosphere, atmosphere and biosphere.', '[{"heading":"Natural and human-made","text":"Rivers, forests and mountains are natural. People change nature to meet their needs: they build houses, grow crops and make roads. This is the human environment."},{"heading":"Ecosystems","text":"In a pond, fish eat insects, frogs eat fish, and plants make food from sunlight. Every living thing depends on others and on its surroundings."},{"heading":"Keeping a balance","text":"Cutting forests, polluting rivers and wasting resources upset this balance. Saving the environment means living without harming nature."}]'::jsonb, '[{"topic":"Geography","question":"World Environment Day is on…","options":["5 June","22 April","16 September","21 March"],"correct_index":0,"explanation":"It is celebrated on 5 June."},{"topic":"Geography","question":"Which of these is human-made?","options":["A river","A forest","A bridge","A mountain"],"correct_index":2,"explanation":"Bridges are built by people."},{"topic":"Geography","question":"A pond with its plants and animals is an example of…","options":["an ecosystem","a plateau","a glacier","a desert"],"correct_index":0,"explanation":"It is a small ecosystem."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-2', 3, 'class7-geography', 'Inside our Earth', 'Our environment', 'Geography', 1, 'Let’s peel the Earth like an onion and see its layers and rocks!', '["The Earth has three layers: crust, mantle and core.","The crust is the thinnest layer; under the oceans it is made mainly of silica and magnesium (sima), and on the continents of silica and alumina (sial).","The core is made mainly of nickel and iron (nife).","Igneous rocks form from cooled molten rock; sedimentary rocks form in layers; metamorphic rocks are changed by heat and pressure.","Clay changes into slate, and limestone into marble."]'::jsonb, 'The deepest mine in the world is in South Africa, yet it reaches only a tiny distance into the Earth.', '[{"heading":"The layers","text":"The crust is like the skin of an apple. Below it lies the mantle, and at the centre is the very hot core."},{"heading":"Rocks and minerals","text":"Rocks are made of minerals. Granite and basalt are igneous rocks; sandstone is sedimentary; marble and slate are metamorphic."},{"heading":"Uses of rocks","text":"We use rocks for building roads and houses, and stones for jewellery and statues. Fossils in rocks tell us about life long ago."}]'::jsonb, '[{"topic":"Geography","question":"Which is the innermost layer of the Earth?","options":["Crust","Mantle","Core","Soil"],"correct_index":2,"explanation":"The core is at the centre."},{"topic":"Geography","question":"Limestone changes into…","options":["slate","marble","granite","basalt"],"correct_index":1,"explanation":"Heat and pressure turn limestone into marble."},{"topic":"Geography","question":"Granite is an example of which rock?","options":["Igneous","Sedimentary","Metamorphic","Fossil"],"correct_index":0,"explanation":"Granite forms from cooled molten rock."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-3', 3, 'class7-geography', 'Our changing Earth', 'Our environment', 'Geography', 2, 'Rivers, wind, waves and ice keep reshaping the land. Let’s watch them at work!', '["Earthquakes and volcanoes are sudden movements inside the Earth.","Erosion is the wearing away of land by water, wind or ice; deposition is the laying down of the eroded material.","A river winding through flat land forms loops called meanders; a cut-off loop becomes an ox-bow lake.","Sea waves make sea caves, arches and stacks; glaciers carry rocks and leave piles called moraines.","In deserts, wind makes sand dunes."]'::jsonb, 'Angel Falls in Venezuela is the highest waterfall in the world.', '[{"heading":"Sudden changes","text":"When plates of the crust move suddenly, the ground shakes in an earthquake. Molten rock may burst out through a volcano."},{"heading":"Work of rivers","text":"A river falling over hard rock forms a waterfall. On plains it winds in meanders. Near the sea it splits into streams and forms a delta."},{"heading":"Waves, ice and wind","text":"Waves carve the coast and build beaches. Glaciers dig valleys. In deserts, wind blows sand into dunes and carves mushroom-shaped rocks."}]'::jsonb, '[{"topic":"Geography","question":"A cut-off loop of a river becomes…","options":["a delta","an ox-bow lake","a dune","a stack"],"correct_index":1,"explanation":"It becomes an ox-bow lake."},{"topic":"Geography","question":"Rocks left behind by a glacier are called…","options":["moraines","meanders","stacks","beaches"],"correct_index":0,"explanation":"They are moraines."},{"topic":"Geography","question":"Sand dunes are made mainly by…","options":["rivers","wind","glaciers","waves"],"correct_index":1,"explanation":"Wind blows sand into dunes."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-4', 3, 'class7-geography', 'Air', 'Air and water', 'Geography', 3, 'We can’t see air, but it surrounds us and keeps us alive. Let’s learn about it!', '["Air is mostly nitrogen (about 78%) and oxygen (about 21%).","The atmosphere has five layers; we live in the lowest, the troposphere.","The ozone layer in the stratosphere protects us from harmful rays.","Weather is the day-to-day condition of the air; climate is the average weather over many years.","Wind blows from high pressure to low pressure."]'::jsonb, 'A barometer measures air pressure, and a rain gauge measures rainfall.', '[{"heading":"Why air matters","text":"We breathe oxygen, plants use carbon dioxide, and air keeps the Earth warm. Too much carbon dioxide from burning fuel is warming the Earth."},{"heading":"Weather and climate","text":"Temperature, air pressure, wind, humidity and rain make up the weather. When we describe the usual weather of a place over many years, we describe its climate."},{"heading":"Moisture and rain","text":"The amount of water vapour in the air is humidity. When moist air rises and cools, it forms clouds, and then rain, snow or hail."}]'::jsonb, '[{"topic":"Geography","question":"Which layer of the atmosphere do we live in?","options":["Stratosphere","Troposphere","Mesosphere","Exosphere"],"correct_index":1,"explanation":"We live in the troposphere."},{"topic":"Geography","question":"Air pressure is measured with a…","options":["thermometer","barometer","rain gauge","compass"],"correct_index":1,"explanation":"A barometer measures air pressure."},{"topic":"Geography","question":"The average weather of a place over many years is its…","options":["season","climate","humidity","pressure"],"correct_index":1,"explanation":"That is climate."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-5', 3, 'class7-geography', 'Water', 'Air and water', 'Geography', 4, 'Water keeps moving around the Earth in a big circle. Let’s follow it!', '["In the water cycle, water evaporates, forms clouds, falls as rain and flows back to the sea.","Most of the Earth’s water is salty; very little is fresh water we can use.","The rise and fall of the sea twice a day is called a tide.","Ocean currents are streams of water flowing in the oceans, warm or cold.","A tsunami is a huge wave caused by an earthquake under the sea."]'::jsonb, 'World Water Day is celebrated on 22 March.', '[{"heading":"The water cycle","text":"The Sun heats water in seas and lakes, and it rises as vapour. High up it cools into clouds and falls as rain or snow. Rivers carry it back to the sea."},{"heading":"Tides and waves","text":"The pull of the Moon causes tides: high tide when water rises, low tide when it falls. Wind makes waves on the surface."},{"heading":"Currents","text":"Warm currents carry heat from near the Equator, and cold currents come from the poles. Where they meet, there is fog and good fishing."}]'::jsonb, '[{"topic":"Geography","question":"Tides are caused mainly by the pull of…","options":["the wind","the Moon","the rivers","the clouds"],"correct_index":1,"explanation":"The Moon’s gravity causes tides."},{"topic":"Geography","question":"World Water Day is on…","options":["5 June","22 March","1 May","14 November"],"correct_index":1,"explanation":"It is celebrated on 22 March."},{"topic":"Geography","question":"Water turning into vapour is called…","options":["condensation","evaporation","rain","freezing"],"correct_index":1,"explanation":"That is evaporation."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-geo-6', 3, 'class7-geography', 'Forests and grasslands of the world', 'Air and water', 'Geography', 5, 'From thick jungles to endless grasslands, let’s travel the world’s natural vegetation!', '["Natural vegetation depends mostly on temperature and rainfall.","Tropical evergreen forests are thick and green all year; tropical deciduous forests shed leaves in the dry season.","Coniferous forests of tall, cone-shaped trees like pine grow in cold northern lands; in Russia they are called the taiga.","Grasslands have different names: prairies (North America), pampas (South America), steppes (Central Asia) and savanna (Africa).","Thorny bushes grow in deserts, and mosses and lichens in the cold tundra."]'::jsonb, 'Grasslands in South Africa are called velds, and in Australia downs.', '[{"heading":"Forests","text":"Heavy rain and heat give thick evergreen forests, like the Amazon. Moderate rain gives deciduous forests with teak and sal. Cold lands have coniferous forests, used for paper and wood."},{"heading":"Grasslands","text":"Where there is not enough rain for trees, grass grows. The savanna of Africa is home to lions, zebras and elephants."},{"heading":"Deserts and tundra","text":"Desert plants like cactus store water and have thorns. In the very cold tundra, only small plants grow during the short summer."}]'::jsonb, '[{"topic":"Geography","question":"Grasslands of North America are called…","options":["pampas","prairies","steppes","downs"],"correct_index":1,"explanation":"They are called prairies."},{"topic":"Geography","question":"The African grassland with lions and zebras is the…","options":["savanna","taiga","tundra","veld"],"correct_index":0,"explanation":"That is the savanna."},{"topic":"Geography","question":"Coniferous forests in Russia are called…","options":["taiga","prairie","pampas","mangrove"],"correct_index":0,"explanation":"They are called the taiga."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class7-civics', 'Democracy and Us', 'Politics', 'class', 'Class 7', '', 'Equality, health, state government, media and markets.', 6) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-1', 3, 'class7-civics', 'Equality in democracy', 'Equality', 'Politics', 0, 'In a democracy, everyone is equal. Let’s see what that really means!', '["Every adult citizen has one vote, rich or poor: this is universal adult franchise.","The Constitution says all persons are equal before the law (Article 14).","No one can be discriminated against because of religion, caste, race, sex or place of birth (Article 15).","The Midday Meal Scheme gives cooked lunch to children in government schools; Tamil Nadu was a pioneer.","Rosa Parks of the USA refused to give up her bus seat in 1955, starting a famous fight for equal rights."]'::jsonb, 'Equality also means equal dignity: treating every person with respect.', '[{"heading":"Equal vote, equal rights","text":"In elections, the vote of a famous film star counts the same as the vote of a farm worker. The law treats everyone the same way."},{"heading":"Making equality real","text":"Laws alone are not enough. The government runs schemes like the Midday Meal, which brought more children, especially girls and poor children, to school."},{"heading":"Struggles elsewhere","text":"In the USA, African-Americans fought unfair laws in the Civil Rights Movement. Rosa Parks’ protest helped bring the Civil Rights Act of 1964."}]'::jsonb, '[{"topic":"Politics","question":"Which Article says all are equal before the law?","options":["Article 14","Article 21","Article 32","Article 51A"],"correct_index":0,"explanation":"Article 14 guarantees equality before the law."},{"topic":"Politics","question":"Rosa Parks is famous for…","options":["writing the Constitution","refusing to give up her bus seat","winning an election","climbing Everest"],"correct_index":1,"explanation":"Her bus protest in 1955 fought unfair laws."},{"topic":"Politics","question":"The Midday Meal Scheme gives…","options":["free books","cooked lunch in government schools","free bus rides","money to teachers"],"correct_index":1,"explanation":"It gives cooked lunch to schoolchildren."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-2', 3, 'class7-civics', 'Health and the government', 'Government and us', 'Politics', 1, 'Everyone deserves good health care. Let’s see how the government helps.', '["Health means being free of illness and also being well in body and mind.","Public health services are run by the government; private services are run by individuals or companies.","Public hospitals give free or low-cost treatment.","The right to life (Article 21) includes a right to health care, as courts have held.","Clean water and sanitation prevent many diseases like diarrhoea and cholera."]'::jsonb, 'A Primary Health Centre (PHC) serves a group of villages.', '[{"heading":"Public and private","text":"A government health centre or hospital should treat everyone, even those who cannot pay. Private clinics charge fees and may be costly."},{"heading":"Reaching everyone","text":"Many villages still have few doctors. Health workers, PHCs and district hospitals form a chain so that care can reach rural areas."},{"heading":"Prevention is better than cure","text":"Clean drinking water, toilets, vaccinations and good food stop many diseases before they start. These need the government and citizens to work together."}]'::jsonb, '[{"topic":"Politics","question":"Health services run by the government are called…","options":["private","public","foreign","secret"],"correct_index":1,"explanation":"They are public health services."},{"topic":"Politics","question":"Which Article, the right to life, includes health care?","options":["Article 14","Article 17","Article 21","Article 44"],"correct_index":2,"explanation":"Article 21 has been read to include health."},{"topic":"Politics","question":"A PHC is a…","options":["Primary Health Centre","Public Highway Corporation","Police Head Camp","Private Hospital Chain"],"correct_index":0,"explanation":"PHC stands for Primary Health Centre."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-3', 3, 'class7-civics', 'How the state government works', 'Government and us', 'Politics', 2, 'Each state has its own government. Let’s visit a Legislative Assembly!', '["Each state is divided into constituencies; each elects one MLA (Member of the Legislative Assembly).","The party with a majority of MLAs forms the government.","The leader of the ruling party becomes the Chief Minister.","The Governor is appointed by the President and is the head of the state.","The Legislative Assembly discusses problems and makes laws for the state."]'::jsonb, 'MLAs who are not in the ruling party form the opposition.', '[{"heading":"Choosing MLAs","text":"In elections, people of each constituency vote for a candidate. The winner becomes the MLA for that area."},{"heading":"Forming the government","text":"If a party wins more than half the seats, it has a majority. Its leader becomes Chief Minister, and other MLAs become ministers in charge of health, education and other departments."},{"heading":"Answering to the people","text":"In the Assembly, opposition MLAs ask questions, and ministers must answer. Newspapers and TV also report on the government’s work."}]'::jsonb, '[{"topic":"Politics","question":"Who appoints the Governor of a state?","options":["The Chief Minister","The President","The people","The MLAs"],"correct_index":1,"explanation":"The President appoints the Governor."},{"topic":"Politics","question":"MLA stands for…","options":["Member of the Legislative Assembly","Mayor of Local Area","Minister of Law and Administration","Member of the Lok Sabha"],"correct_index":0,"explanation":"MLA means Member of the Legislative Assembly."},{"topic":"Politics","question":"Who becomes the Chief Minister?","options":["The oldest MLA","The leader of the majority party","The Governor","A judge"],"correct_index":1,"explanation":"The leader of the majority party."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-4', 3, 'class7-civics', 'Boys, girls and equal chances', 'Gender', 'Politics', 3, 'Girls and boys can do any job. Let’s see how women changed the world!', '["Society often expects boys and girls to behave differently; these expectations are learnt, not natural.","Housework and care work are real work, even though they are unpaid.","Savitribai Phule was one of India’s first women teachers and opened schools for girls.","Rashsundari Devi taught herself to read and wrote one of the first autobiographies in Bengali, Amar Jiban.","International Women’s Day is celebrated on 8 March."]'::jsonb, 'The Constitution says men and women are equal, and laws protect women from discrimination at work.', '[{"heading":"Learning roles","text":"Toys, games and chores often send messages: dolls for girls, cars for boys. But both can be anything: doctors, pilots, cooks or engineers."},{"heading":"Valuing work at home","text":"Cooking, cleaning and caring for children and the old take many hours. Most of this is done by women, and it should be shared and respected."},{"heading":"Women who led change","text":"Reformers like Savitribai Phule and Pandita Ramabai worked for girls’ education. Women’s movements have won better laws against violence and unfair treatment."}]'::jsonb, '[{"topic":"Politics","question":"International Women’s Day is on…","options":["8 March","5 June","14 November","15 August"],"correct_index":0,"explanation":"It is celebrated on 8 March."},{"topic":"Politics","question":"Who was one of India’s first women teachers?","options":["Savitribai Phule","Razia Sultan","Rani Lakshmibai","Mirabai"],"correct_index":0,"explanation":"Savitribai Phule opened schools for girls."},{"topic":"Politics","question":"Who wrote Amar Jiban?","options":["Rashsundari Devi","Sarojini Naidu","Indira Gandhi","Annie Besant"],"correct_index":0,"explanation":"Rashsundari Devi wrote it in Bengali."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-5', 3, 'class7-civics', 'Understanding media', 'Media and markets', 'Politics', 4, 'TV, newspapers and the internet tell us what is happening. Let’s learn to think about them!', '["Media are the ways we communicate with many people: newspapers, TV, radio and the internet.","Mass media reach very large numbers of people at once.","Media should be independent: no one should control what they report.","Most media earn money from advertisements, which can affect what they show.","Good citizens compare different sources and check facts before believing or sharing news."]'::jsonb, 'Advertisements try to make us buy things; they often use famous people and catchy slogans.', '[{"heading":"How media help democracy","text":"Media tell us what the government is doing and let people raise problems. A free press is called a pillar of democracy."},{"heading":"Money and media","text":"Running a TV channel or newspaper costs a lot. Advertisers pay for space, and sometimes media avoid stories that upset them."},{"heading":"Thinking for ourselves","text":"A story can be told in many ways. Reading more than one source, and asking who is telling it and why, helps us find the truth."}]'::jsonb, '[{"topic":"Politics","question":"Most media earn money mainly from…","options":["advertisements","taxes","fines","gifts"],"correct_index":0,"explanation":"Advertisements pay for most media."},{"topic":"Politics","question":"Independent media means…","options":["media controlled by the government","no one controls what they report","only foreign news","only sports news"],"correct_index":1,"explanation":"They should report freely and fairly."},{"topic":"Politics","question":"Before sharing news, a good citizen should…","options":["share it at once","check facts and compare sources","add jokes","change it"],"correct_index":1,"explanation":"Always check facts first."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class7-civics-6', 3, 'class7-civics', 'Markets around us', 'Media and markets', 'Politics', 5, 'From weekly haats to shopping malls, let’s see how goods reach us!', '["A weekly market (haat) is held on a fixed day; things are cheap as there are no shop rents to pay.","Neighbourhood shops sell daily needs and often give goods on credit.","Shopping complexes and malls sell branded goods at higher prices.","Goods pass through a chain: producer → wholesaler → retailer → consumer.","Today, many people also buy and sell online."]'::jsonb, 'A wholesaler buys in large quantities and sells to shopkeepers; a retailer sells to us.', '[{"heading":"Different kinds of markets","text":"Weekly markets bring traders and buyers together. Local shops are close by. Malls have many shops under one roof, often air-conditioned."},{"heading":"The chain of markets","text":"A farmer sells vegetables to a wholesale trader in a mandi. The trader sells to shopkeepers, who sell to us. Each one adds a little to the price."},{"heading":"Fair or not?","text":"Big sellers have more money and choice, while small vendors earn little. Markets help us get things, but not everyone gains equally."}]'::jsonb, '[{"topic":"Politics","question":"Who buys goods in large quantities and sells to shops?","options":["Retailer","Wholesaler","Consumer","Farmer"],"correct_index":1,"explanation":"A wholesaler does this."},{"topic":"Politics","question":"Why are things cheaper in a weekly market?","options":["Sellers don’t pay shop rent","Goods are old","Government pays","Only children buy"],"correct_index":0,"explanation":"Traders there have low costs like no rent."},{"topic":"Politics","question":"Who sells goods directly to us?","options":["Wholesaler","Retailer","Producer only","Bank"],"correct_index":1,"explanation":"Retailers sell to consumers."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class8-history', 'From Trade to Freedom', 'History', 'class', 'Class 8', '', 'Company rule, revolts, reforms and the road to 1947.', 7) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-1', 3, 'class8-history', 'How the Company came to rule', 'Company rule', 'History', 0, 'A trading company from England became the ruler of India. Let’s see how!', '["The English East India Company came to trade in 1600 and set up trading posts called factories.","At the Battle of Plassey (1757), Robert Clive defeated Siraj-ud-Daulah, the Nawab of Bengal.","After the Battle of Buxar (1764), the Company got the Diwani, the right to collect revenue, of Bengal, Bihar and Orissa in 1765.","Tipu Sultan of Mysore fought the British and died at Srirangapatna in 1799.","Lord Wellesley’s Subsidiary Alliance and Lord Dalhousie’s Doctrine of Lapse helped the Company take more states."]'::jsonb, 'Tipu Sultan was called the “Tiger of Mysore”.', '[{"heading":"From trade to power","text":"The Company bought cotton, silk, spices and indigo cheaply in India. To protect its trade, it built forts and an army, and began to interfere in the quarrels of Indian rulers."},{"heading":"Plassey and Buxar","text":"At Plassey, the Nawab’s commander Mir Jafar betrayed him, and the Company won. After Buxar, the Mughal emperor gave the Company the Diwani, making it the real ruler of Bengal."},{"heading":"Taking more land","text":"Under the Subsidiary Alliance, Indian rulers had to keep British troops and pay for them. Under the Doctrine of Lapse, if a ruler died without a son, his kingdom went to the Company, as with Jhansi and Satara."}]'::jsonb, '[{"topic":"History","question":"Who won the Battle of Plassey for the Company?","options":["Lord Dalhousie","Robert Clive","Warren Hastings","Lord Wellesley"],"correct_index":1,"explanation":"Robert Clive won it in 1757."},{"topic":"History","question":"Who was called the “Tiger of Mysore”?","options":["Hyder Ali","Tipu Sultan","Shivaji","Ranjit Singh"],"correct_index":1,"explanation":"Tipu Sultan was the Tiger of Mysore."},{"topic":"History","question":"The Doctrine of Lapse was used by…","options":["Lord Wellesley","Lord Dalhousie","Lord Cornwallis","Lord Canning"],"correct_index":1,"explanation":"Lord Dalhousie used it to take states like Jhansi."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-2', 3, 'class8-history', 'Ruling the countryside', 'Company rule', 'History', 1, 'How did the British collect money from India’s farmers? Let’s visit the villages!', '["The Permanent Settlement of 1793, under Lord Cornwallis, fixed revenue with zamindars (landlords) in Bengal.","In the Mahalwari system, revenue was fixed for a whole village (mahal).","In the Ryotwari system, started by Thomas Munro in the south, revenue was fixed directly with farmers (ryots).","Farmers in Bengal were forced to grow indigo; in 1859 they revolted in the “Blue Rebellion”.","In 1917, Gandhi went to Champaran in Bihar to help indigo farmers."]'::jsonb, 'Indigo is a plant that gives a rich blue dye, much wanted in Europe.', '[{"heading":"Collecting land revenue","text":"The Company needed money to run its rule and trade. It tried different ways to collect tax from land. Under all of them, farmers often had to pay too much."},{"heading":"Crops for Europe","text":"The British made farmers grow crops needed abroad, like indigo, jute, cotton and tea, instead of food. Indigo planters gave loans and forced farmers to keep growing it."},{"heading":"Farmers fight back","text":"In 1859, indigo farmers in Bengal refused to grow it and attacked factories. The play “Neel Darpan” showed their suffering. Years later, Gandhi’s Champaran Satyagraha helped indigo farmers in Bihar."}]'::jsonb, '[{"topic":"History","question":"The Permanent Settlement was introduced in…","options":["1757","1765","1793","1857"],"correct_index":2,"explanation":"Lord Cornwallis introduced it in 1793."},{"topic":"History","question":"Who started the Ryotwari system?","options":["Lord Cornwallis","Thomas Munro","Robert Clive","Lord Dalhousie"],"correct_index":1,"explanation":"Thomas Munro started it in the south."},{"topic":"History","question":"The “Blue Rebellion” of 1859 was against…","options":["salt tax","forced indigo farming","new schools","railways"],"correct_index":1,"explanation":"Farmers rose against forced indigo farming."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-3', 3, 'class8-history', 'Tribal people and Birsa Munda', 'People resist', 'History', 2, 'Tribal people lived freely in forests until new rules came. Let’s meet the brave Birsa Munda!', '["Many tribal people practised shifting (jhum) cultivation, moving their fields from place to place in forests.","British forest laws stopped tribals from using forests freely.","Moneylenders and traders (called dikus by tribals) made their lives harder.","The Santhals rebelled in 1855–56, led by Sidhu and Kanhu.","Birsa Munda led the Munda people of Chotanagpur in the 1890s; he died in jail in 1900."]'::jsonb, 'Birsa Munda’s birthday, 15 November, is celebrated as Janjatiya Gaurav Divas.', '[{"heading":"Life in the forest","text":"Tribal groups hunted, gathered forest goods, herded animals or grew crops by shifting cultivation. The forest was their home and their livelihood."},{"heading":"New rules","text":"The British declared many forests government property and stopped shifting cultivation. They wanted timber for railways and wanted tribals to become settled farmers or workers."},{"heading":"Birsa’s dream","text":"Birsa Munda dreamed of a golden age without outsiders and unfair laws. His followers attacked symbols of British power. He died young, but forced the British to pass laws protecting tribal land."}]'::jsonb, '[{"topic":"History","question":"Who led the Santhal rebellion of 1855?","options":["Birsa Munda","Sidhu and Kanhu","Tantia Tope","Kunwar Singh"],"correct_index":1,"explanation":"Sidhu and Kanhu led the Santhals."},{"topic":"History","question":"Shifting cultivation is also called…","options":["jhum","zabt","ryotwari","mahal"],"correct_index":0,"explanation":"It is often called jhum cultivation."},{"topic":"History","question":"Janjatiya Gaurav Divas (15 November) honours…","options":["Birsa Munda","Mahatma Gandhi","Rani Lakshmibai","Bhagat Singh"],"correct_index":0,"explanation":"It is Birsa Munda’s birthday."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-4', 3, 'class8-history', 'When people rebel: 1857', 'People resist', 'History', 3, 'In 1857, soldiers, kings and farmers rose together. Let’s see what happened!', '["The revolt began with sepoys at Meerut on 10 May 1857.","Rumours of cartridges greased with cow and pig fat angered Hindu and Muslim sepoys.","Mangal Pandey had attacked officers at Barrackpore in March 1857.","The rebels made Bahadur Shah Zafar, the old Mughal king, their leader.","Rani Lakshmibai of Jhansi, Nana Saheb, Tantia Tope and Begum Hazrat Mahal were among the leaders."]'::jsonb, 'After 1857, the British Crown took over India from the Company, under the Government of India Act 1858.', '[{"heading":"Why people were angry","text":"Rulers had lost their kingdoms, farmers paid heavy taxes, and sepoys faced low pay and insults. Many also feared that the British wanted to change their religion."},{"heading":"The revolt spreads","text":"From Meerut, sepoys marched to Delhi. Soon Kanpur, Lucknow, Jhansi and many other places joined. Ordinary people fought alongside soldiers."},{"heading":"After the revolt","text":"The British crushed the revolt by 1858. Bahadur Shah Zafar was sent to Rangoon. The Company’s rule ended, and India was ruled by the Crown through a Viceroy."}]'::jsonb, '[{"topic":"History","question":"Where did the Revolt of 1857 begin?","options":["Delhi","Meerut","Kanpur","Jhansi"],"correct_index":1,"explanation":"It began at Meerut on 10 May 1857."},{"topic":"History","question":"The rebels made whom their emperor?","options":["Nana Saheb","Bahadur Shah Zafar","Tantia Tope","Tipu Sultan"],"correct_index":1,"explanation":"They declared Bahadur Shah Zafar their leader."},{"topic":"History","question":"Which queen fought bravely in 1857?","options":["Razia Sultan","Rani Lakshmibai","Nur Jahan","Rani Durgavati"],"correct_index":1,"explanation":"Rani Lakshmibai of Jhansi."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-5', 3, 'class8-history', 'Education and social reform', 'Changing society', 'History', 4, 'New schools and brave reformers changed India. Let’s meet them!', '["Thomas Macaulay’s Minute (1835) pushed for English education in India.","Wood’s Despatch (1854) led to universities in Calcutta, Bombay and Madras (1857).","Raja Ram Mohan Roy campaigned against sati, which was banned in 1829.","Jyotiba Phule wrote Gulamgiri (1873) against caste injustice.","Rabindranath Tagore started a school at Shantiniketan in 1901, where children learnt close to nature."]'::jsonb, 'Gandhi wanted education in Indian languages, with learning through hand work and crafts.', '[{"heading":"English education","text":"The British wanted Indians who could work in offices. Macaulay believed English learning was better than Indian learning. Many Indians disagreed but also used English to learn new ideas."},{"heading":"Reformers","text":"Raja Ram Mohan Roy, Ishwar Chandra Vidyasagar, Jyotiba and Savitribai Phule, and others worked for widows, girls’ education and the end of caste discrimination."},{"heading":"Indian ideas of education","text":"Tagore wanted children to learn joyfully, in natural surroundings. Gandhi wanted education that built character and taught useful skills, in the child’s own language."}]'::jsonb, '[{"topic":"History","question":"Who started the school at Shantiniketan?","options":["Mahatma Gandhi","Rabindranath Tagore","Jyotiba Phule","Raja Ram Mohan Roy"],"correct_index":1,"explanation":"Rabindranath Tagore started it in 1901."},{"topic":"History","question":"Who wrote Gulamgiri?","options":["Jyotiba Phule","Dr B. R. Ambedkar","Swami Vivekananda","Dayananda Saraswati"],"correct_index":0,"explanation":"Jyotiba Phule wrote it in 1873."},{"topic":"History","question":"In which year were universities set up in Calcutta, Bombay and Madras?","options":["1835","1854","1857","1901"],"correct_index":2,"explanation":"They were set up in 1857."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-history-6', 3, 'class8-history', 'The road to freedom', 'Changing society', 'History', 5, 'From 1885 to 1947, Indians struggled for freedom. Let’s walk that road together!', '["The Indian National Congress was formed in 1885 in Bombay.","The Partition of Bengal (1905) led to the Swadeshi movement.","Gandhi led the Non-Cooperation Movement (1920), the Salt March (1930) and the Quit India Movement (1942).","The Jallianwala Bagh massacre in Amritsar took place on 13 April 1919.","India became independent on 15 August 1947."]'::jsonb, 'Subhas Chandra Bose formed the Azad Hind government and led the Indian National Army.', '[{"heading":"Early nationalists","text":"Leaders like Dadabhai Naoroji asked the British for reforms. Later, leaders like Bal Gangadhar Tilak demanded Swaraj (self-rule) and boycotted British goods."},{"heading":"Gandhi’s mass movements","text":"Gandhi brought farmers, workers, women and students into the struggle with non-violent movements. The Salt March to Dandi showed how a simple act could challenge an empire."},{"heading":"Freedom and partition","text":"After the Second World War, Britain agreed to leave. India became free on 15 August 1947, but was divided, and Pakistan was formed. Millions had to leave their homes."}]'::jsonb, '[{"topic":"History","question":"When was the Indian National Congress formed?","options":["1857","1885","1905","1920"],"correct_index":1,"explanation":"It was formed in 1885."},{"topic":"History","question":"The Quit India Movement began in…","options":["1920","1930","1942","1947"],"correct_index":2,"explanation":"It began in August 1942."},{"topic":"History","question":"The Jallianwala Bagh massacre happened in…","options":["Delhi","Lahore","Amritsar","Lucknow"],"correct_index":2,"explanation":"It happened in Amritsar on 13 April 1919."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class8-geography', 'Resources and Development', 'Geography', 'class', 'Class 8', '', 'Land, water, forests, minerals, farming and industries.', 8) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-1', 3, 'class8-geography', 'What are resources?', 'Resources', 'Geography', 0, 'Water, trees, coal and even people can be resources! Let’s find out why.', '["A resource is anything that is useful and has value for people.","Natural resources come from nature, like air, water, soil and minerals.","Human-made resources are made by people, like buildings, roads and machines.","People’s skills and knowledge make them human resources.","Renewable resources, like sunlight and wind, get renewed; non-renewable ones, like coal and oil, can run out."]'::jsonb, 'Sustainable development means using resources carefully so that future generations also have enough.', '[{"heading":"What makes something a resource","text":"Water was always there, but it became a resource when people used it to drink, farm and make electricity. Time and technology can turn things into resources."},{"heading":"Kinds of resources","text":"Resources can be natural, human-made or human. Natural resources can be renewable or non-renewable, and found everywhere (ubiquitous) or only in some places (localised)."},{"heading":"Saving resources","text":"Reduce, reuse and recycle. Turn off lights, save water and protect forests. Using resources wisely is called conservation."}]'::jsonb, '[{"topic":"Geography","question":"Which of these is a non-renewable resource?","options":["Sunlight","Wind","Coal","Water"],"correct_index":2,"explanation":"Coal takes millions of years to form and can run out."},{"topic":"Geography","question":"A road is an example of a…","options":["natural resource","human-made resource","human resource","mineral"],"correct_index":1,"explanation":"Roads are made by people."},{"topic":"Geography","question":"Using resources so future people have enough is called…","options":["sustainable development","pollution","migration","mining"],"correct_index":0,"explanation":"That is sustainable development."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-2', 3, 'class8-geography', 'Land, soil and water', 'Resources', 'Geography', 1, 'We stand on land, grow food in soil and drink water. Let’s learn to protect all three!', '["Land is used for farming, forests, mining, houses and roads; this is called land use.","Soil takes hundreds of years to form but can be washed away quickly.","Ways to save soil: terrace farming on slopes, contour ploughing, mulching and planting rows of trees as shelter belts.","Only a small part of the Earth’s water is fresh water we can use.","Drip irrigation and sprinklers save water in farming."]'::jsonb, 'Rainwater harvesting means collecting and storing rainwater for later use.', '[{"heading":"Land use","text":"How land is used depends on soil, slope, climate and people’s needs. As population grows, forests and farms are turned into towns, which can harm the environment."},{"heading":"Saving soil","text":"Cutting trees, overgrazing and floods wash soil away. Terraces on hills, ploughing along the slope’s contours and covering soil with straw or leaves (mulching) help hold it."},{"heading":"Saving water","text":"Water is wasted by leaking pipes and by flooding fields. Drip irrigation gives each plant just the water it needs. Keeping rivers clean also protects our water."}]'::jsonb, '[{"topic":"Geography","question":"Farming on step-like fields on hill slopes is called…","options":["terrace farming","mulching","shifting cultivation","drip irrigation"],"correct_index":0,"explanation":"Terraces stop soil from washing down slopes."},{"topic":"Geography","question":"Covering soil with straw or leaves is called…","options":["mulching","ploughing","mining","grazing"],"correct_index":0,"explanation":"That is mulching."},{"topic":"Geography","question":"Which method saves the most water in farming?","options":["Flooding fields","Drip irrigation","Leaving taps open","Canals without lining"],"correct_index":1,"explanation":"Drip irrigation gives water drop by drop to plants."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-3', 3, 'class8-geography', 'Natural vegetation and wildlife', 'Resources', 'Geography', 2, 'Forests and animals are part of our treasure. Let’s learn how to protect them!', '["Natural vegetation grows on its own, without people planting it.","Forests give us wood, fruit, medicines and oxygen, and are homes for animals.","National parks, wildlife sanctuaries and biosphere reserves protect plants and animals.","The Nilgiri Biosphere Reserve (1986) was India’s first biosphere reserve.","CITES is an international agreement that controls trade in wild animals and plants."]'::jsonb, 'Van Mahotsav, a week of tree planting, is celebrated in the first week of July.', '[{"heading":"Why forests matter","text":"Trees hold the soil, bring rain, clean the air and give shelter to animals and birds. Many medicines come from forest plants."},{"heading":"Threats","text":"Forests are cut for farms, cities and roads. Poaching kills animals like tigers, rhinos and elephants for their skins, horns and tusks."},{"heading":"Protecting nature","text":"Laws ban hunting of protected animals. Biosphere reserves protect large areas, including the people who live there. Everyone can help by planting trees and not buying wildlife products."}]'::jsonb, '[{"topic":"Geography","question":"India’s first biosphere reserve was…","options":["Sundarbans","Nilgiri","Nanda Devi","Gulf of Mannar"],"correct_index":1,"explanation":"The Nilgiri Biosphere Reserve, set up in 1986."},{"topic":"Geography","question":"CITES controls trade in…","options":["oil","wild animals and plants","cars","gold"],"correct_index":1,"explanation":"It controls trade in wild animals and plants."},{"topic":"Geography","question":"Van Mahotsav is a festival of…","options":["kites","tree planting","lights","harvest"],"correct_index":1,"explanation":"It is a tree-planting week in July."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-4', 3, 'class8-geography', 'Minerals and power', 'Using resources', 'Geography', 3, 'Iron, coal and sunlight power our world. Let’s dig into minerals and energy!', '["Metallic minerals that contain iron, like iron ore, are ferrous; others, like copper and bauxite, are non-ferrous.","Non-metallic minerals include limestone, mica and gypsum.","Coal, petroleum and natural gas are conventional (older) sources of energy; they are fossil fuels.","Solar, wind, tidal, geothermal and biogas are non-conventional sources; they are cleaner.","Electricity made from flowing water is called hydel power."]'::jsonb, 'Coal is sometimes called “buried sunshine”, because it formed from ancient plants.', '[{"heading":"Minerals","text":"Minerals are found in rocks and are taken out by mining. Iron is used for steel, bauxite for aluminium, and copper for wires."},{"heading":"Conventional energy","text":"Most of our electricity still comes from burning coal in thermal power stations. Petrol and diesel run vehicles. These pollute the air and will run out one day."},{"heading":"Clean energy","text":"Solar panels, windmills and biogas plants give energy without much pollution. India is building many solar parks and wind farms."}]'::jsonb, '[{"topic":"Geography","question":"Which is a ferrous mineral?","options":["Copper","Bauxite","Iron ore","Mica"],"correct_index":2,"explanation":"Iron ore contains iron, so it is ferrous."},{"topic":"Geography","question":"Electricity made from flowing water is…","options":["thermal power","hydel power","solar power","nuclear"],"correct_index":1,"explanation":"That is hydel (hydroelectric) power."},{"topic":"Geography","question":"Which is a non-conventional energy source?","options":["Coal","Petroleum","Wind","Natural gas"],"correct_index":2,"explanation":"Wind is a clean, non-conventional source."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-5', 3, 'class8-geography', 'Agriculture', 'Using resources', 'Geography', 4, 'From a small family farm to big tea gardens, let’s explore farming!', '["Subsistence farming grows food mainly for the farmer’s own family.","Commercial farming grows crops to sell in the market.","Plantations are large farms growing one crop, like tea, coffee or rubber.","Rice needs high temperature and lots of rain; wheat grows in cooler, drier weather.","Cotton grows well in black soil, and jute in the wet delta lands of Bengal."]'::jsonb, 'Agriculture, fishing and forestry are primary activities; making goods in factories is a secondary activity.', '[{"heading":"Kinds of farming","text":"In shifting cultivation, a patch of forest is cleared, farmed for a few years and then left. Intensive farming uses small land with much work. Commercial farms use machines and sell their crops."},{"heading":"Major crops","text":"Rice is the main food crop of the east and south of India, wheat of the north. Tea grows in Assam and Darjeeling, and coffee in Karnataka."},{"heading":"Changes in farming","text":"Better seeds, fertilisers and irrigation have raised production. But too many chemicals can harm soil and water, so organic farming is also growing."}]'::jsonb, '[{"topic":"Geography","question":"Farming mainly to feed one’s own family is…","options":["commercial farming","subsistence farming","plantation","industry"],"correct_index":1,"explanation":"That is subsistence farming."},{"topic":"Geography","question":"Which crop is grown on plantations?","options":["Tea","Wheat","Gram","Mustard"],"correct_index":0,"explanation":"Tea is a plantation crop."},{"topic":"Geography","question":"Which crop grows best in black soil?","options":["Jute","Cotton","Tea","Rice"],"correct_index":1,"explanation":"Cotton grows well in black soil."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-geo-6', 3, 'class8-geography', 'Industries and people', 'Using resources', 'Geography', 5, 'Factories turn raw materials into things we use, and people are the greatest resource of all!', '["Industries change raw materials into useful goods, like cotton into cloth.","Agro-based industries use farm products; mineral-based industries use minerals like iron ore.","TISCO (now Tata Steel) started steel making at Jamshedpur in 1907.","Bengaluru is called the “Silicon Valley of India” for its IT industry.","India counts its people in a Census, held every ten years."]'::jsonb, 'Sex ratio is the number of females for every 1,000 males.', '[{"heading":"Kinds of industries","text":"Industries can be small (like a handloom) or large (like a steel plant). They can be owned by the government (public sector), by private people, or by both (joint sector)."},{"heading":"Where industries grow","text":"Industries grow where raw materials, power, workers, transport and markets are available. Jamshedpur is near iron ore and coal; Mumbai grew with cotton mills."},{"heading":"People as a resource","text":"Healthy, educated and skilled people make a country strong. The Census tells us how many people there are, their ages, literacy and where they live."}]'::jsonb, '[{"topic":"Geography","question":"Which city is called the “Silicon Valley of India”?","options":["Mumbai","Bengaluru","Chennai","Kolkata"],"correct_index":1,"explanation":"Bengaluru, for its IT industry."},{"topic":"Geography","question":"TISCO’s steel plant is at…","options":["Bhilai","Jamshedpur","Rourkela","Durgapur"],"correct_index":1,"explanation":"It began at Jamshedpur in 1907."},{"topic":"Geography","question":"How often is India’s Census usually held?","options":["Every year","Every five years","Every ten years","Every twenty years"],"correct_index":2,"explanation":"It is held every ten years."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class8-civics', 'The Constitution and Us', 'Politics', 'class', 'Class 8', '', 'The Constitution, Parliament, courts and social justice.', 9) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-1', 3, 'class8-civics', 'Why do we need a Constitution?', 'The Constitution', 'Politics', 0, 'A country needs a rulebook that everyone follows. Let’s open ours!', '["A constitution sets out the basic rules for how a country is governed.","India’s Constitution was adopted on 26 November 1949 and came into force on 26 January 1950.","Dr B. R. Ambedkar chaired its Drafting Committee.","Key features: federalism, a parliamentary form of government, separation of powers, Fundamental Rights and secularism.","Separation of powers means the legislature, executive and judiciary each have their own work."]'::jsonb, 'Dr Ambedkar is called the father of the Indian Constitution.', '[{"heading":"Why rules matter","text":"A constitution protects people from misuse of power. It says how leaders are chosen, what they can and cannot do, and what rights every citizen has."},{"heading":"Making our Constitution","text":"The Constituent Assembly, with about 300 members, worked for nearly three years and debated every part. It reflected the dreams of the freedom struggle."},{"heading":"Three organs","text":"The legislature (Parliament) makes laws, the executive (government) carries them out, and the judiciary (courts) settles disputes and checks that laws follow the Constitution."}]'::jsonb, '[{"topic":"Politics","question":"When did the Constitution come into force?","options":["15 August 1947","26 November 1949","26 January 1950","2 October 1950"],"correct_index":2,"explanation":"It came into force on 26 January 1950."},{"topic":"Politics","question":"Who chaired the Drafting Committee?","options":["Jawaharlal Nehru","Dr B. R. Ambedkar","Sardar Patel","Dr Rajendra Prasad"],"correct_index":1,"explanation":"Dr B. R. Ambedkar chaired it."},{"topic":"Politics","question":"Which organ of government makes laws?","options":["Executive","Legislature","Judiciary","Police"],"correct_index":1,"explanation":"The legislature (Parliament) makes laws."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-2', 3, 'class8-civics', 'Understanding secularism', 'The Constitution', 'Politics', 1, 'India respects all religions equally. Let’s understand what secularism means.', '["Secularism means the state keeps religion separate from government.","The Indian state does not favour or promote any one religion.","Every person is free to follow, practise and spread their religion.","The state can step in to stop harmful practices, as it did with untouchability.","The word “secular” was added to the Preamble by the 42nd Amendment in 1976."]'::jsonb, 'In India, government schools cannot hold religious lessons or celebrate one religion over others.', '[{"heading":"Why separate religion and state","text":"If one religious group controlled the government, others might be treated unfairly. Keeping them separate protects everyone, including those who follow no religion."},{"heading":"How India does it","text":"The state keeps a principled distance from all religions. It does not have an official religion, and it treats all citizens equally."},{"heading":"Freedom with limits","text":"Freedom of religion does not allow harming others. The state can make laws for equality, for example to end discrimination inside religious practices."}]'::jsonb, '[{"topic":"Politics","question":"Secularism means…","options":["one official religion","religion kept separate from government","no festivals","only one language"],"correct_index":1,"explanation":"The state does not favour any religion."},{"topic":"Politics","question":"Which amendment added “secular” to the Preamble?","options":["1st","24th","42nd","73rd"],"correct_index":2,"explanation":"The 42nd Amendment of 1976."},{"topic":"Politics","question":"Does India have an official state religion?","options":["Yes, Hinduism","Yes, Islam","No","It changes every year"],"correct_index":2,"explanation":"India has no official religion."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-3', 3, 'class8-civics', 'Parliament and making laws', 'Parliament and courts', 'Politics', 2, 'Laws are made in Parliament. Let’s see how an idea becomes a law!', '["Parliament has the President, the Lok Sabha and the Rajya Sabha.","Members of the Lok Sabha are elected directly by the people; they are called MPs.","The party or alliance with a majority in the Lok Sabha forms the government, led by the Prime Minister.","A proposed law is called a bill; it becomes a law (Act) after both Houses pass it and the President agrees.","Citizens can push for new laws, like the Protection of Women from Domestic Violence Act, 2005."]'::jsonb, 'Question Hour lets MPs ask ministers questions about the government’s work.', '[{"heading":"Choosing Parliament","text":"In a general election, every constituency elects one MP to the Lok Sabha. The Rajya Sabha members are mostly elected by state legislatures."},{"heading":"Checking the government","text":"Parliament controls the government. MPs ask questions, debate policies and approve how money is spent. The opposition plays an important role in pointing out mistakes."},{"heading":"How a law is made","text":"A bill is discussed and voted on in both Houses. After the President signs it, it becomes law. People and groups often campaign for years to get important laws passed."}]'::jsonb, '[{"topic":"Politics","question":"A proposed law is called a…","options":["bill","writ","case","vote"],"correct_index":0,"explanation":"A proposed law is a bill."},{"topic":"Politics","question":"Members of the Lok Sabha are chosen by…","options":["the President","the people directly","the judges","the Governors"],"correct_index":1,"explanation":"People elect them in general elections."},{"topic":"Politics","question":"Who leads the government at the Union level?","options":["The Chief Justice","The Prime Minister","The Speaker","The Governor"],"correct_index":1,"explanation":"The Prime Minister leads the government."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-4', 3, 'class8-civics', 'The judiciary', 'Parliament and courts', 'Politics', 3, 'Courts make sure everyone gets justice. Let’s visit them!', '["India has three levels of courts: district courts, High Courts and the Supreme Court.","The judiciary is independent: the government cannot tell judges how to decide.","Criminal law deals with crimes like theft; civil law deals with disputes like property or money.","An FIR (First Information Report) is filed at a police station to report a crime.","Public Interest Litigation (PIL), started in the 1980s, lets anyone go to court on behalf of people who cannot."]'::jsonb, 'The Supreme Court, in New Delhi, is the highest court of the country.', '[{"heading":"What courts do","text":"Courts settle disputes between people, between people and the government, and between states. They also protect Fundamental Rights."},{"heading":"Criminal and civil cases","text":"In a criminal case, the police investigate and the state takes the accused to court. In a civil case, a person who feels wronged files a case to get a remedy, like compensation."},{"heading":"Justice for all","text":"Through PIL, courts have helped bonded labourers, prisoners and children. The court can be reached even by a letter about a serious injustice."}]'::jsonb, '[{"topic":"Politics","question":"Which is the highest court in India?","options":["District Court","High Court","Supreme Court","Lok Adalat"],"correct_index":2,"explanation":"The Supreme Court is the highest."},{"topic":"Politics","question":"What does FIR stand for?","options":["First Information Report","Final Inquiry Record","Formal Indian Rule","First Investigation Request"],"correct_index":0,"explanation":"FIR means First Information Report."},{"topic":"Politics","question":"A dispute over property is a…","options":["criminal case","civil case","bill","PIL only"],"correct_index":1,"explanation":"Property and money disputes are civil cases."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-5', 3, 'class8-civics', 'Marginalisation and safeguards', 'Social justice', 'Politics', 4, 'Some groups have been pushed to the side for a long time. Let’s see how the law protects them.', '["Marginalisation means being pushed to the edge of society and kept out of opportunities.","Adivasis, Dalits and some minority groups have faced marginalisation.","The Constitution provides reservations in education, jobs and legislatures for Scheduled Castes and Scheduled Tribes.","The SC/ST (Prevention of Atrocities) Act, 1989 punishes crimes against these groups.","Manual scavenging (cleaning human waste by hand) is banned by law."]'::jsonb, 'Article 15 forbids discrimination on grounds of religion, race, caste, sex or place of birth.', '[{"heading":"Being left out","text":"Many Adivasis lost forest land to dams and mines. Dalits faced untouchability for centuries. Marginalised groups often have less education, health care and income."},{"heading":"Laws and policies","text":"Reservations, scholarships and special hostels help marginalised groups get education and jobs. Laws punish discrimination and violence against them."},{"heading":"People’s struggles","text":"Movements led by Dalits, Adivasis and others have used the Constitution to demand their rights. Many poets and writers have also spoken out for dignity."}]'::jsonb, '[{"topic":"Politics","question":"Marginalisation means…","options":["being at the centre of power","being pushed to the edge of society","moving to a city","winning an election"],"correct_index":1,"explanation":"It means being kept out of opportunities."},{"topic":"Politics","question":"The SC/ST (Prevention of Atrocities) Act was passed in…","options":["1950","1976","1989","2005"],"correct_index":2,"explanation":"It was passed in 1989."},{"topic":"Politics","question":"Which Article forbids discrimination on grounds of caste?","options":["Article 15","Article 32","Article 44","Article 51A"],"correct_index":0,"explanation":"Article 15 forbids such discrimination."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class8-civics-6', 3, 'class8-civics', 'Public facilities and the law', 'Social justice', 'Politics', 5, 'Water, buses and safe workplaces are for everyone. Let’s see how laws make sure of it!', '["Public facilities, like water supply, health care, schools and public transport, are provided by the government for everyone.","Courts have held that the right to life (Article 21) includes the right to clean water.","Minimum wage laws stop workers from being paid too little.","The Bhopal gas tragedy of December 1984, at the Union Carbide factory, was one of the worst industrial disasters.","Laws protect the environment and consumers as well as workers."]'::jsonb, 'Public transport like buses and the Metro carry many people cheaply and cause less pollution per person.', '[{"heading":"Facilities for all","text":"A private company aims to make profit, but a public facility must serve everyone, rich or poor. Clean water and sanitation are basic needs."},{"heading":"Laws protect people","text":"Laws on minimum wages, safety at work and child labour protect workers. Strong enforcement is needed so that the laws are followed."},{"heading":"Lessons from Bhopal","text":"When poisonous gas leaked in Bhopal, thousands died and many more fell ill. It showed the need for strict safety and environment laws."}]'::jsonb, '[{"topic":"Politics","question":"The Bhopal gas tragedy happened in…","options":["1947","1975","1984","2004"],"correct_index":2,"explanation":"It happened in December 1984."},{"topic":"Politics","question":"The right to clean water is part of…","options":["Article 14","Article 21 (right to life)","Article 44","Article 112"],"correct_index":1,"explanation":"Courts have read it into the right to life."},{"topic":"Politics","question":"Minimum wage laws protect…","options":["companies","workers","banks","shops"],"correct_index":1,"explanation":"They stop workers being paid too little."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class9-history', 'Early India and the World', 'History', 'class', 'Class 9', '', 'Social science, early humans, civilisations and states.', 10) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-1', 3, 'class9-history', 'Understanding social science', 'Introduction', 'History', 0, 'Why do people live the way they do? Social science helps us find out. Let’s begin!', '["Social science studies people and society: how we live, work, rule and change over time.","Its main branches are history, geography, political science and economics; sociology studies groups and communities.","History studies the past; geography studies places and the Earth; political science studies power and government; economics studies how we use resources.","These subjects are linked: a river (geography) can shape farming (economics), cities (history) and borders (politics).","Social scientists use evidence like records, maps, surveys and data, and ask questions with an open mind."]'::jsonb, 'India has an old tradition of thinking about society: the Arthashastra, linked with Kautilya (Chanakya), discusses statecraft and economy.', '[{"heading":"What is social science?","text":"Natural sciences like physics and biology study the world of matter and living things. Social science studies something just as interesting: people living together. It asks how families, villages, cities and countries are organised, why people make the choices they do, and how life has changed over thousands of years. Because people are not machines, social science rarely gives one simple answer. Instead, it helps us look at a question from many sides and understand why different people may see the same event in different ways."},{"heading":"The main branches","text":"History studies the past using clues such as inscriptions, coins, buildings, letters and old books. Geography studies the Earth, its landforms, climate and resources, and how people use and change their surroundings. Political science studies power: who makes decisions, how governments are formed and how citizens can take part. Economics studies how people produce, share and use scarce resources such as land, money and time. Sociology looks at groups, customs and social change, and anthropology studies cultures and ways of life."},{"heading":"Why the branches belong together","text":"Real life does not come in separate subjects. Think of a great river like the Ganga. Its fertile plains (geography) allowed farmers to grow surplus grain (economics). That surplus helped cities and kingdoms to grow (history), and control over the river’s land and water shaped politics and borders (political science). This is why the new Class 9 book brings the subjects together as themes: to understand any question properly, we need all these lenses at once."},{"heading":"How social scientists find out","text":"Social scientists collect evidence carefully. A historian compares several sources and asks who wrote each one and why. A geographer uses maps, satellite images and field visits. An economist studies numbers such as prices, incomes and production. Political scientists study laws, elections and surveys of what people think. Good researchers check facts, notice their own biases and change their views when new evidence appears. These habits of mind are useful far beyond the classroom."},{"heading":"An old Indian tradition","text":"Thinking about society is not new in India. The Arthashastra, linked with Kautilya (Chanakya), discusses how a state should be run, how taxes should be collected and how trade can be encouraged. Ancient assemblies such as the sabha and samiti show early ideas of discussion before decisions. Travellers, poets and scholars over the centuries recorded how people lived. Learning social science helps us connect this long tradition with the questions we face as citizens today."},{"heading":"Social science and you","text":"Social science is not just about exams. When you read a newspaper, compare prices in a shop, vote one day, or wonder why your town floods every monsoon, you are using social science. It helps you understand the news, respect people who live differently, and make wise choices as a citizen. As you study each theme this year, try to ask: what happened, where, why, who gained, who lost, and what could be done better?"}]'::jsonb, '[{"topic":"Social Science","question":"Which branch of social science studies how people use resources?","options":["History","Economics","Geography","Political science"],"correct_index":1,"explanation":"Economics studies how we use scarce resources."},{"topic":"Social Science","question":"The Arthashastra is linked with…","options":["Kalidasa","Kautilya","Aryabhata","Panini"],"correct_index":1,"explanation":"It is linked with Kautilya, also called Chanakya."},{"topic":"Social Science","question":"Power and government are studied in…","options":["political science","geography","chemistry","economics only"],"correct_index":0,"explanation":"Political science studies power and government."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-4', 3, 'class9-history', 'Early humans and the first civilisations', 'Our past', 'History', 1, 'From stone tools to planned cities, let’s travel back thousands of years!', '["Early humans lived by hunting and gathering and used stone tools; this long period is the Stone Age.","The rock shelters of Bhimbetka in Madhya Pradesh have paintings made by early humans; they are a UNESCO World Heritage Site.","At Mehrgarh, people were farming and keeping animals by about 7000 BCE.","The Harappan (Indus–Sarasvati) civilisation built planned cities with drains, such as Mohenjo-daro, Harappa, Dholavira and Lothal.","Other early civilisations grew along rivers: Mesopotamia (Tigris and Euphrates), Egypt (Nile) and China (Huang He)."]'::jsonb, 'Lothal in Gujarat had one of the world’s earliest known dockyards.', '[{"heading":"Life in the Stone Age","text":"For most of human history, people lived by hunting animals, fishing and gathering fruits, roots and honey. They moved with the seasons and made tools from stone, bone and wood. Historians call this long period the Stone Age and divide it into the Palaeolithic (old), Mesolithic (middle) and Neolithic (new) stages. Learning to control fire was a huge step: it gave warmth, protection from animals and a way to cook food. Small groups shared what they found and cared for each other."},{"heading":"Art on the rocks","text":"Early people left behind paintings on the walls of caves and rock shelters. At Bhimbetka in Madhya Pradesh, hundreds of shelters show hunting scenes, animals, dancing and daily life, painted with colours made from minerals. Some paintings are many thousands of years old. These pictures are precious evidence: they tell us what animals lived nearby, what tools people used and what mattered to them. Bhimbetka is now a UNESCO World Heritage Site."},{"heading":"From hunting to farming","text":"Slowly, people learnt to sow seeds and tame animals such as sheep, goats and cattle. Farming meant they could stay in one place, build houses of mud brick and store grain. At Mehrgarh, near the Bolan Pass, people were growing barley and wheat and keeping animals by about 7000 BCE. This great change, from moving about to settled village life, is often called the Neolithic Revolution. It led to pottery, weaving and, over time, larger settlements."},{"heading":"The Harappan cities","text":"By about 2600 BCE, large cities had grown in the north-west of the subcontinent. Mohenjo-daro, Harappa, Dholavira, Kalibangan and Lothal had straight streets, baked-brick houses, wells and covered drains, something many later cities lacked. Mohenjo-daro had a Great Bath, and Lothal had a dockyard for boats. Harappans made beads, seals, pottery and cotton cloth, used standard weights and traded as far as Mesopotamia. Their script has still not been read, so many questions remain open."},{"heading":"Other river civilisations","text":"Around the same time, other civilisations grew along great rivers. In Mesopotamia, between the Tigris and the Euphrates, people built cities like Ur and wrote in wedge-shaped cuneiform on clay tablets. In Egypt, along the Nile, rulers called pharaohs built the pyramids. In China, early states grew along the Huang He. Rivers gave water, fertile soil and easy transport. Each civilisation developed its own ways of farming, trading, writing and ruling."},{"heading":"How we know about them","text":"Most of what we know about early humans and the first civilisations comes from archaeology. Archaeologists dig carefully at old sites and study tools, bones, pottery, seeds and the remains of buildings. Scientific methods help them find out how old these objects are. Each new discovery, like the city of Dholavira or the farming village at Mehrgarh, adds to the story, and sometimes changes what historians believed before."}]'::jsonb, '[{"topic":"History","question":"The rock paintings of Bhimbetka are in…","options":["Gujarat","Madhya Pradesh","Bihar","Kerala"],"correct_index":1,"explanation":"Bhimbetka is in Madhya Pradesh."},{"topic":"History","question":"Which Harappan site had an early dockyard?","options":["Lothal","Harappa","Kalibangan","Rakhigarhi"],"correct_index":0,"explanation":"Lothal in Gujarat had a dockyard."},{"topic":"History","question":"Mesopotamia grew between which rivers?","options":["Nile and Congo","Tigris and Euphrates","Ganga and Yamuna","Indus and Jhelum"],"correct_index":1,"explanation":"Between the Tigris and the Euphrates."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-5', 3, 'class9-history', 'State and society up to 1000 CE', 'Our past', 'History', 2, 'From small kingdoms to great empires, let’s see how states grew in India!', '["Around the 6th century BCE, there were sixteen large states called mahajanapadas; Magadha became the strongest.","Some states, like the Vajji confederacy, were ganas or sanghas, ruled by assemblies rather than a single king.","Chandragupta Maurya, guided by Chanakya, built a large empire with its capital at Pataliputra.","After the Kalinga war, Emperor Ashoka turned to dhamma and spread his message through rock and pillar edicts.","Under the Guptas, science and art flourished: Aryabhata wrote on astronomy and mathematics, and Nalanda became a famous centre of learning."]'::jsonb, 'The Lion Capital of Ashoka at Sarnath is India’s national emblem.', '[{"heading":"Janapadas and mahajanapadas","text":"As farming spread across the Ganga plains, villages grew into towns, and groups of people settled in territories called janapadas. By about the 6th century BCE, sixteen large states, the mahajanapadas, had formed, including Magadha, Kosala, Vatsa and Avanti. They built forts, kept armies and collected taxes in grain and goods. Magadha, with fertile land, iron mines nearby and rivers for transport, became the most powerful. Its capital was first Rajagriha and later Pataliputra."},{"heading":"Kings and assemblies","text":"Not every state had a single king. Some, like the Vajji confederacy with its capital at Vaishali, were ganas or sanghas, where many leaders met in an assembly, discussed matters and decided together. Even in kingdoms, councils of ministers and older assemblies like the sabha and samiti were important. These traditions show that ideas of discussion and shared decision-making have deep roots in India."},{"heading":"A great empire","text":"In the 4th century BCE, Chandragupta Maurya, guided by his adviser Chanakya, built an empire that stretched across most of the subcontinent, with Pataliputra as its capital. His grandson Ashoka fought a terrible war in Kalinga. Shocked by the deaths, he gave up conquest by war and followed dhamma: kindness, tolerance, respect for elders and care for animals. He carved his messages on rocks and pillars across his empire, in languages people could understand."},{"heading":"The Gupta age and the south","text":"Later, the Gupta rulers controlled much of northern India. This period is famous for learning and art. Aryabhata wrote on astronomy and mathematics, Kalidasa wrote plays and poems, and Nalanda grew into a great university that drew students from distant lands. In the south, kingdoms such as the Pallavas, Chalukyas and later the Cholas built magnificent temples and encouraged trade across the seas with South-East Asia."},{"heading":"How people lived","text":"Most people were farmers who paid a share of their harvest as tax. Crafts-people made pottery, cloth, metal tools and jewellery, and merchants carried goods along land and sea routes. Guilds of traders and artisans managed their own affairs. Towns grew around markets, ports and temples. Religious ideas such as Buddhism and Jainism spread alongside older traditions. Up to about 1000 CE, India was a land of many states, busy trade and rich learning."},{"heading":"Sources for this period","text":"Historians learn about these centuries from many sources. Ashoka’s edicts tell us his own ideas in his own words. Coins show the names and pictures of kings. Texts such as the Arthashastra describe how a state could be run, and Buddhist and Jain books tell us about towns and trade. Accounts of foreign visitors, like the Greek Megasthenes and the Chinese pilgrim Xuanzang, add an outsider’s view. Comparing these sources helps us build a fuller picture."}]'::jsonb, '[{"topic":"History","question":"Which mahajanapada became the most powerful?","options":["Kosala","Magadha","Avanti","Vatsa"],"correct_index":1,"explanation":"Magadha became the strongest."},{"topic":"History","question":"Which war changed Ashoka’s mind about fighting?","options":["The Kalinga war","The Battle of Panipat","The Battle of Tarain","The Battle of Plassey"],"correct_index":0,"explanation":"After Kalinga, Ashoka turned to dhamma."},{"topic":"History","question":"Aryabhata is famous for his work in…","options":["astronomy and mathematics","painting","music","architecture"],"correct_index":0,"explanation":"He wrote on astronomy and mathematics."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class9-geography', 'Earth and Climate', 'Geography', 'class', 'Class 9', '', 'How the Earth’s surface is shaped, the air and climate.', 11) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-2', 3, 'class9-geography', 'Shaping of the Earth’s surface', 'Our Earth', 'Geography', 0, 'Mountains rise, rivers carve valleys, and coasts change shape. Let’s see what shapes our Earth!', '["Forces inside the Earth (endogenic forces) build landforms through earthquakes, volcanoes and folding.","Forces on the surface (exogenic forces), like rivers, wind, waves and glaciers, wear land down and build new forms.","The Earth’s crust is broken into plates that move slowly; the Himalayas rose when the Indian plate pushed into the Eurasian plate.","Weathering breaks rocks where they are; erosion carries the pieces away; deposition lays them down elsewhere.","River work makes valleys, waterfalls, meanders and deltas; wind makes sand dunes; glaciers make U-shaped valleys."]'::jsonb, 'The Himalayas are young fold mountains and are still rising a few millimetres every year.', '[{"heading":"A planet that keeps changing","text":"The Earth’s surface may look fixed, but it is always changing. Some changes are sudden, like an earthquake or a volcanic eruption. Most are very slow, like a river cutting a valley over millions of years. Geographers group the forces that shape the land into two kinds. Endogenic forces come from deep inside the Earth and usually build up the land. Exogenic forces act on the surface and usually wear the land down. Together they create the mountains, plains and coasts we see."},{"heading":"Moving plates","text":"The Earth’s outer shell is broken into huge pieces called plates, which float on hot, soft rock below and move a few centimetres a year. Where plates pull apart, molten rock rises and new crust forms. Where they push together, one plate may sink beneath the other, or the rocks crumple upwards into mountains. Millions of years ago, the Indian plate moved north and crashed into the Eurasian plate. The rocks between were folded and lifted to form the Himalayas, which are still rising today."},{"heading":"Earthquakes and volcanoes","text":"When rocks along a crack in the crust, called a fault, suddenly slip, the ground shakes in an earthquake. The place where it starts underground is the focus, and the point above it on the surface is the epicentre. Volcanoes form where magma finds a way to the surface as lava, ash and gas. Many earthquakes and volcanoes happen along plate edges. India’s Himalayan region and the north-east are prone to earthquakes, and Barren Island in the Andamans is an active volcano."},{"heading":"Weathering, erosion and deposition","text":"On the surface, heat, cold, rain and plant roots slowly break rocks apart where they lie. This is weathering. Running water, wind, waves and moving ice then carry the broken pieces away, which is erosion. When these agents slow down, they drop their load, building new land: this is deposition. A river carries soil from the mountains and spreads it over the plains, which is why river plains are so fertile and support so many people."},{"heading":"Landforms we can see","text":"Rivers make V-shaped valleys in the hills, waterfalls where they drop over hard rock, loops called meanders on flat land, and deltas at their mouths, like the huge Ganga–Brahmaputra delta. Glaciers carve wide U-shaped valleys and leave piles of rock called moraines. Waves cut cliffs and caves along coasts and build beaches. In deserts such as the Thar, wind piles sand into dunes. Understanding these forces helps us plan safer cities, protect soil and prepare for disasters."},{"heading":"Living with natural hazards","text":"Some of the same forces that shape the land can be dangerous. Earthquakes, landslides, floods and volcanic eruptions can destroy homes and take lives. We cannot stop these forces, but we can reduce the damage. Building earthquake-safe houses, not cutting forests on steep slopes, warning people early and practising safety drills all save lives. Knowing how the Earth works is the first step to living safely with it."}]'::jsonb, '[{"topic":"Geography","question":"Forces that work from inside the Earth are called…","options":["exogenic","endogenic","erosion","deposition"],"correct_index":1,"explanation":"Endogenic forces work from inside the Earth."},{"topic":"Geography","question":"The Himalayas formed when the Indian plate pushed into…","options":["the African plate","the Eurasian plate","the Pacific plate","the Arabian Sea"],"correct_index":1,"explanation":"It collided with the Eurasian plate."},{"topic":"Geography","question":"Breaking of rocks where they are is called…","options":["weathering","deposition","folding","migration"],"correct_index":0,"explanation":"That is weathering."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-3', 3, 'class9-geography', 'Atmosphere and climate', 'Our Earth', 'Geography', 1, 'Why is Rajasthan dry and Meghalaya wet? Let’s study the air and climate!', '["The atmosphere is mostly nitrogen (about 78%) and oxygen (about 21%).","Weather is the state of the air on a given day; climate is the average pattern over about 30 years or more.","Climate depends on latitude, height above sea level, distance from the sea, winds and relief.","India has a monsoon climate: the south-west monsoon brings most of its rain from June to September.","Climate change, caused largely by greenhouse gases from burning fossil fuels, is warming the Earth."]'::jsonb, 'Mawsynram in Meghalaya is one of the rainiest places on Earth.', '[{"heading":"Our blanket of air","text":"The atmosphere is a layer of air held around the Earth by gravity. It is mostly nitrogen and oxygen, with small amounts of argon, carbon dioxide and water vapour. It gives us oxygen to breathe, keeps the planet warm enough for life and protects us from harmful rays and small meteors. The lowest layer, the troposphere, is where clouds form and weather happens. Above it, the stratosphere contains the ozone layer, which absorbs much of the Sun’s harmful ultraviolet radiation."},{"heading":"Weather and climate","text":"Weather is the condition of the air at a place over a short time: whether it is hot or cold, wet or dry, calm or windy today. Climate is the usual pattern of weather over a long time, about thirty years or more. So we might say “it is raining in Mumbai today” (weather), but “Mumbai has a hot, humid climate with heavy summer rain” (climate). Temperature, air pressure, wind, humidity and rainfall are the main elements we measure."},{"heading":"What decides climate","text":"Several factors shape a place’s climate. Places near the Equator get more direct sunlight and are hot, while places far from it are cooler. Temperature falls as height increases, which is why hill stations like Shimla are cool. Places near the sea have mild climates, while places far inland have very hot summers and cold winters. Winds and mountains matter too: moist winds that rise over hills drop heavy rain, leaving the land behind them dry."},{"heading":"India’s monsoon","text":"India has a monsoon climate, which means the winds change direction with the seasons. In summer the land heats up, and moist winds blow in from the Indian Ocean from the south-west. They usually reach Kerala around the start of June and bring most of India’s rain by September. The Western Ghats and the north-east get very heavy rain; Mawsynram in Meghalaya is one of the rainiest places on Earth. In winter, dry winds blow from the land towards the sea."},{"heading":"A changing climate","text":"Burning coal, oil and gas releases carbon dioxide and other greenhouse gases, which trap heat in the atmosphere. Cutting forests adds to the problem. As a result, the Earth is getting warmer. This brings stronger heatwaves, melting glaciers, rising seas and less predictable rain, which can hurt farmers and coastal communities. Countries are working to cut emissions by using solar and wind power. We can help by saving electricity, using public transport and planting trees."},{"heading":"Measuring the weather","text":"Weather scientists use instruments to measure the air. A thermometer measures temperature, a barometer measures air pressure, a rain gauge measures rainfall, and a wind vane shows wind direction. Today satellites and computers also help. In India, the India Meteorological Department (IMD) collects this data, forecasts the monsoon and warns people about cyclones and heatwaves, helping farmers, fishers and everyone else plan ahead."}]'::jsonb, '[{"topic":"Geography","question":"Climate is the average weather over about…","options":["one day","one month","one year","30 years or more"],"correct_index":3,"explanation":"Climate describes long-term patterns."},{"topic":"Geography","question":"India gets most of its rain from…","options":["the south-west monsoon","western disturbances","cyclones only","snow"],"correct_index":0,"explanation":"The south-west monsoon, June to September."},{"topic":"Geography","question":"Which gas makes up most of the air?","options":["Oxygen","Nitrogen","Carbon dioxide","Ozone"],"correct_index":1,"explanation":"Nitrogen is about 78% of the air."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class9-civics', 'Democracy and Elections', 'Politics', 'class', 'Class 9', '', 'What democracy means and how India votes.', 12) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-6', 3, 'class9-civics', 'Democracy', 'Democracy and elections', 'Politics', 0, 'India is the world’s largest democracy. But what makes a country a democracy? Let’s find out!', '["Democracy is a form of government in which rulers are chosen by the people.","Abraham Lincoln called it “government of the people, by the people, for the people”.","In a direct democracy, citizens decide themselves, as in ancient Athens; in a representative democracy, they elect representatives.","Key features: free and fair elections, one person one vote, rule of law and respect for rights.","Ideas of discussion and shared decisions in India go back to assemblies like the sabha, samiti and the ganas."]'::jsonb, 'India is the largest democracy in the world by number of voters.', '[{"heading":"What democracy means","text":"The word democracy comes from two Greek words: demos, meaning people, and kratos, meaning rule. So democracy means rule by the people. In a democracy, the final power to choose the government rests with ordinary citizens, not with a king, an army or a small group of rich families. Abraham Lincoln, a President of the USA, described it as “government of the people, by the people, for the people”. Today most countries in the world call themselves democracies, though they work in different ways."},{"heading":"Direct and representative democracy","text":"In ancient Athens, citizens met in an assembly and voted directly on laws and wars. This is direct democracy. It works for small communities, and something similar happens in an Indian village Gram Sabha. But a country of hundreds of millions cannot meet in one place. So we elect representatives, such as members of Parliament and state assemblies, who make laws on our behalf. This is representative democracy. If they do not serve us well, we can vote them out at the next election."},{"heading":"What makes a real democracy","text":"Holding elections is not enough. Elections must be free and fair, with a real choice between parties. Every adult should have one vote, and each vote should count equally. The government must follow the Constitution and the law, and courts must be independent. Citizens need freedom of speech and a free press to learn what is happening and to criticise leaders. The rights of minorities must be protected, so that the majority cannot treat others unfairly."},{"heading":"Roots of democracy in India","text":"Ideas of discussion and collective decisions have a long history in India. The Vedic sabha and samiti were assemblies, and the ganas and sanghas of ancient times were run by councils. Buddhist monasteries made decisions through discussion and voting. Modern Indian democracy grew out of the freedom struggle and was shaped by the Constitution, which gave every adult citizen the right to vote from the very first election, whatever their wealth, education, caste or gender."},{"heading":"Why democracy is valued","text":"Democracy is not perfect. Decisions can be slow, and problems such as poverty, corruption and misinformation still exist. Yet it has big advantages. Leaders must answer to the people. Mistakes can be corrected peacefully. Disagreements are settled by discussion and voting rather than by force. Everyone has dignity and an equal say. Democracy works best when citizens are informed, respect each other’s views and take part, not only by voting but by speaking up for the common good."},{"heading":"Democracy in daily life","text":"Democracy is not only about governments; it is also a way of living together. In a family, school or club, a democratic way means listening to everyone, discussing problems, and taking decisions fairly, perhaps by voting. A class monitor chosen by classmates, a housing society that holds meetings, or a Gram Sabha discussing a new road are all small examples of democracy at work in everyday life."}]'::jsonb, '[{"topic":"Politics","question":"Who described democracy as “government of the people, by the people, for the people”?","options":["Mahatma Gandhi","Abraham Lincoln","Winston Churchill","Dr B. R. Ambedkar"],"correct_index":1,"explanation":"Abraham Lincoln said it."},{"topic":"Politics","question":"Ancient Athens is an example of…","options":["direct democracy","monarchy","dictatorship","representative democracy"],"correct_index":0,"explanation":"Citizens there voted directly in assemblies."},{"topic":"Politics","question":"Which is NOT a feature of democracy?","options":["Free and fair elections","Rule of law","One person ruling forever without elections","Equal vote"],"correct_index":2,"explanation":"Democracy needs regular elections."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-7', 3, 'class9-civics', 'Elections', 'Democracy and elections', 'Politics', 1, 'Elections are the festival of democracy! Let’s see how India votes.', '["The Election Commission of India (Article 324) conducts elections; it was set up on 25 January 1950, now National Voters’ Day.","India’s first general election was held in 1951–52; Sukumar Sen was the first Chief Election Commissioner.","The voting age was lowered from 21 to 18 by the 61st Amendment (1988).","Electronic Voting Machines (EVMs) are used, with VVPAT slips that let voters check their vote.","The NOTA (“None of the Above”) option was added in 2013."]'::jsonb, 'Before elections, parties and candidates must follow the Model Code of Conduct.', '[{"heading":"Why we need elections","text":"In a representative democracy, elections are how citizens choose the people who will govern on their behalf. They also let people judge the work of the government and replace it if they are unhappy. In India, elections are held for the Lok Sabha, the state Legislative Assemblies, and local bodies such as panchayats and municipalities. Normally each is elected for five years. Because so many people take part, Indian elections are often called the biggest festival of democracy in the world."},{"heading":"The first general election","text":"India’s first general election, held over several months in 1951–52, was a huge challenge. Most voters could not read, so each party was given a picture symbol, a practice that continues today. Voters dropped ballot papers into boxes marked with these symbols. The election was organised by Sukumar Sen, the first Chief Election Commissioner. Millions of people, rich and poor, men and women, voted for the first time, proving that democracy could work in a large, diverse country."},{"heading":"How an election works","text":"The country is divided into constituencies, and each elects one representative. First, a voter list is prepared. Candidates file nomination papers, which are checked. Parties release manifestos explaining their plans and campaign through meetings and media. On polling day, voters cast a secret vote, today on Electronic Voting Machines with a VVPAT slip they can see. Votes are then counted, and the candidate with the most votes wins. This system is called first-past-the-post."},{"heading":"Keeping elections free and fair","text":"The Election Commission of India, set up under Article 324 on 25 January 1950, is independent of the government. It announces dates, controls election officials, checks spending and enforces the Model Code of Conduct, which stops parties from misusing government power or making hateful speeches. It can order a re-poll if there is cheating. Since 2013, voters can also choose NOTA, “None of the Above”, if they do not wish to support any candidate."},{"heading":"Every vote counts","text":"In 1988 the 61st Amendment lowered the voting age from 21 to 18, bringing millions of young people into the electorate. Every citizen aged 18 or above can register and vote, whatever their religion, caste, gender or income. 25 January is celebrated as National Voters’ Day to encourage people, especially first-time voters, to register. A high turnout makes the result truly reflect the will of the people. Voting is both a right and a responsibility."},{"heading":"Problems and reforms","text":"Elections in India face challenges too. Some candidates spend huge sums of money, some voters are offered gifts, and false news can spread quickly. Some people with criminal cases also contest. The Election Commission, the courts and citizens’ groups keep pushing for reforms, such as making candidates declare their wealth and criminal record, and limiting election spending. Informed voters who think carefully before voting are the best protection for democracy."}]'::jsonb, '[{"topic":"Politics","question":"National Voters’ Day is on…","options":["26 January","25 January","15 August","2 October"],"correct_index":1,"explanation":"The Election Commission was set up on 25 January 1950."},{"topic":"Politics","question":"Which amendment lowered the voting age to 18?","options":["42nd","44th","61st","73rd"],"correct_index":2,"explanation":"The 61st Amendment (1988)."},{"topic":"Politics","question":"Who was India’s first Chief Election Commissioner?","options":["Sukumar Sen","T. N. Seshan","B. N. Rau","Dr Rajendra Prasad"],"correct_index":0,"explanation":"Sukumar Sen ran the first general election."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class9-economics', 'Economics: First Steps', 'Economy', 'class', 'Class 9', '', 'Scarcity, choices, production, demand and prices.', 13) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-8', 3, 'class9-economics', 'Building blocks of economics', 'Economics', 'Economy', 0, 'We want many things, but we can’t have everything. That’s where economics begins!', '["Wants are unlimited, but resources like money, time and land are scarce: this is the problem of scarcity.","Because of scarcity, we must make choices.","Opportunity cost is the value of the next best thing you give up when you choose.","The four factors of production are land, labour, capital and entrepreneurship.","Their rewards are rent (land), wages (labour), interest (capital) and profit (entrepreneurship)."]'::jsonb, 'Every economy must answer three questions: what to produce, how to produce, and for whom to produce.', '[{"heading":"Needs, wants and scarcity","text":"Every person has needs, things we must have to live, such as food, water, clothing and shelter. We also have wants, things we would like, such as a bicycle, a phone or a holiday. Our wants keep growing: when one is met, another appears. But the resources needed to satisfy them, like money, time, land, water and raw materials, are limited. This gap between unlimited wants and limited resources is called scarcity. It is the basic problem that economics studies."},{"heading":"Choices and opportunity cost","text":"Because resources are scarce, we must choose how to use them. If you have ₹100, you might buy a book or go to a film, but not both. If you spend Sunday studying, you give up the chance to play cricket. The value of the best thing you give up is called the opportunity cost. Families face such choices when planning a budget, farmers when deciding which crop to grow, and governments when deciding whether to spend more on hospitals, schools or roads."},{"heading":"Goods and services","text":"Economic activity produces goods and services. Goods are things you can touch, like rice, shoes or cars. Services are useful work done for others, like teaching, banking, transport or medical care. Some goods are used directly by families (consumer goods), while others, like machines and tools, are used to make more goods (capital goods). In India today, services make up the largest part of production, though farming still employs many people."},{"heading":"Factors of production","text":"To produce anything, we need four kinds of inputs. Land includes all natural resources, such as soil, water, forests and minerals. Labour is the physical and mental work of people. Capital means man-made aids to production, such as tools, machines, buildings and money for investment. Entrepreneurship is the skill of bringing the other three together, taking risks and starting new ventures. Their rewards are rent for land, wages for labour, interest for capital and profit for the entrepreneur."},{"heading":"Three big questions","text":"Every economy, whether a village or a whole country, must answer three questions. What should be produced, and how much? How should it be produced: with more machines or more workers? For whom should it be produced, or how should the output be shared? In a market economy, prices help answer these questions. In other systems, the government plays a bigger role. India has a mixed economy, where both markets and the government work together."},{"heading":"Economics around you","text":"Economics is part of daily life. When your family decides how much to save, when a shopkeeper decides what to stock before Diwali, or when the government decides how to spend tax money, they are all solving economic problems. Learning economics helps you understand why some things are costly, why jobs grow in some places and not others, and how to make the best use of what you have."}]'::jsonb, '[{"topic":"Economy","question":"The value of the next best choice given up is called…","options":["profit","opportunity cost","rent","tax"],"correct_index":1,"explanation":"That is opportunity cost."},{"topic":"Economy","question":"The reward for labour is…","options":["rent","interest","wages","profit"],"correct_index":2,"explanation":"Workers earn wages."},{"topic":"Economy","question":"Why must we make choices?","options":["Resources are scarce","Wants are few","Everything is free","Prices never change"],"correct_index":0,"explanation":"Scarcity forces us to choose."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class9-sst-9', 3, 'class9-economics', 'The price puzzle', 'Economics', 'Economy', 1, 'Why are mangoes cheap in summer and costly in winter? Let’s solve the price puzzle!', '["Demand is how much of a good people want and can pay for at a price.","Law of demand: when the price rises, people usually buy less; when it falls, they buy more.","Supply is how much sellers are ready to sell; when the price rises, sellers usually offer more.","The market price settles where demand and supply meet: the equilibrium price.","The government announces a Minimum Support Price (MSP) for some crops to protect farmers from very low prices."]'::jsonb, 'Prices of seasonal goods, like fruits and vegetables, change a lot because supply changes with the season.', '[{"heading":"Why prices matter","text":"A price is the amount of money we pay to buy a good or service. Prices act like signals in the economy. A high price tells sellers that people want more of something and encourages them to produce it. A low price tells them to produce less, or to switch to something else. For buyers, prices help decide what they can afford. To understand why prices go up and down, economists look at two forces: demand and supply."},{"heading":"Demand","text":"Demand is the amount of a good that people are willing and able to buy at different prices. Usually, when the price of something rises, people buy less of it, and when the price falls, they buy more. This is called the law of demand. Demand also depends on people’s income, their tastes, festivals and seasons, and the prices of related goods. For example, if the price of tea rises sharply, some people may switch to coffee."},{"heading":"Supply","text":"Supply is the amount that sellers are willing to sell at different prices. When prices rise, sellers usually want to sell more, because they can earn more. Supply also depends on the cost of raw materials, the technology used, the number of sellers and, for crops, the weather. A good monsoon can bring a big harvest and plenty of supply. A drought, flood or pest attack can cut supply suddenly, pushing prices up."},{"heading":"Where demand meets supply","text":"In a market, the price keeps moving until the amount buyers want equals the amount sellers offer. This is the equilibrium price. If the price is too high, goods remain unsold, so sellers lower it. If the price is too low, there is a shortage, and buyers are willing to pay more, so the price rises. That is why mangoes are cheap in early summer when markets are full of them, and costly out of season."},{"heading":"When the government steps in","text":"Sometimes market prices can hurt people. If crop prices crash after a bumper harvest, farmers may not even recover their costs. So the government announces a Minimum Support Price (MSP) for several crops, such as wheat and rice, and buys from farmers at that price. It also sells food grains at low prices to poor families through the public distribution system. In this way, the government tries to balance fair prices for farmers with affordable food for consumers."},{"heading":"Prices and families","text":"Rising prices affect families in different ways. A small increase in the price of vegetables or cooking gas may not trouble a rich family, but it can hurt a poor family that spends most of its income on food. When prices of most things rise over time, this is called inflation. Understanding demand and supply helps us see why prices change, and why governments and the Reserve Bank watch prices so carefully."}]'::jsonb, '[{"topic":"Economy","question":"According to the law of demand, when price rises…","options":["people buy more","people usually buy less","demand stays the same always","supply falls to zero"],"correct_index":1,"explanation":"Higher prices usually reduce the quantity bought."},{"topic":"Economy","question":"The price where demand equals supply is the…","options":["equilibrium price","MSP","tax price","maximum price"],"correct_index":0,"explanation":"That is the equilibrium price."},{"topic":"Economy","question":"MSP protects…","options":["shopkeepers","farmers","banks","importers"],"correct_index":1,"explanation":"It protects farmers from very low crop prices."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class10-history', 'Making the Modern World', 'History', 'class', 'Class 10', '', 'Nationalism in Europe and India, the world economy, industry and print.', 14) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-history-1', 3, 'class10-history', 'The rise of nationalism in Europe', 'Nationalism', 'History', 0, 'How did people in Europe start to feel they belonged to one nation? Let’s find out!', '["The French Revolution of 1789 spread the ideas of liberty, equality and a nation of citizens.","Napoleon’s Civil Code of 1804 ended privileges based on birth but took away political freedom.","After Napoleon’s defeat, the Congress of Vienna (1815), led by the Austrian minister Metternich, tried to bring back the old order.","Giuseppe Mazzini founded Young Italy in 1831 to work for a united, free Italy.","Germany was united in 1871 under Otto von Bismarck; Italy was united through Cavour, Garibaldi and King Victor Emmanuel II.","Rivalries in the Balkans helped lead to the First World War."]'::jsonb, 'Nations were often shown as women in art, like Marianne for France and Germania for Germany.', '[{"heading":"What is a nation?","text":"Today we take it for granted that the world is divided into nations, each with its own flag, anthem and government. But this idea is quite new. Two hundred and fifty years ago, much of Europe was ruled by kings and emperors over people who spoke many languages and felt loyal to their region or ruler, not to a “nation”. Nationalism is the feeling that people who share a history, language or culture belong together and should rule themselves."},{"heading":"The French Revolution","text":"The revolution of 1789 in France changed everything. Power passed from the king to a body of citizens. New symbols, such as the tricolour flag, a national anthem and the idea of la patrie (the fatherland), helped create a shared identity. A uniform system of laws and weights and measures was introduced, and French became the common language. Revolutionaries believed France had a duty to free other peoples of Europe from their kings."},{"heading":"Napoleon and after","text":"Napoleon conquered much of Europe. His Civil Code of 1804 made all people equal before the law, protected property and removed feudal dues, but he ruled as a dictator and controlled the press. After his defeat in 1815, the great powers met at the Congress of Vienna. Led by the Austrian minister Metternich, they restored old royal families and tried to crush liberal and national ideas. Secret societies and students kept these ideas alive."},{"heading":"Revolutions and romantic ideas","text":"In 1830 and again in 1848, revolts broke out across Europe as people demanded constitutions, freedom of the press and national unity. Writers, artists and musicians of the Romantic movement celebrated folk songs, poetry and the history of ordinary people as the heart of the nation. Greece won independence from the Ottoman Empire in 1832 with wide European support. In 1848, an elected Frankfurt Parliament tried to unite Germany, but it failed."},{"heading":"Unifying Germany and Italy","text":"Germany was finally united not by the people but by the Prussian state. Its chief minister, Otto von Bismarck, used wars against Denmark, Austria and France, and in 1871 the Prussian king was proclaimed German Emperor. Italy was divided into several states. Mazzini spread the dream of unity; Count Cavour, the minister of Sardinia-Piedmont, used diplomacy; and Giuseppe Garibaldi led his volunteer Red Shirts in the south. In 1861 Victor Emmanuel II became king of a united Italy."},{"heading":"Nationalism turns aggressive","text":"By the late 19th century, nationalism had changed. It was used by powerful states to justify building empires and competing for colonies. In the Balkans, many peoples wanted to break free from the Ottoman Empire, while big powers like Russia, Germany, Britain and Austria-Hungary competed for influence. This tension made the region a “powder keg” and helped spark the First World War in 1914. At the same time, ideas of nationalism inspired colonised peoples, including Indians, to fight for freedom."}]'::jsonb, '[{"topic":"History","question":"Who founded the secret society Young Italy?","options":["Giuseppe Garibaldi","Count Cavour","Giuseppe Mazzini","Victor Emmanuel II"],"correct_index":2,"explanation":"Mazzini founded Young Italy in 1831."},{"topic":"History","question":"Germany was united in 1871 mainly under…","options":["Napoleon","Metternich","Bismarck","Garibaldi"],"correct_index":2,"explanation":"Otto von Bismarck led German unification."},{"topic":"History","question":"The Congress of Vienna (1815) aimed to…","options":["spread democracy","restore the old monarchies","unite Italy","free the colonies"],"correct_index":1,"explanation":"It tried to bring back the old order after Napoleon."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-history-2', 3, 'class10-history', 'Nationalism in India', 'Nationalism', 'History', 1, 'How did millions of Indians come together against British rule? Let’s walk with Gandhiji!', '["The First World War brought high taxes, rising prices and forced recruitment, which angered many Indians.","The Rowlatt Act (1919) allowed detention without trial; on 13 April 1919, troops fired on a crowd at Jallianwala Bagh in Amritsar.","The Non-Cooperation Movement (1920–22), joined with the Khilafat movement, was called off after violence at Chauri Chaura.","The Civil Disobedience Movement began with the Salt March from Sabarmati to Dandi in 1930.","Dr B. R. Ambedkar and Gandhi signed the Poona Pact in 1932.","Songs, symbols and images, such as Bharat Mata and the tricolour, built a sense of a shared nation."]'::jsonb, 'The image of Bharat Mata was famously painted by Abanindranath Tagore.', '[{"heading":"A new kind of struggle","text":"In India, as in many colonies, nationalism grew together with the fight against foreign rule. People of different regions, languages and religions began to feel that they shared a common problem: colonial rule. The First World War made life harder. Taxes and prices rose, villages were forced to supply soldiers, and crops failed in many areas. When Mahatma Gandhi returned from South Africa in 1915, he brought a new method of struggle: satyagraha, the power of truth and non-violent resistance."},{"heading":"Rowlatt Act and Jallianwala Bagh","text":"In 1919, the British passed the Rowlatt Act, which let them jail political activists without trial. Gandhi called for a nationwide protest. On 13 April 1919, a large crowd gathered in the walled garden of Jallianwala Bagh in Amritsar. General Dyer blocked the exit and ordered his troops to fire, killing hundreds. The massacre shocked India. Many people who had trusted British justice now turned against colonial rule."},{"heading":"Non-Cooperation and Khilafat","text":"Gandhi believed British rule survived only because Indians cooperated with it. In 1920, the Congress launched the Non-Cooperation Movement. Students left government schools, lawyers gave up their practice, foreign cloth was burnt and liquor shops were picketed. Hindus and Muslims joined hands through the Khilafat movement. Peasants in Awadh, tribal people in the Gudem hills of Andhra and plantation workers in Assam joined in their own ways. After a violent clash at Chauri Chaura in 1922, Gandhi called the movement off."},{"heading":"Salt and civil disobedience","text":"The Simon Commission of 1928 had no Indian members and was greeted with protests. In 1929, at Lahore, the Congress demanded Purna Swaraj, complete independence. In March 1930, Gandhi set out on the Salt March from Sabarmati to Dandi on the Gujarat coast and broke the salt law by making salt from sea water. This began the Civil Disobedience Movement: people refused to pay taxes, boycotted foreign goods and broke unjust laws peacefully."},{"heading":"Different voices","text":"Not everyone saw swaraj in the same way. Rich peasants wanted lower revenue; poor peasants wanted rents cancelled. Business groups wanted protection from foreign goods. Women joined marches in large numbers. Dr B. R. Ambedkar organised the Depressed Classes and demanded separate electorates for Dalits; after Gandhi’s fast, the two agreed on the Poona Pact of 1932, which reserved seats for them in legislatures. Some Muslim leaders worried about their place in a Hindu-majority nation."},{"heading":"Feeling like one nation","text":"A sense of belonging also grew through culture. Bankim Chandra Chattopadhyay’s song Vande Mataram became a rallying cry. Abanindranath Tagore painted Bharat Mata, an image of the nation as a mother. Folk tales and songs were collected as part of a shared heritage. During the Swadeshi movement a tricolour flag appeared, and by 1921 Gandhi had designed a flag with a spinning wheel at its centre. History was reinterpreted to show India’s great past, inspiring people to struggle for freedom."}]'::jsonb, '[{"topic":"History","question":"Why was the Non-Cooperation Movement called off in 1922?","options":["Freedom was won","The violence at Chauri Chaura","Gandhi went abroad","The British agreed to all demands"],"correct_index":1,"explanation":"Gandhi stopped it after violence at Chauri Chaura."},{"topic":"History","question":"The Poona Pact of 1932 was signed by Gandhi and…","options":["Jawaharlal Nehru","Dr B. R. Ambedkar","Lord Irwin","Muhammad Ali Jinnah"],"correct_index":1,"explanation":"It was signed by Gandhi and Dr Ambedkar."},{"topic":"History","question":"Who painted the famous image of Bharat Mata?","options":["Raja Ravi Varma","Abanindranath Tagore","Nandalal Bose","Amrita Sher-Gil"],"correct_index":1,"explanation":"Abanindranath Tagore painted Bharat Mata."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-history-3', 3, 'class10-history', 'The making of a global world', 'The world economy', 'History', 2, 'Noodles, potatoes and people have travelled the world for centuries. Let’s follow them!', '["The silk routes linked Asia, Europe and Africa for trade, ideas and religions long before modern times.","Foods travelled too: potatoes, maize, tomatoes and chillies came to Asia and Europe from the Americas.","In the 19th century, Indian indentured labourers were taken to places like the Caribbean, Fiji and Mauritius to work on plantations.","The Great Depression began in 1929 and caused a huge fall in prices, trade and jobs around the world.","After the Second World War, the Bretton Woods conference (1944) set up the IMF and the World Bank."]'::jsonb, 'When the potato crop failed in Ireland in the 1840s, about a million people died of starvation.', '[{"heading":"An old story of connections","text":"Globalisation may sound like a modern word, but people have been linked across great distances for thousands of years. Traders, travellers, pilgrims and soldiers carried goods, ideas, diseases and skills from one land to another. The silk routes, a network of land and sea paths, joined China and India with Central Asia, West Asia, Africa and Europe. Silk and spices went west; gold and silver came east; and Buddhism, Christianity and Islam spread along these routes too."},{"heading":"Food, conquest and disease","text":"After Columbus reached the Americas in 1492, crops such as potatoes, maize, tomatoes and chillies spread around the world and changed diets. But the Spanish conquest of the Americas was also deadly: diseases like smallpox, carried by Europeans, killed huge numbers of local people. Silver from American mines enriched Europe. In Ireland, poor families came to depend so much on potatoes that when the crop failed in the 1840s, about a million people died and many more emigrated."},{"heading":"The 19th-century world economy","text":"In the 1800s, trade, migration and investment grew enormously. Britain imported cheap food grains and exported factory goods. Railways, steamships and the telegraph shrank distances, and refrigerated ships could carry meat across oceans. European powers divided Africa among themselves. A cattle disease called rinderpest, which reached Africa in the 1890s, killed most of the cattle there, forcing many Africans to work for wages on European farms and mines."},{"heading":"Indentured labour","text":"Many poor Indians, especially from eastern Uttar Pradesh, Bihar and central India, signed contracts to work abroad on plantations, mines and railways in places like the Caribbean, Fiji, Mauritius and Malaysia. Life was very hard and many could not return. Yet they built new cultures, blending Indian traditions with local ones; for example, chutney music in Trinidad and Guyana. Indian traders and bankers also financed trade in many parts of Asia and Africa."},{"heading":"War and the Great Depression","text":"The First World War disrupted trade and left Europe in debt. In 1929 the Great Depression began: prices of farm goods collapsed, banks failed, factories closed and millions lost their jobs, starting in the USA and spreading worldwide. In India, prices of crops like wheat and jute fell by half, but the colonial government still demanded full revenue. Peasants sold their land and even gold, and their anger fed the Civil Disobedience Movement."},{"heading":"After 1945","text":"To avoid another depression, world leaders met at Bretton Woods in the USA in 1944. They set up the International Monetary Fund, to deal with countries’ money problems, and the World Bank, to fund reconstruction and development. Newly free countries such as India joined, but many felt these bodies were controlled by rich nations. They formed groups like the G-77 to demand a fairer world economic order. From the 1990s, trade and investment grew rapidly again in a new wave of globalisation."}]'::jsonb, '[{"topic":"History","question":"Which conference set up the IMF and the World Bank?","options":["Versailles","Vienna","Bretton Woods","Yalta"],"correct_index":2,"explanation":"The Bretton Woods conference of 1944."},{"topic":"History","question":"The Great Depression began in…","options":["1914","1929","1939","1947"],"correct_index":1,"explanation":"It began in 1929."},{"topic":"History","question":"Potatoes reached Europe from…","options":["India","China","the Americas","Africa"],"correct_index":2,"explanation":"Potatoes came from the Americas."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-history-4', 3, 'class10-history', 'The age of industrialisation', 'The world economy', 'History', 3, 'Machines changed how the world made things. Let’s see how factories came to Britain and India!', '["Before factories, merchants paid village families to spin and weave at home: this is called proto-industrialisation.","Cotton was the leading industry of Britain’s Industrial Revolution; Richard Arkwright built an early cotton mill.","James Watt improved the steam engine, which later powered factories, trains and ships.","Indian weavers suffered as the East India Company controlled them through paid agents (gomasthas) and cheap British cloth flooded in.","The first cotton mill in Bombay opened in 1854; Indian businessmen like Jamsetji Tata later built industries."]'::jsonb, 'During the First World War, imports fell and Indian factories grew quickly to meet the demand.', '[{"heading":"Before the factories","text":"Long before big factories, there was a lot of production for international markets. In England and Europe, merchants gave raw materials to peasant families in villages, who spun, wove and dyed at home. The merchants then sold the finished goods. Historians call this proto-industrialisation. It let merchants avoid the powerful town guilds, and gave poor rural families extra income. Much early industrial growth came from this system, not only from machines."},{"heading":"The coming of the factory","text":"From the late 18th century, factories began to grow in Britain. Cotton was the leading industry. New machines like the spinning jenny and Richard Arkwright’s water frame, and later his cotton mill, brought all the stages of production under one roof. James Watt’s improved steam engine provided steady power. Iron and steel industries grew, and railways spread. Still, change was slow, and for a long time hand labour remained common because it was cheap and flexible."},{"heading":"Life for workers","text":"Factory work was hard. Workers, including children, often worked long hours in crowded, unsafe conditions. Jobs were uncertain, and in winter many lost work. When the spinning jenny came, some women who earned a living by hand-spinning attacked the machines, fearing for their jobs. Over time, workers formed trade unions and campaigned for better wages, shorter hours and laws against child labour."},{"heading":"India’s weavers","text":"Before industrialisation, Indian silk and cotton cloth was famous around the world, sold by Armenian, Persian and Indian merchants through ports like Surat, Hooghly and Masulipatnam. After the East India Company gained power, it appointed paid agents called gomasthas to control weavers and stop them selling to others. Weavers were often paid too little. In the 19th century, cheap machine-made cloth from Manchester flooded Indian markets, and many weavers lost their livelihood."},{"heading":"Factories come to India","text":"The first cotton mill in Bombay opened in 1854, and jute mills grew around Calcutta. Indian businessmen who had made money in trade, such as Dwarkanath Tagore in Bengal and Jamsetjee Jeejeebhoy in Bombay, invested in industry. Jamsetji Tata planned a steel works at Jamshedpur. During the First World War, imports from Britain fell, and Indian mills got large orders for army supplies, so Indian industry grew quickly. Workers came from nearby districts and often kept links with their villages."},{"heading":"Selling the goods","text":"Producers needed buyers, so they used advertisements, labels and calendars. Labels showed images of gods, goddesses or famous figures to make products seem trustworthy and familiar. Indian manufacturers used nationalist messages like “made in India” and swadeshi to sell their goods against foreign brands. Handloom production also survived and even grew, as weavers used new technology like the fly shuttle and made fine cloth that machines could not easily copy."},{"heading":"Looking back","text":"Industrialisation changed how people lived and worked, in Britain and in India. It brought new goods, new jobs and growing cities, but also hard working conditions and the decline of many traditional crafts. In India, the story was tied to colonial rule: British policies often favoured British industry. Yet Indian entrepreneurs and workers built their own mills and factories, laying the foundations of the modern Indian economy after independence."}]'::jsonb, '[{"topic":"History","question":"Village production for merchants before factories is called…","options":["proto-industrialisation","globalisation","colonisation","urbanisation"],"correct_index":0,"explanation":"That is proto-industrialisation."},{"topic":"History","question":"Who improved the steam engine?","options":["Richard Arkwright","James Watt","Isaac Newton","Henry Ford"],"correct_index":1,"explanation":"James Watt improved the steam engine."},{"topic":"History","question":"The first cotton mill in Bombay opened in…","options":["1757","1820","1854","1905"],"correct_index":2,"explanation":"It opened in 1854."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-history-5', 3, 'class10-history', 'Print culture and the modern world', 'Ideas and print', 'History', 4, 'Printed books and newspapers changed how people think. Let’s see how print spread!', '["The earliest printing was done with wooden blocks in China, Korea and Japan.","Johann Gutenberg developed a printing press with movable metal type in Germany in the 15th century; the Bible was among the first books he printed.","Martin Luther’s writings, spread by print from 1517, helped start the Protestant Reformation.","Portuguese missionaries brought the printing press to Goa in the mid-16th century.","James Augustus Hickey began the Bengal Gazette in 1780; the Vernacular Press Act of 1878 tried to control Indian-language newspapers."]'::jsonb, 'Rashsundari Devi’s Amar Jiban (1876) is one of the first autobiographies written in Bengali.', '[{"heading":"Printing begins in East Asia","text":"The first kind of printing was woodblock printing. A page of text or a picture was carved on a wooden block, inked and pressed onto paper. China used this for a very long time to print books and official papers, and the technique spread to Korea and Japan. Printed books in China were often long folded strips, and in Japan, cheap prints of everyday life, poetry and art became popular in cities."},{"heading":"Gutenberg’s press","text":"In the 15th century, Johann Gutenberg, a German metalworker, developed a printing press using movable metal type. Each letter was a small piece of metal that could be arranged into words and used again. His press could print many copies quickly and cheaply compared with hand copying. One of his first major works was the Bible. Within decades, printing presses spread across Europe, and millions of books were printed."},{"heading":"A reading revolution","text":"As books became cheaper, more people began to read. Ideas could spread widely and quickly. In 1517 Martin Luther wrote criticisms of the Catholic Church; printed copies spread fast, and the Protestant Reformation followed. Religious authorities and kings feared that print could spread dangerous ideas, and some books were banned. In the 18th century, the writings of thinkers like Rousseau and Voltaire helped prepare the ground for the French Revolution."},{"heading":"Print comes to India","text":"India had a rich tradition of handwritten manuscripts on palm leaves and paper in Sanskrit, Persian and many regional languages. Portuguese missionaries brought the printing press to Goa in the mid-16th century. In 1780, James Augustus Hickey started the Bengal Gazette, a weekly magazine. Soon Indians began their own newspapers; Raja Ram Mohan Roy published the Sambad Kaumudi from 1821. Printed books and pamphlets fuelled debates about religion, social reform and caste."},{"heading":"New readers and writers","text":"Print opened doors for women and lower castes. Women began writing about their lives: Rashsundari Devi taught herself to read in secret and wrote Amar Jiban, an autobiography, in 1876. Jyotiba Phule wrote about the injustice of caste in Gulamgiri. Cheap books, called chapbooks in Europe and small booklets in India, reached poor readers. Novels, magazines and calendars became popular, and libraries grew in towns."},{"heading":"Print and nationalism","text":"Newspapers became powerful tools of the national movement. They reported on British misrule and spread nationalist ideas. Leaders like Bal Gangadhar Tilak used his paper Kesari to criticise the government. Alarmed, the British passed the Vernacular Press Act in 1878, which allowed them to punish Indian-language papers that printed “seditious” reports. Yet newspapers kept growing, and print helped people across India imagine themselves as one nation."},{"heading":"Print today","text":"From Gutenberg’s press to mobile phones, every new way of sharing words has changed society. Print made knowledge cheaper and helped people question authority, demand rights and imagine new futures. Today, the internet spreads information even faster, both true and false. The lesson of print history is that reading widely, checking sources and thinking for ourselves are as important now as they were five hundred years ago."}]'::jsonb, '[{"topic":"History","question":"Who developed the printing press with movable metal type?","options":["Martin Luther","Johann Gutenberg","James Watt","Galileo"],"correct_index":1,"explanation":"Johann Gutenberg, in 15th-century Germany."},{"topic":"History","question":"The Vernacular Press Act was passed in…","options":["1780","1857","1878","1919"],"correct_index":2,"explanation":"It was passed in 1878."},{"topic":"History","question":"Who started the Bengal Gazette in 1780?","options":["Raja Ram Mohan Roy","James Augustus Hickey","Bal Gangadhar Tilak","William Carey"],"correct_index":1,"explanation":"James Augustus Hickey started it."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class10-civics', 'How Democracy Works', 'Politics', 'class', 'Class 10', '', 'Power sharing, federalism, diversity, parties and outcomes.', 15) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-civics-1', 3, 'class10-civics', 'Power sharing', 'Sharing power', 'Politics', 0, 'Why do democracies share power instead of giving it all to one group? Let’s compare Belgium and Sri Lanka!', '["Belgium has Dutch-speaking, French-speaking and a small German-speaking community; it shared power among them to keep peace.","Belgium changed its constitution several times between 1970 and 1993 and created a separate “community government”.","In Sri Lanka, the Sinhala majority made Sinhala the only official language in 1956, which alienated Tamils and led to a long civil war.","Power can be shared among organs of government, levels of government, social groups, and parties and pressure groups.","Power sharing is good both for stability (prudential reason) and because it is the spirit of democracy (moral reason)."]'::jsonb, 'The sharing of power among legislature, executive and judiciary is called a system of checks and balances.', '[{"heading":"The story of Belgium","text":"Belgium is a small country in Europe with a complicated mix of people. Most people in the Flemish region speak Dutch, those in Wallonia speak French, and a small group speaks German. In the capital, Brussels, French speakers are in the majority. For a long time, the French-speaking minority was richer and more powerful, which the Dutch-speaking majority resented. In the 1950s and 1960s, tensions between the communities grew dangerously high."},{"heading":"Belgium’s solution","text":"Instead of letting one group dominate, Belgian leaders shared power. Between 1970 and 1993 they amended their constitution four times. The central government must have equal numbers of Dutch- and French-speaking ministers. Much power was given to the regional governments. Brussels has its own government with both groups represented. A “community government” elected by each language group looks after culture, education and language. This complex system has kept the country united and peaceful."},{"heading":"The story of Sri Lanka","text":"Sri Lanka, an island nation south of India, became independent in 1948. The Sinhala-speaking people form the majority, and Tamil speakers form a large minority, mostly in the north and east. Instead of sharing power, the Sinhala-dominated governments made Sinhala the only official language in 1956, favoured Sinhala applicants for jobs and university places, and promoted Buddhism. Tamils felt treated as second-class citizens."},{"heading":"The cost of majoritarianism","text":"Tamil parties first demanded equal rights and regional autonomy. When these were ignored, some groups turned to armed struggle, and a long and bloody civil war began. Thousands of people were killed and many families became refugees. The war ended only in 2009, leaving deep scars. The lesson is that when a majority forces its will on others, called majoritarianism, it can destroy the unity of a country instead of strengthening it."},{"heading":"Why share power?","text":"There are two kinds of reasons. Prudential reasons are about results: sharing power reduces conflict between groups and keeps the country stable, as Belgium shows. Moral reasons are about values: in a democracy, people have a right to be consulted on how they are governed, so sharing power is part of what democracy means. Both reasons point the same way: power should not be held by one person, one group or one level of government alone."},{"heading":"Forms of power sharing","text":"In modern democracies, power is shared in several ways. Among organs of government, the legislature, executive and judiciary check each other: this is horizontal sharing. Among levels of government, power is divided between the Union, state and local governments: this is vertical sharing. Power is also shared among social groups, for example through reserved seats for weaker sections. Finally, political parties, pressure groups and movements compete for and influence power."},{"heading":"Power sharing in India","text":"India shares power in all these ways. The Constitution divides power among Parliament, the government and the courts, and between the Union, states and local bodies. Seats are reserved for Scheduled Castes, Scheduled Tribes and women in many bodies. Many parties compete and often share power in coalitions. This careful sharing helps a country as diverse as India stay united while giving every group a voice."}]'::jsonb, '[{"topic":"Politics","question":"Which country made Sinhala its only official language in 1956?","options":["Belgium","Sri Lanka","India","Nepal"],"correct_index":1,"explanation":"Sri Lanka’s 1956 Act made Sinhala the only official language."},{"topic":"Politics","question":"Sharing power between Union, state and local governments is…","options":["horizontal sharing","vertical sharing","majoritarianism","a coalition"],"correct_index":1,"explanation":"Sharing across levels is vertical sharing."},{"topic":"Politics","question":"Belgium’s “community government” is elected by…","options":["the whole country together","people of each language group","the king","the European Union"],"correct_index":1,"explanation":"Each language community elects its own."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-civics-2', 3, 'class10-civics', 'Federalism', 'Sharing power', 'Politics', 1, 'India has a Union government and state governments. How do they share the work? Let’s see!', '["Federalism is a system where power is divided between a central authority and its constituent units, like states.","The Constitution divides subjects into the Union List (like defence and foreign affairs), State List (like police and agriculture) and Concurrent List (like education and forests).","Subjects not in any list, called residuary subjects, go to the Union.","“Coming together” federations include the USA and Switzerland; “holding together” federations include India and Spain.","The 73rd and 74th Amendments (1992) made local government a third level, with one-third of seats reserved for women."]'::jsonb, 'States were reorganised on the basis of language from the 1950s; the States Reorganisation Act was passed in 1956.', '[{"heading":"What is federalism?","text":"In a unitary system, there is one main government, and any local bodies get their powers from it. In a federal system, there are two or more levels of government, each with its own powers given by the constitution. Each level governs the same citizens, but on different subjects. Neither level can take away the other’s powers on its own. Courts act as umpires when there are disputes between levels."},{"heading":"Two routes to federalism","text":"Some federations are formed when independent states come together to make a bigger unit while keeping their identity; examples are the USA, Switzerland and Australia. Here, the states usually have equal power. Other federations are formed when a large country decides to share power with its regions to hold the country together; India, Spain and Belgium are examples. In these, the central government is often stronger."},{"heading":"How India divides power","text":"The Indian Constitution has three lists. The Union List covers matters of national importance, such as defence, foreign affairs, banking and currency. The State List covers matters of state and local importance, like police, trade within the state and agriculture. The Concurrent List covers subjects such as education, forests, marriage and adoption, on which both can make laws; if they clash, the Union law prevails. New subjects, like computer software, go to the Union."},{"heading":"Federalism in practice","text":"The real strength of Indian federalism has come from how it is practised. In the 1950s, many states were redrawn on the basis of language, which helped people feel represented. India has no single national language; Hindi is an official language, and the Constitution recognises many other languages. Over time, when different parties began to rule at the Union and in states, governments learnt to respect each other’s powers."},{"heading":"The third tier","text":"A country as large as India needs government close to the people. In 1992, the 73rd and 74th Amendments made panchayats and municipalities a constitutional third tier. Regular elections are held for them by State Election Commissions, seats are reserved for Scheduled Castes, Scheduled Tribes and backward classes, and at least one-third of seats are reserved for women. States must share some powers and money with these local bodies."},{"heading":"Why decentralisation matters","text":"Local people best understand local problems, like a broken hand-pump or a village road. When decisions are taken close to them, they can take part directly, and leaders are easier to hold accountable. The Gram Sabha, a meeting of all voters of a village, can question its panchayat. Local government has brought millions of people, including many women, into public life. Yet many local bodies still lack enough money and powers."},{"heading":"Language and unity","text":"India’s language policy shows how federalism can keep a diverse country together. Instead of forcing one language on everyone, the Union government uses Hindi and English for official work, and states use their own languages. The Eighth Schedule of the Constitution recognises 22 languages. This flexibility, unlike the rigid language policy that hurt Sri Lanka, has helped people of every region feel at home in India."}]'::jsonb, '[{"topic":"Politics","question":"On which list is “police”?","options":["Union List","State List","Concurrent List","Residuary"],"correct_index":1,"explanation":"Police is a State List subject."},{"topic":"Politics","question":"Which is a “coming together” federation?","options":["India","Spain","USA","Belgium"],"correct_index":2,"explanation":"The USA was formed by states coming together."},{"topic":"Politics","question":"Residuary subjects belong to…","options":["the states","the Union","local bodies","the courts"],"correct_index":1,"explanation":"The Union government can make laws on them."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-civics-3', 3, 'class10-civics', 'Gender, religion and caste', 'Democracy and diversity', 'Politics', 2, 'How do differences of gender, religion and caste show up in politics? Let’s think about it fairly.', '["The sexual division of labour means society expects women to do housework and men to work outside, though both can do any work.","Feminist movements have worked for equal rights for women in voting, education, jobs and family life.","The 106th Amendment (2023) provides for one-third of seats in the Lok Sabha and state assemblies to be reserved for women.","Communalism is using religion to divide people and seek power; India’s Constitution is secular and has no official religion.","Caste inequality still exists; reformers like Jotiba Phule, Dr Ambedkar and Periyar fought it, and the Constitution bans untouchability."]'::jsonb, 'In panchayats and municipalities, at least one-third of seats are already reserved for women.', '[{"heading":"Differences and democracy","text":"Every society has differences: between women and men, between people of different religions, and between castes. Democracy cannot ignore these differences, because they affect people’s chances in life. At the same time, democracy must stop any difference from becoming a reason to treat people unfairly or to divide the country. The way politics handles these differences can either strengthen or weaken democracy."},{"heading":"Gender and public life","text":"In many societies, girls are expected to help at home and boys to go out and earn. This is called the sexual division of labour. Women do much unpaid work, and in paid jobs they often earn less and face discrimination. Feminist movements around the world have demanded equal rights in voting, education, work and family law. In India, literacy and jobs for women have improved, but gaps remain, and the sex ratio in some areas shows a bias against girls."},{"heading":"Women in politics","text":"For a long time, very few women were elected to Parliament and state assemblies. Reserving seats in panchayats and municipalities for women in 1992 brought lakhs of women into local politics. In 2023, Parliament passed the 106th Constitutional Amendment, which provides for one-third of seats in the Lok Sabha and state assemblies to be reserved for women once the process of redrawing constituencies is done. This is a big step towards equal representation."},{"heading":"Religion and politics","text":"People may express their religious values in public life, and a government may step in to protect religious minorities. But communalism is different: it treats one religion as superior, sees followers of a religion as one community with the same interests, and uses this to win power or attack others. It can lead to riots and violence. To guard against it, the Constitution makes India a secular state, with freedom of religion for all and equality regardless of faith."},{"heading":"Caste and politics","text":"Caste divisions, especially the practice of untouchability, caused great injustice in India. Reformers such as Jotiba Phule, Dr B. R. Ambedkar, Mahatma Gandhi and Periyar Ramaswami worked against them. The Constitution bans untouchability and provides reservations to help disadvantaged groups. Urbanisation, literacy and new jobs have weakened old caste rules. Yet caste still affects marriages, wealth and opportunities, and it often plays a role in elections."},{"heading":"Finding the balance","text":"Caste and religion in politics can have two sides. When disadvantaged groups organise to demand fair treatment, democracy becomes more inclusive. But when caste or religion is used only to win votes, to spread hatred or to ignore real issues like poverty and jobs, it harms democracy. In practice, no party can win in India with the votes of just one caste or religion, so parties must reach out widely. Citizens should judge leaders by their work, not by group labels."},{"heading":"What we can do","text":"Citizens can help by treating everyone as equals in daily life: sharing housework, letting girls study and play as freely as boys, and refusing to judge people by their caste or religion. Questioning stereotypes, standing up against discrimination and voting for leaders who work for all are small steps that together make democracy stronger and fairer."}]'::jsonb, '[{"topic":"Politics","question":"Which amendment reserves one-third of Lok Sabha seats for women?","options":["73rd","86th","101st","106th"],"correct_index":3,"explanation":"The 106th Amendment (2023)."},{"topic":"Politics","question":"Using religion to divide people for power is called…","options":["secularism","communalism","federalism","feminism"],"correct_index":1,"explanation":"That is communalism."},{"topic":"Politics","question":"Expecting women to do housework and men to earn outside is…","options":["the sexual division of labour","universal franchise","federalism","secularism"],"correct_index":0,"explanation":"That is the sexual division of labour."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-civics-4', 3, 'class10-civics', 'Political parties', 'Parties and outcomes', 'Politics', 3, 'Every election has parties with symbols and promises. What do parties actually do? Let’s find out!', '["A political party is a group of people who come together to contest elections and hold power in government.","A party has three parts: leaders, active members and followers.","Parties contest elections, put forward policies, make laws, form and run governments, and play the role of opposition.","India has a multi-party system; the USA and UK are mainly two-party systems.","The anti-defection law (52nd Amendment, 1985) stops elected members from changing parties freely."]'::jsonb, 'The Election Commission recognises parties as national or state parties and gives each a reserved symbol.', '[{"heading":"Why we need parties","text":"Imagine an election where every candidate stood alone, with no parties. Each would make different promises, and no one could form a stable government or be held responsible for its policies. Political parties solve this problem. They bring together people who share ideas about how society should be run, offer voters clear choices, and take responsibility for governing. Modern representative democracy cannot work without parties."},{"heading":"What parties do","text":"Parties choose candidates and contest elections. They put forward programmes and policies in their manifestos, and voters choose among them. The party that wins forms the government and makes laws through the legislature. Parties that lose play the role of opposition: they question and criticise the government and keep it on its toes. Parties also shape public opinion, raise issues and help people reach government schemes and officials."},{"heading":"Kinds of party systems","text":"In some countries, only one party is allowed to rule; this is not democratic, as voters have no real choice. In a two-party system, like the USA or the UK, power usually alternates between two main parties. In a multi-party system, like India, many parties compete, and often no single party wins a majority, so several parties join hands to form a coalition government. Each system grows out of a country’s history and society."},{"heading":"National and state parties","text":"In India, every party must register with the Election Commission. Parties that get a certain share of votes or seats are recognised as state parties or national parties and get a reserved election symbol. National parties have support across many states, while state parties are strong in one or a few states. Over time, state parties have become very important in Indian politics and often share power at the Union level in coalitions."},{"heading":"Challenges for parties","text":"Parties face many criticisms. Some lack internal democracy, with power held by a few leaders. Some become family businesses, with top posts passed within a family. Money and muscle power play a big role in elections, and some candidates have criminal records. Voters sometimes feel that parties offer no meaningful choice. These problems weaken people’s trust in democracy and need to be tackled."},{"heading":"Efforts at reform","text":"Several reforms have been made. The anti-defection law of 1985 stops an elected member from switching parties for personal gain; if they do, they can lose their seat. The Supreme Court has ordered candidates to declare their assets and criminal cases in affidavits, so voters can make informed choices. The Election Commission requires parties to hold organisational elections and file accounts. Above all, informed citizens who join parties and raise their voice can push parties to improve."},{"heading":"Parties and citizens","text":"Parties are only as good as the people in them. When ordinary citizens, including young people, join parties, attend meetings and ask questions, parties become more democratic and responsive. Even those who do not join a party can follow the news, compare manifestos and vote thoughtfully. A healthy democracy needs both strong parties and alert citizens who hold them to account."}]'::jsonb, '[{"topic":"Politics","question":"India has a…","options":["one-party system","two-party system","multi-party system","no-party system"],"correct_index":2,"explanation":"India has many parties competing."},{"topic":"Politics","question":"The anti-defection law came through which amendment?","options":["42nd","44th","52nd","61st"],"correct_index":2,"explanation":"The 52nd Amendment of 1985."},{"topic":"Politics","question":"A government formed by several parties together is a…","options":["coalition","monarchy","federation","commission"],"correct_index":0,"explanation":"That is a coalition government."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-civics-5', 3, 'class10-civics', 'Outcomes of democracy', 'Parties and outcomes', 'Politics', 4, 'Does democracy really deliver? Let’s weigh what it does well and where it falls short.', '["Democracy produces a government that is accountable, responsive and legitimate: chosen by and answerable to the people.","Decisions may take longer in a democracy, but they are more acceptable because they follow discussion.","On economic growth, democracies and dictatorships show mixed records; inequality and poverty remain challenges in many democracies.","Democracies handle social differences better, allowing them to be expressed peacefully.","Democracy promotes the dignity and freedom of every person, including women and disadvantaged groups."]'::jsonb, 'A key test of democracy is that citizens can get information about government decisions, for example through the Right to Information Act (2005).', '[{"heading":"How should we judge democracy?","text":"Most people across the world support democracy, yet many also complain about it: slow decisions, corruption and leaders who ignore them. To judge democracy fairly, we should ask what we can reasonably expect from it. Democracy is a form of government; it creates conditions for achieving goals, but citizens must use those conditions well. We should compare it with other systems, not with an imaginary perfect government."},{"heading":"Accountable and legitimate","text":"The most basic outcome of democracy is a government that is accountable to citizens and responsive to their needs. People elect their leaders and can remove them. Decisions follow rules and procedures, and citizens can find out how decisions were made, for example through the Right to Information Act of 2005. A democratic government is also legitimate: it is the people’s own government, which gives it a moral right to rule."},{"heading":"Economic growth and development","text":"Some people expect democracy to make a country rich quickly. In fact, over the years, some dictatorships have grown faster, while many democracies have grown steadily. Growth depends on many factors, such as population, resources and global conditions, not only on the type of government. But democracy offers something important: even when growth is slow, people can demand that its benefits be shared more fairly."},{"heading":"Inequality and poverty","text":"In many democracies, a small number of very rich people own a large share of wealth, while many people struggle to meet basic needs. Since the poor form a large part of the voters, one might expect governments to focus on them; but this does not always happen. Reducing poverty and inequality remains one of the biggest challenges for democracies, including India."},{"heading":"Handling social differences","text":"No society can fully remove conflicts between groups. Democracies are better at handling them: they allow different groups to express their demands, negotiate and reach compromises peacefully. For this, the majority must work with minorities, and rule by majority must not become rule by one religious or ethnic group. Belgium’s power sharing is an example of handling differences well, while Sri Lanka shows the danger of ignoring them."},{"heading":"Dignity and freedom","text":"Perhaps the greatest strength of democracy is that it respects the dignity and freedom of every individual. Women’s movements and movements of disadvantaged castes have used democratic rights to demand equal treatment, and today discrimination is seen as wrong and illegal. Democracy also allows people to complain about its own weaknesses and to correct them. As long as citizens stay informed and active, democracy can keep improving."},{"heading":"Democracy is a journey","text":"Democracy is never finished. Every generation must work to make it better: to make elections cleaner, governments more responsive, and society more equal. The fact that we can openly discuss democracy’s shortcomings is itself one of its strengths. As young citizens, you can strengthen democracy by staying informed, respecting others’ views, standing up for fairness and, when you turn 18, voting in every election."}]'::jsonb, '[{"topic":"Politics","question":"A democratic government is legitimate because it is…","options":["chosen by the people","the oldest","the richest","never criticised"],"correct_index":0,"explanation":"It is the people’s own government."},{"topic":"Politics","question":"The Right to Information Act was passed in…","options":["1950","1992","2005","2019"],"correct_index":2,"explanation":"The RTI Act was passed in 2005."},{"topic":"Politics","question":"Which is a strength of democracy?","options":["Decisions without discussion","Handling social differences peacefully","One group always ruling","No elections"],"correct_index":1,"explanation":"Democracy lets differences be settled peacefully."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class10-geography', 'India’s Resources', 'Geography', 'class', 'Class 10', '', 'Land, forests, water, farming, minerals, industry and transport.', 16) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-1', 3, 'class10-geography', 'Resources and development', 'Land and resources', 'Geography', 0, 'Land, water, soil and even our skills are resources. Let’s learn to use them wisely!', '["Resources can be classified by origin (biotic, abiotic), exhaustibility (renewable, non-renewable), ownership and status of development.","The Earth Summit at Rio de Janeiro in 1992 adopted Agenda 21 for sustainable development.","Land degradation is caused by mining, overgrazing, deforestation and over-irrigation, which can make soil salty and waterlogged.","India’s main soils are alluvial, black (regur), red and yellow, laterite, arid and forest soils.","Soil is protected by contour ploughing, terrace farming, strip cropping and shelter belts of trees."]'::jsonb, 'Gandhiji said: “There is enough for everybody’s need and not for anybody’s greed.”', '[{"heading":"What makes a resource","text":"Anything in our surroundings that can meet our needs, that we have the technology to use, and that is affordable and acceptable, is a resource. Nature provides the raw materials, but it is human knowledge and effort that turn them into resources. Water in a river becomes a resource when we use it to drink, irrigate fields or make electricity. People themselves, with their skills and ideas, are the most important resource of all."},{"heading":"Kinds of resources","text":"By origin, resources are biotic (living, like forests and fish) or abiotic (non-living, like rocks and metals). By exhaustibility, they are renewable, like sunlight and wind, or non-renewable, like coal and petroleum, which take millions of years to form. By ownership, they may belong to individuals, communities, the nation or the whole world, like the open ocean. By status, they may be potential, developed, stock or reserves."},{"heading":"Why plan resources?","text":"Using resources without thinking has led to serious problems: a few people grow rich while many stay poor, resources run out, and the environment is damaged. In 1992, world leaders met at the Earth Summit in Rio de Janeiro and adopted Agenda 21, a plan for sustainable development. India has some regions rich in one resource but poor in others, so careful planning, matched to local needs and technology, is essential."},{"heading":"Land and its problems","text":"Land is a basic resource: we farm on it, build on it and draw forests and minerals from it. India has plains, mountains and plateaus, each used in different ways. But land is being degraded. Mining leaves deep scars, overgrazing strips the soil, cutting forests causes erosion, and too much irrigation in states like Punjab and Haryana has made some soils waterlogged and salty. Industrial waste also pollutes land and water."},{"heading":"Soils of India","text":"Soil is the thin top layer of the Earth in which plants grow, and it takes thousands of years to form. Alluvial soil, laid down by rivers, covers the northern plains and is very fertile. Black soil, or regur, formed from lava rock, holds moisture and is ideal for cotton. Red and yellow soils are found on the plateau. Laterite soil forms under heavy rain and suits tea, coffee and cashew. Arid soils are found in Rajasthan, and forest soils in the hills."},{"heading":"Saving the soil","text":"Wind and running water can carry away the precious top soil. Running water can cut deep channels called gullies, turning land into badlands, like the ravines of the Chambal valley. Farmers protect soil by ploughing along the contours of slopes, building terraces on hills, growing strips of grass between crops, and planting rows of trees as shelter belts to slow the wind. Stopping overgrazing and planting trees on bare land also help."},{"heading":"Resources and you","text":"Every one of us uses resources every day: water for washing, electricity for light, paper for books and fuel for travel. Small habits, like turning off taps and lights, reusing bags and recycling waste, reduce pressure on resources. When millions of people make such choices, the effect is large. Using resources wisely today is the best gift we can give to future generations."}]'::jsonb, '[{"topic":"Geography","question":"Agenda 21 was adopted at the Earth Summit held in…","options":["Kyoto","Rio de Janeiro","Paris","Stockholm"],"correct_index":1,"explanation":"At Rio de Janeiro in 1992."},{"topic":"Geography","question":"Which soil is also called regur?","options":["Alluvial","Black","Laterite","Arid"],"correct_index":1,"explanation":"Black soil is called regur and is good for cotton."},{"topic":"Geography","question":"Coal and petroleum are…","options":["renewable resources","non-renewable resources","biotic resources","human resources"],"correct_index":1,"explanation":"They take millions of years to form and can run out."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-2', 3, 'class10-geography', 'Forest and wildlife resources', 'Land and resources', 'Geography', 1, 'Forests and animals are part of our heritage. Let’s see how people are saving them!', '["India is one of the world’s richest countries in biodiversity, with many plants and animals found nowhere else.","The Indian Wildlife (Protection) Act was passed in 1972, and Project Tiger began in 1973.","Forests are classified as reserved, protected and unclassed forests.","The Chipko movement in the Himalayas saw villagers hug trees to stop them being cut.","Joint Forest Management, begun in Odisha in 1988, involves local communities in protecting forests."]'::jsonb, 'The Bishnoi community of Rajasthan is famous for protecting blackbuck, chinkara and trees.', '[{"heading":"Why biodiversity matters","text":"Biodiversity means the variety of life: plants, animals and tiny organisms, all depending on each other. India is one of the world’s most biodiverse countries, with forests, grasslands, wetlands, deserts and coral reefs. Forests give us wood, medicines, fruits and fodder, protect soil, store water and clean the air. Many tribal and village communities depend directly on forests for their living, so losing forests harms both nature and people."},{"heading":"Species in danger","text":"Scientists group species by how safe they are. Some are normal, with healthy numbers. Endangered species, like the tiger and the lion-tailed macaque, are in danger of dying out. Vulnerable species may soon become endangered. Rare species have small populations. Endemic species are found only in one area, like the Andaman teal. Extinct species are lost forever; the cheetah was declared extinct in India in 1952, though some have now been brought back to Kuno National Park."},{"heading":"What harms forests","text":"Forests have been cleared for farming, railways, mines, dams and growing cities. Large dams flooded huge forest areas. Hunting and trading in animal parts, like tiger skins and rhino horns, pushed many animals towards extinction. Pollution, forest fires and invasive plants add to the damage. When forests disappear, animals lose their homes, rains become less reliable, and soil is washed away."},{"heading":"Protecting wildlife","text":"In 1972, India passed the Wildlife (Protection) Act, banning the hunting of protected species and setting up national parks and wildlife sanctuaries. Project Tiger, started in 1973, created tiger reserves such as Corbett, Sundarbans and Bandipur. Other projects protect elephants, rhinos and crocodiles. Today many reserves also aim to protect whole ecosystems, not just one animal, because every species depends on others."},{"heading":"Kinds of forests","text":"The government manages forests in three groups. Reserved forests, which make up more than half of all forest land, are the most strictly protected. Protected forests are safeguarded from further damage. Unclassed forests include other forests and wastelands belonging to the government, private people and communities. Some states, like Madhya Pradesh, have large areas of reserved forest, while in the north-east many forests are unclassed and managed by local communities."},{"heading":"People who protect forests","text":"Some of the best protection comes from local people. In the Chipko movement in the Himalayas, villagers, many of them women, hugged trees to stop them being cut. The Bishnois of Rajasthan have protected trees and blackbuck for centuries. Many villages keep sacred groves where no tree may be cut. Under Joint Forest Management, begun in Odisha in 1988, villagers help protect forests and share in their benefits. Movements like Beej Bachao Andolan save traditional seeds."},{"heading":"What each of us can do","text":"Protecting forests and wildlife is not only the work of the government. Each of us can help by planting and caring for trees, saving paper, refusing products made from wild animals, and not disturbing animals in parks. Visiting national parks responsibly, supporting local communities who protect forests and spreading awareness among friends and family all make a real difference to India’s precious natural heritage."}]'::jsonb, '[{"topic":"Geography","question":"The Indian Wildlife (Protection) Act was passed in…","options":["1947","1972","1980","1992"],"correct_index":1,"explanation":"It was passed in 1972."},{"topic":"Geography","question":"In which movement did villagers hug trees?","options":["Chipko","Narmada Bachao","Swadeshi","Bhoodan"],"correct_index":0,"explanation":"In the Chipko movement, villagers hugged trees."},{"topic":"Geography","question":"Joint Forest Management first began in…","options":["Kerala","Odisha","Assam","Punjab"],"correct_index":1,"explanation":"It began in Odisha in 1988."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-3', 3, 'class10-geography', 'Water resources', 'Land and resources', 'Geography', 2, 'There’s plenty of water on Earth, yet many places run short. Let’s find out why, and what we can do!', '["About three-fourths of the Earth is covered by water, but only a small share is fresh water we can use.","Water scarcity is caused by overuse, unequal access, a growing population and pollution, not only by low rainfall.","Multi-purpose river projects, like Bhakra Nangal and Hirakud, provide irrigation, electricity and flood control.","Big dams have also displaced people; the Narmada Bachao Andolan opposed the Sardar Sarovar Dam.","Traditional water harvesting includes guls and kuls in the western Himalayas and tankas (underground tanks) in Rajasthan."]'::jsonb, 'Jawaharlal Nehru called dams the “temples of modern India”.', '[{"heading":"A precious resource","text":"Most of the Earth’s water is in the oceans and is too salty to drink. Much of the fresh water is frozen in ice caps and glaciers or lies deep underground. So only a small part is easily available in rivers, lakes and shallow groundwater. Rain and snow refill this supply through the water cycle, making water a renewable resource. But if we use it faster than it is refilled, or pollute it, we can still run short."},{"heading":"Why water becomes scarce","text":"Water scarcity is not caused only by dry weather. A growing population needs more water for drinking, cooking and farming. Farmers in many areas pump so much groundwater for irrigation that water tables fall. Cities and industries use large amounts and often release dirty water into rivers. Even where water exists, poor people may not have fair access to it. So we must manage water carefully, not just find more of it."},{"heading":"Dams and multi-purpose projects","text":"People have built dams for centuries. After independence, India built large multi-purpose projects that store river water for irrigation, generate hydroelectricity, supply water to cities, control floods and support fishing. Examples include Bhakra Nangal on the Satluj, Hirakud on the Mahanadi and the Sardar Sarovar on the Narmada. Nehru proudly called dams the “temples of modern India”, as they were symbols of development."},{"heading":"The other side of dams","text":"Big dams have also caused problems. They block the natural flow of rivers, trap sediment and harm fish. Large areas of forest and farmland are flooded, and thousands of people, often tribal and poor families, lose their homes. The Narmada Bachao Andolan raised these issues about the Sardar Sarovar Dam. Disputes also arise between states over sharing river water. These concerns have led many to support smaller, local water projects."},{"heading":"Wisdom from the past","text":"Indians have harvested rainwater for a very long time. In the hills of the western Himalayas, people built channels called guls and kuls to carry water to fields. In Rajasthan, homes had tankas, underground tanks that stored rainwater from rooftops, keeping it cool and clean. In the dry regions, khadins and johads stored runoff for farming. In Meghalaya, farmers use bamboo pipes to carry water from springs to their plants, drop by drop."},{"heading":"Saving water today","text":"Today, many cities encourage rooftop rainwater harvesting, collecting rain from roofs into tanks or channelling it into the ground to recharge wells. Tamil Nadu was among the first states to make it compulsory for buildings. Farmers can save water with drip and sprinkler irrigation, and by choosing crops that need less water. At home, we can fix leaking taps, reuse water and avoid wasting it. Every drop saved helps."},{"heading":"A shared responsibility","text":"Water connects everyone, from farmers and factories to families in cities. Rivers flow across state borders, so states must cooperate and share water fairly. Communities can revive old ponds and tanks, and schools can teach children to value every drop. Using water wisely today ensures that our villages and cities will still have enough clean water tomorrow."}]'::jsonb, '[{"topic":"Geography","question":"Who called dams the “temples of modern India”?","options":["Mahatma Gandhi","Jawaharlal Nehru","Sardar Patel","Dr B. R. Ambedkar"],"correct_index":1,"explanation":"Jawaharlal Nehru called them that."},{"topic":"Geography","question":"Underground tanks for storing rainwater in Rajasthan are called…","options":["kuls","tankas","johads","guls"],"correct_index":1,"explanation":"Tankas store rainwater under houses in Rajasthan."},{"topic":"Geography","question":"The Narmada Bachao Andolan opposed which dam?","options":["Bhakra Nangal","Hirakud","Sardar Sarovar","Tehri"],"correct_index":2,"explanation":"It opposed the Sardar Sarovar Dam."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-4', 3, 'class10-geography', 'Agriculture', 'Farming and minerals', 'Geography', 3, 'India is a land of farmers. Let’s see what we grow and how farming is changing!', '["Types of farming in India include primitive subsistence, intensive subsistence and commercial farming.","The three cropping seasons are rabi (winter), kharif (monsoon) and zaid (short summer).","Rice, wheat, millets, pulses, sugarcane and oilseeds are major food crops; tea, coffee, rubber, cotton and jute are important cash crops.","India is the largest producer of pulses and one of the largest producers of rice, wheat, sugarcane and tea.","Reforms like the Green Revolution, Kisan Credit Cards, crop insurance and minimum support prices aim to help farmers."]'::jsonb, 'Vinoba Bhave’s Bhoodan movement asked landowners to give land voluntarily to the landless.', '[{"heading":"Farming in India","text":"Agriculture is one of India’s oldest activities, and a large share of Indians still depend on it for their living. Farming here ranges from tiny family plots to huge plantations. It provides food for our people, raw materials for industries like textiles and sugar, and goods for export. Because so many people depend on it, the health of farming affects the whole economy."},{"heading":"Types of farming","text":"In primitive subsistence farming, families grow food on small patches using simple tools; slash-and-burn, or jhum, cultivation in the north-east is one form. Intensive subsistence farming uses a lot of labour, fertilisers and irrigation on small land to grow as much as possible. Commercial farming grows crops mainly for sale, using modern inputs; plantations of tea, coffee and rubber are a special kind, growing one crop on large estates."},{"heading":"Cropping seasons","text":"India has three main crop seasons. Rabi crops are sown in winter, from October to December, and harvested in spring; wheat, gram, peas and mustard are rabi crops. Kharif crops are sown with the monsoon and harvested in autumn; rice, maize, cotton, jowar and groundnut are kharif crops. Between these, a short summer season called zaid grows watermelon, cucumber and vegetables."},{"heading":"Major crops","text":"Rice is the main food of most Indians and grows in hot, wet areas such as West Bengal, Uttar Pradesh and Punjab with irrigation. Wheat is the main crop of the north and north-west. Millets like jowar, bajra and ragi grow in drier areas and are very nutritious. India is the largest producer and consumer of pulses. Sugarcane, oilseeds, tea in Assam, coffee in Karnataka, cotton on black soils and jute in the Ganga delta are other key crops."},{"heading":"Reforms and support","text":"After independence, land reforms tried to give land to the tillers. The Green Revolution of the 1960s used high-yielding seeds, fertilisers and irrigation to raise food output, especially wheat. The White Revolution raised milk production. The government also gives Kisan Credit Cards for cheap loans, crop insurance against bad weather, and minimum support prices for many crops. Weather forecasts and soil testing help farmers plan."},{"heading":"Challenges ahead","text":"Many farmers have very small plots and little money. They depend on uncertain rains and often take loans that are hard to repay. Overuse of chemicals and groundwater is harming soil and water. Prices of crops can swing widely. To make farming sustainable, India is encouraging organic farming, better water use, crop variety, storage and food processing, so that farmers earn more and the land stays healthy."},{"heading":"Food for the future","text":"India must feed a large and growing population while protecting its land and water. This means producing more food from the same land without harming the soil, reducing waste in storage and transport, and making sure farmers get fair prices. Millets, which need little water and are very nutritious, are getting renewed attention. A healthy farming sector is the foundation of India’s food security."}]'::jsonb, '[{"topic":"Geography","question":"Wheat is a…","options":["kharif crop","rabi crop","zaid crop","plantation crop"],"correct_index":1,"explanation":"Wheat is sown in winter, so it is a rabi crop."},{"topic":"Geography","question":"Slash-and-burn farming in the north-east is called…","options":["jhum","zaid","terrace","plantation"],"correct_index":0,"explanation":"It is called jhum cultivation."},{"topic":"Geography","question":"Who led the Bhoodan movement?","options":["M. S. Swaminathan","Vinoba Bhave","Verghese Kurien","Jyotiba Phule"],"correct_index":1,"explanation":"Vinoba Bhave led the Bhoodan (land gift) movement."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-5', 3, 'class10-geography', 'Minerals and energy resources', 'Farming and minerals', 'Geography', 4, 'From iron ore to sunshine, minerals and energy power our lives. Let’s explore them!', '["Minerals can be metallic (ferrous like iron ore, non-ferrous like copper and bauxite) or non-metallic (like mica and limestone).","Most of India’s coal comes from the Damodar valley and nearby areas, such as Jharia, Raniganj and Bokaro.","Petroleum comes from Mumbai High, Gujarat and Assam; Digboi in Assam is India’s oldest oil field.","Conventional energy sources include coal, petroleum, natural gas and electricity; non-conventional sources include solar, wind, tidal, geothermal and biogas.","Nuclear power stations include Tarapur, Rawatbhata, Kalpakkam, Narora, Kakrapar and Kaiga."]'::jsonb, 'Geothermal energy is being explored at Manikaran in Himachal Pradesh and in the Puga valley of Ladakh.', '[{"heading":"What are minerals?","text":"A mineral is a natural substance with a definite composition, found in rocks. Everything from the salt in our food to the metal in our phones comes from minerals. Rock that contains enough of a mineral to be worth mining is called an ore. Minerals are found in veins and layers, in river sands and even in ocean water. Since they take millions of years to form, they must be used carefully and recycled where possible."},{"heading":"Metallic minerals","text":"Ferrous minerals contain iron. India has rich iron ore deposits in Odisha and Jharkhand, in the Durg–Bastar belt of Chhattisgarh, and in Karnataka and Goa; Kudremukh in Karnataka is known for exports. Manganese is used to make steel. Non-ferrous minerals include copper, found at Balaghat in Madhya Pradesh and Khetri in Rajasthan, and bauxite, the ore of aluminium, found in Odisha and other plateau areas."},{"heading":"Non-metallic minerals","text":"Mica, which can be split into thin sheets, is used in electrical goods; India has deposits around Koderma in Jharkhand. Limestone is the main raw material for cement and is also used in iron and steel making. Mining gives jobs and raw materials, but it can be dangerous for miners, who face dust, gases and accidents, and it can pollute land and water if not done responsibly."},{"heading":"Conventional energy","text":"Coal is India’s most important source of energy. Most of it is Gondwana coal from the Damodar valley, with fields at Jharia, Raniganj and Bokaro; lignite, a lower-grade coal, is mined at Neyveli in Tamil Nadu. Petroleum comes from Mumbai High offshore, from Gujarat and from Assam, where Digboi is the oldest field. Natural gas is found in the Krishna–Godavari basin. Electricity is produced mainly in thermal and hydel power stations."},{"heading":"Non-conventional energy","text":"Fossil fuels pollute the air and will one day run out, so India is turning to cleaner sources. Solar power is growing fast, with huge solar parks in Rajasthan and Gujarat. Wind farms run in Tamil Nadu, Gujarat and Rajasthan. Tidal energy can be tapped in the Gulfs of Khambhat and Kutch. Geothermal energy uses heat from inside the Earth. Biogas plants turn cattle dung and farm waste into cooking gas and manure."},{"heading":"Nuclear energy and saving power","text":"Nuclear power is produced by splitting atoms of uranium or thorium. India has nuclear stations at Tarapur, Rawatbhata, Kalpakkam, Narora, Kakrapar and Kaiga, among others. Every unit of energy we save is as good as producing one. Using public transport, switching off lights and fans, buying energy-saving appliances and using solar heaters all reduce our energy needs and protect the environment."},{"heading":"Using minerals wisely","text":"Mineral deposits are limited and unevenly spread, and they cannot be replaced once used. Mining also disturbs forests and the people who live there. So minerals must be mined carefully, with land restored afterwards. Recycling metals like aluminium, iron and copper saves both minerals and energy. Using substitutes and better technology can help our mineral resources last much longer."}]'::jsonb, '[{"topic":"Geography","question":"Bauxite is the ore of…","options":["iron","copper","aluminium","gold"],"correct_index":2,"explanation":"Aluminium is made from bauxite."},{"topic":"Geography","question":"Which is India’s oldest oil field?","options":["Mumbai High","Ankleshwar","Digboi","Neyveli"],"correct_index":2,"explanation":"Digboi in Assam is the oldest."},{"topic":"Geography","question":"Lignite is mined at…","options":["Jharia","Neyveli","Raniganj","Koderma"],"correct_index":1,"explanation":"Neyveli in Tamil Nadu has lignite."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-6', 3, 'class10-geography', 'Manufacturing industries', 'Industry and transport', 'Geography', 5, 'Factories turn raw materials into the things we use every day. Let’s tour India’s industries!', '["Manufacturing means turning raw materials into more valuable goods; it is part of the secondary sector.","Industries are grouped by raw material (agro-based, mineral-based), ownership (public, private, joint, cooperative) and size.","The first successful textile mill in India was set up in Mumbai in 1854.","Iron and steel is a basic industry, because many other industries depend on it.","Industries cause air, water, noise and land pollution, so they must use cleaner methods."]'::jsonb, 'Bengaluru is often called the “Silicon Valley of India” for its information technology industry.', '[{"heading":"Why manufacturing matters","text":"Manufacturing turns raw cotton into cloth, iron ore into steel and sugarcane into sugar. It adds value to raw materials, creates jobs, and reduces our dependence on farming. A strong manufacturing sector helps a country earn foreign exchange through exports and supports farming by producing tools, fertilisers and machines. That is why governments encourage industries through schemes like Make in India."},{"heading":"Kinds of industries","text":"Industries can be classified in several ways. By raw material, they are agro-based, like cotton textiles, jute and sugar, or mineral-based, like iron and steel and cement. By ownership, they are public sector (owned by the government), private sector, joint sector, or cooperative, like many sugar mills in Maharashtra. By size, they may be small-scale or large-scale. Basic industries supply raw materials to others."},{"heading":"Textiles","text":"The textile industry is one of India’s oldest and biggest, giving jobs to millions, from cotton farmers to weavers and garment makers. The first successful cotton mill was set up in Mumbai in 1854. Cotton mills are found in Maharashtra, Gujarat and Tamil Nadu, close to cotton-growing areas and markets. India is also a major producer of jute goods, mostly made in mills along the Hooghly river in West Bengal."},{"heading":"Iron, steel and more","text":"Iron and steel is called a basic industry because machines, vehicles, buildings and tools all need steel. Steel plants are built close to iron ore, coal and water, as in the Chota Nagpur region. Other major industries include aluminium smelting, chemicals, fertilisers, cement for construction, automobiles and electronics. Many public sector steel plants are run by the Steel Authority of India Limited (SAIL)."},{"heading":"New industries","text":"In recent decades, the information technology and electronics industries have grown quickly. Bengaluru, Hyderabad, Pune, Chennai and Gurugram are major IT centres, with software parks that provide services to clients around the world. These industries employ many young, educated people, including large numbers of women, and earn a lot of foreign exchange for the country."},{"heading":"Industry and pollution","text":"Factories can pollute the air with smoke and gases, rivers with chemical waste, the land with solid waste, and cities with noise. Thermal power plants and factories also release a lot of heat and carbon dioxide. To reduce this harm, industries can treat waste water before releasing it, use cleaner fuels, fit filters on chimneys, recycle waste and save energy. Laws and public pressure push them to do so."},{"heading":"Where industries are located","text":"Industries are usually set up where raw materials, power, water, workers, transport and markets are easily available. Many cities, like Mumbai, Kolkata and Chennai, grew around industries. Governments also encourage industries in backward regions to spread jobs more evenly. A good location keeps costs low and helps industries compete with others in India and abroad."},{"heading":"Industry and jobs","text":"Industries give jobs not only inside factories but also to transporters, shopkeepers, repair workers and suppliers. When a large factory opens, a whole town can grow around it. That is why balanced industrial growth across all regions is important for reducing poverty."}]'::jsonb, '[{"topic":"Geography","question":"The first successful textile mill in India was set up in…","options":["Kolkata in 1818","Mumbai in 1854","Chennai in 1900","Delhi in 1947"],"correct_index":1,"explanation":"It was set up in Mumbai in 1854."},{"topic":"Geography","question":"Why is iron and steel called a basic industry?","options":["It is very old","Many other industries depend on it","It is small","It uses no raw materials"],"correct_index":1,"explanation":"Its products are used by many other industries."},{"topic":"Geography","question":"Cotton textiles are an example of…","options":["an agro-based industry","a mineral-based industry","a service","mining"],"correct_index":0,"explanation":"They use a farm product, cotton, as raw material."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-geo-7', 3, 'class10-geography', 'Lifelines of the national economy', 'Industry and transport', 'Geography', 6, 'Roads, railways, ports and phones keep India moving. Let’s ride along!', '["The Golden Quadrilateral highways link Delhi, Kolkata, Chennai and Mumbai.","The North–South corridor links Srinagar and Kanyakumari; the East–West corridor links Silchar and Porbandar.","India’s first train ran from Bombay to Thane on 16 April 1853.","National Waterway No. 1 runs on the Ganga between Prayagraj and Haldia.","Major ports include Kandla (Deendayal), Mumbai, JNPT, Marmagao, Kochi, Chennai, Visakhapatnam, Paradip and Kolkata."]'::jsonb, 'Pipelines also carry oil and gas across India, for example from gas fields in Gujarat to the north.', '[{"heading":"Why transport matters","text":"Goods and people must move from where things are made to where they are needed. Transport, communication and trade are the lifelines that connect farms, mines, factories and markets. A good network of roads, railways, waterways and air routes helps businesses grow, lets people reach jobs, schools and hospitals, and brings different parts of the country closer together."},{"heading":"Roads","text":"Roads reach almost every village and are cheaper to build than railways. The Golden Quadrilateral is a network of super highways linking Delhi, Kolkata, Chennai and Mumbai. The North–South corridor connects Srinagar to Kanyakumari, and the East–West corridor connects Silchar in Assam to Porbandar in Gujarat. National highways are built and maintained by the Union government, while state highways and village roads are looked after by states and local bodies."},{"heading":"Railways","text":"India’s first passenger train ran from Bombay to Thane on 16 April 1853. Today Indian Railways is one of the largest networks in the world under a single management. It carries huge numbers of passengers and heavy goods like coal, iron ore and food grains over long distances. Building railways is harder in mountains, deserts and flood-prone areas, but new lines and high-speed corridors keep expanding the network."},{"heading":"Pipelines and waterways","text":"Pipelines carry crude oil, petroleum products and natural gas from fields and refineries to cities and factories, cheaply and safely. Waterways are the cheapest way to move heavy goods. National Waterway No. 1 runs on the Ganga from Prayagraj to Haldia, and other waterways use the Brahmaputra and the backwaters of Kerala. Coastal shipping also carries goods between Indian ports."},{"heading":"Ports and airways","text":"Most of India’s foreign trade travels by sea. Major ports on the west coast include Kandla (Deendayal Port), Mumbai, Jawaharlal Nehru Port, Marmagao, New Mangalore and Kochi. On the east coast are Tuticorin, Chennai, Visakhapatnam, Paradip and the riverine port of Kolkata with Haldia. Air transport is the fastest way to travel and reaches remote areas like the north-east and the islands, though it is costly."},{"heading":"Communication, trade and tourism","text":"Communication links people instantly. The postal network, telephones, mobile phones, the internet, television and radio carry information across the country. Trade within the country and with other nations depends on all these lifelines. Tourism, too, has grown into a major industry, bringing visitors to India’s heritage sites, mountains and beaches, creating jobs and earning foreign exchange."},{"heading":"Connecting a big country","text":"For a country as large and varied as India, transport and communication are what hold the economy together. They let a farmer in Punjab sell wheat in Kerala, a factory in Tamil Nadu get coal from Jharkhand, and a student in Assam study online with a teacher in Delhi. Building and maintaining these lifelines is essential for India’s growth and unity."},{"heading":"Trade with the world","text":"India trades with countries all over the world. It exports goods like engineering products, medicines, gems, textiles and software services, and imports crude oil, machinery and electronics. Good ports, airports and communication links make this trade possible."}]'::jsonb, '[{"topic":"Geography","question":"The Golden Quadrilateral links Delhi, Kolkata, Chennai and…","options":["Bengaluru","Mumbai","Hyderabad","Ahmedabad"],"correct_index":1,"explanation":"It links the four metros including Mumbai."},{"topic":"Geography","question":"India’s first passenger train ran from Bombay to…","options":["Pune","Thane","Surat","Nashik"],"correct_index":1,"explanation":"From Bombay to Thane on 16 April 1853."},{"topic":"Geography","question":"National Waterway No. 1 is on which river?","options":["Brahmaputra","Ganga","Godavari","Narmada"],"correct_index":1,"explanation":"It runs on the Ganga from Prayagraj to Haldia."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class10-economics', 'Understanding Development', 'Economy', 'class', 'Class 10', '', 'Development, sectors, money and credit, globalisation, consumers.', 17) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-eco-1', 3, 'class10-economics', 'Development', 'Development', 'Economy', 0, 'What does “development” really mean? A bigger income, or a better life? Let’s think about it!', '["Different people have different development goals, and some goals can conflict, like a dam that gives power but displaces villagers.","Income is one important measure; average or per capita income is total income divided by population.","Averages can hide inequality, so we also look at health, education and other facilities.","The Human Development Index (HDI), published by the UNDP, combines health, education and income.","Sustainable development means meeting today’s needs without harming the ability of future generations to meet theirs."]'::jsonb, 'Kerala has a low infant mortality rate partly because of good basic health and education facilities.', '[{"heading":"Different people, different goals","text":"Development means progress, but progress looks different to different people. A landless labourer may want more days of work and better wages. A rich farmer may want higher prices for crops. A girl from a village may want to study as freely as her brother. An urban family may want clean air and less traffic. Goals can even clash: a new dam may give electricity to cities but flood the homes of tribal villagers."},{"heading":"More than money","text":"Income matters, because money buys many things we need. But people also want things money cannot easily buy: equal treatment, freedom, security, respect and a clean environment. A good job with a slightly lower salary may be better than a higher-paying job far from family or with no security. So development includes both material goods and the quality of life."},{"heading":"Comparing countries and states","text":"To compare countries, economists often use average income, also called per capita income: the total income of the country divided by its population. The World Bank uses it to group countries as rich or low-income. But averages can hide inequality. Two countries with the same average may be very different if, in one, a few people are extremely rich while most are poor."},{"heading":"Health and education","text":"That is why we also look at indicators like the infant mortality rate (how many babies die before their first birthday), the literacy rate and the net attendance ratio (how many children are actually in school). Kerala, for example, has a lower infant mortality rate than some richer states because it has better basic health and education facilities, and a public distribution system that provides food at fair prices."},{"heading":"The Human Development Index","text":"The United Nations Development Programme (UNDP) publishes the Human Development Report every year. It ranks countries by the Human Development Index, which combines life expectancy, years of schooling and income per person. On this index, a country with a smaller income but better health and education can rank above a richer country. This shows that public facilities and people’s well-being matter as much as income."},{"heading":"Development that lasts","text":"Development must also be sustainable. In many parts of India, groundwater is being pumped faster than it is refilled, and forests and soils are being lost. Burning fossil fuels causes pollution and climate change. Using up resources now may leave future generations poorer. Sustainable development means meeting our needs today without harming the ability of our children and grandchildren to meet theirs."},{"heading":"Thinking about development","text":"Development is not something only governments do. Families decide to send their children to school, communities build better sanitation, and citizens demand better services. When we think about development, we should ask: whose development, and at what cost? Development that improves the lives of the poorest people, while protecting the environment, is the kind that truly lasts."}]'::jsonb, '[{"topic":"Economy","question":"Per capita income is…","options":["total income divided by population","income of the richest person","income of the government","total exports"],"correct_index":0,"explanation":"It is the average income per person."},{"topic":"Economy","question":"The Human Development Report is published by…","options":["World Bank","IMF","UNDP","WTO"],"correct_index":2,"explanation":"The UNDP publishes it every year."},{"topic":"Economy","question":"Infant mortality rate measures…","options":["deaths of babies before their first birthday","school enrolment","income per person","unemployment"],"correct_index":0,"explanation":"It counts deaths of babies under one year old."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-eco-2', 3, 'class10-economics', 'Sectors of the Indian economy', 'Development', 'Economy', 1, 'Farming, factories and services: who does what in India’s economy? Let’s sort it out!', '["The primary sector uses natural resources directly (farming, fishing, mining); the secondary sector manufactures goods; the tertiary sector provides services.","GDP is the value of all final goods and services produced in a country in a year.","The tertiary sector produces the largest share of India’s GDP, but the primary sector still employs the largest share of workers.","Disguised unemployment means more people work on a job than are really needed, as on many small family farms.","MGNREGA (2005) guarantees 100 days of paid work a year to rural households who ask for it."]'::jsonb, 'Jobs in the organised sector have regular hours, fixed pay and benefits; unorganised jobs often do not.', '[{"heading":"Three sectors","text":"Economic activities can be grouped into three sectors. The primary sector uses natural resources directly: farming, dairy, fishing, forestry and mining. The secondary sector turns natural products into other goods through manufacturing, such as making cloth from cotton or sugar from sugarcane; it also includes construction and electricity. The tertiary sector provides services that support the other two, like transport, banking, trade, teaching and health care."},{"heading":"Measuring production","text":"To know how much a country produces, we add up the value of final goods and services made in a year, not intermediate goods like the wheat used to make biscuits, to avoid counting things twice. This total is the Gross Domestic Product, or GDP. In India, the Union government’s statistics office collects data from all over the country to estimate GDP."},{"heading":"How India has changed","text":"In the past, most of India’s production came from farming. Over time, manufacturing and especially services have grown faster. Today the tertiary sector produces the largest share of GDP, thanks to banking, IT, trade, transport and communication. But jobs have not shifted as quickly: the primary sector still employs the largest share of workers, even though it produces a much smaller share of output."},{"heading":"Underemployment","text":"On many small farms, more family members work than are really needed. If some of them left, production would not fall. This is disguised unemployment, or underemployment: people seem to be working, but their work is not fully productive. Similar situations exist in cities among casual workers, painters, plumbers and street vendors who may find work only some days."},{"heading":"Creating more jobs","text":"More jobs can be created by building irrigation, roads and storage in villages; giving cheap loans to farmers and small businesses; promoting industries that process farm products; and expanding tourism, health and education. In 2005, Parliament passed MGNREGA, which gives a legal right to 100 days of paid work a year to rural households who demand it. If work is not provided, the government must pay an unemployment allowance."},{"heading":"Organised and unorganised, public and private","text":"Jobs in the organised sector are registered with the government and follow rules on wages, working hours, leave and safety. In the unorganised sector, jobs are small, scattered and often outside such rules, with low pay and no security. Economic activities can also be divided by ownership: the public sector, owned by the government, like railways and post offices, and the private sector, owned by individuals or companies."},{"heading":"Why the sectors matter","text":"The three sectors depend on each other. Farmers need fertilisers and tractors from the secondary sector, and transport and banks from the tertiary sector. Factories need raw materials from farms and mines. Services need goods to sell and people with income to buy them. A balanced economy grows all three, creating good jobs so that people can move from low-paying, uncertain work to better occupations."}]'::jsonb, '[{"topic":"Economy","question":"Which sector produces the largest share of India’s GDP?","options":["Primary","Secondary","Tertiary","None"],"correct_index":2,"explanation":"The tertiary (service) sector is the largest."},{"topic":"Economy","question":"More people working on a job than needed is…","options":["disguised unemployment","inflation","full employment","globalisation"],"correct_index":0,"explanation":"That is disguised unemployment."},{"topic":"Economy","question":"MGNREGA guarantees how many days of work a year?","options":["50","100","200","365"],"correct_index":1,"explanation":"It guarantees 100 days of paid work."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-eco-3', 3, 'class10-economics', 'Money and credit', 'Money and the world', 'Economy', 2, 'Why do we use money, and how do loans work? Let’s visit a bank and a self-help group!', '["Money solves the barter problem of “double coincidence of wants”: it is a medium of exchange.","In India, the Reserve Bank of India issues currency notes on behalf of the government.","Banks keep only a small part of deposits as cash and lend the rest, earning interest.","Credit has terms: interest rate, collateral (security), documents and the way of repayment.","Formal credit comes from banks and cooperatives; informal credit from moneylenders, traders and relatives, often at high interest.","Self-help groups (SHGs) of 15–20 people, mostly women, save together and give small loans to members."]'::jsonb, 'Muhammad Yunus, founder of the Grameen Bank in Bangladesh, won the Nobel Peace Prize in 2006.', '[{"heading":"Why we need money","text":"Imagine trading without money. A shoemaker who wants wheat must find a farmer who both has wheat and wants shoes at the same time. This is called the double coincidence of wants, and it is hard to find. Money solves the problem: the shoemaker sells shoes for money and uses it to buy wheat from anyone. Because money is accepted by everyone as payment, it acts as a medium of exchange."},{"heading":"Forms of money","text":"Over history, people used grain, cattle, shells and metal coins as money. Today we use paper notes and coins, called currency, which are accepted because the government says they must be. In India, the Reserve Bank of India issues notes on behalf of the government. People also keep money in bank accounts and pay using cheques, debit cards and digital payments like UPI. These deposits are also a form of money."},{"heading":"How banks work","text":"Banks accept deposits from people and pay them interest. They keep only a small portion as cash to meet daily withdrawals, and lend most of the rest to people and businesses who need loans. They charge a higher rate of interest on loans than they pay on deposits; the difference is their main income. In this way, banks link people who have spare money with those who need it."},{"heading":"Credit and its terms","text":"Credit, or a loan, is an agreement in which the lender gives money or goods and the borrower promises to repay later. Every loan has terms of credit: the interest rate, the collateral (an asset like land or gold that the lender can take if the loan is not repaid), the documents needed and how it must be repaid. Credit can help a farmer buy seeds or a business grow, but if things go wrong, it can also trap people in debt."},{"heading":"Formal and informal credit","text":"Formal loans come from banks and cooperatives, which are supervised by the Reserve Bank and charge reasonable interest. Informal loans come from moneylenders, traders, employers, relatives and friends. There is no one to check their terms, and moneylenders often charge very high interest, so borrowers may lose their land or fall into a debt trap. Many poor households still depend on informal loans because they lack collateral and documents."},{"heading":"Self-help groups","text":"Self-help groups help the poor, especially women, get cheap credit. An SHG has about 15 to 20 members, usually from one neighbourhood, who save small amounts regularly. The group lends to its members at low interest, and after a year or two it can get bank loans too. Members decide together and are responsible for repayment. SHGs help women become financially independent and confident. The Grameen Bank in Bangladesh, founded by Muhammad Yunus, made this idea famous."},{"heading":"Credit for everyone","text":"For development, cheap and fair credit must reach everyone, especially poor households in villages. This means more bank branches and digital banking in rural areas, simpler documents, and loans without heavy collateral for small amounts. Cooperatives and self-help groups play a big role. When people can borrow at fair rates, they can invest in farming, small businesses and education, and improve their lives."}]'::jsonb, '[{"topic":"Economy","question":"Money solves the barter problem of…","options":["inflation","double coincidence of wants","unemployment","taxes"],"correct_index":1,"explanation":"Money removes the need for a double coincidence of wants."},{"topic":"Economy","question":"An asset given as security for a loan is called…","options":["interest","collateral","deposit","currency"],"correct_index":1,"explanation":"That is collateral."},{"topic":"Economy","question":"Who founded the Grameen Bank?","options":["Amartya Sen","Muhammad Yunus","Verghese Kurien","Manmohan Singh"],"correct_index":1,"explanation":"Muhammad Yunus, Nobel Peace Prize 2006."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-eco-4', 3, 'class10-economics', 'Globalisation and the Indian economy', 'Money and the world', 'Economy', 3, 'Phones made in one country, designed in another, sold everywhere! Let’s understand globalisation.', '["A multinational corporation (MNC) owns or controls production in more than one country.","Globalisation is the rapid integration of countries through trade, investment and movement of people and technology.","Improvements in transport and information technology have made globalisation faster.","In 1991, India began removing barriers on foreign trade and investment: this is called liberalisation.","The World Trade Organization (WTO), set up in 1995, makes rules for international trade."]'::jsonb, 'Special Economic Zones (SEZs) are areas with good facilities and tax benefits to attract investment.', '[{"heading":"Production across borders","text":"Until the middle of the 20th century, most production happened within countries, and only raw materials, food and finished goods were traded. Today, a single product may be designed in one country, its parts made in several others, and then assembled and sold around the world. Companies that own or control production in more than one country are called multinational corporations, or MNCs."},{"heading":"How MNCs spread","text":"MNCs set up factories and offices where they can find cheap workers, raw materials and big markets. They may build their own factories, buy local companies, or partner with them. For example, many car makers and electronics companies have set up plants in India to sell here and export abroad. Money spent by MNCs to buy land, buildings and machines is called foreign investment."},{"heading":"Trade joins markets","text":"Foreign trade lets producers sell beyond their own country and gives buyers more choice. When Chinese toys or Korean phones are sold in Indian markets, Indian buyers can choose among more products, and Indian producers face competition. In this way, trade links, or integrates, markets in different countries. Globalisation is this growing integration of countries through trade, investment, technology and movement of people."},{"heading":"What made it possible","text":"Technology has made globalisation much faster. Container ships and aircraft carry goods cheaply over long distances. Telephones, the internet and computers let companies work across the world in real time; an office in India can process data for a company in the USA overnight. Governments also helped by removing barriers. In 1991, India reduced limits on imports and foreign investment, a policy called liberalisation."},{"heading":"The WTO and India","text":"The World Trade Organization, set up in 1995, aims to make trade freer by setting rules that member countries follow. Many developing countries feel that rich countries push others to open their markets while protecting their own farmers with subsidies. India also set up Special Economic Zones with good roads, power and tax benefits to attract foreign companies and boost exports."},{"heading":"Who gains, who loses","text":"Globalisation has given Indian consumers better and cheaper products, and many Indian companies, like those in IT, have grown into global firms. New jobs have been created in services and some industries. But small producers, such as makers of batteries, toys or dairy products, have struggled against foreign competition, and many workers now have less job security. Fair globalisation means making sure its benefits reach everyone, with fair labour laws and support for small producers."},{"heading":"Globalisation and our daily lives","text":"Look around your home and you will find globalisation everywhere: a phone with parts from many countries, clothes made for global brands, foods and films from abroad. Many Indians also work for foreign companies or sell to buyers overseas. Understanding globalisation helps us see both its opportunities and its risks, and why fair rules for trade and work matter to all of us."}]'::jsonb, '[{"topic":"Economy","question":"A company that controls production in more than one country is a…","options":["cooperative","MNC","SHG","panchayat"],"correct_index":1,"explanation":"That is a multinational corporation (MNC)."},{"topic":"Economy","question":"The WTO was set up in…","options":["1947","1991","1995","2005"],"correct_index":2,"explanation":"It was set up in 1995."},{"topic":"Economy","question":"Removing barriers on trade and investment is called…","options":["nationalisation","liberalisation","industrialisation","privatisation of land"],"correct_index":1,"explanation":"That is liberalisation."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('class10-eco-5', 3, 'class10-economics', 'Consumer rights', 'Money and the world', 'Economy', 4, 'Every time you buy something, you are a consumer with rights! Let’s learn how to use them.', '["Consumers can be cheated through underweighing, adulteration, high prices, poor quality and false advertising.","The Consumer Protection Act was first passed in 1986; a new Act came in 2019.","Consumer rights include the right to safety, information, choice, redress and representation, and consumer education.","Consumer complaints are heard by commissions at the district, state and national levels.","Marks like ISI, Agmark and Hallmark show standard quality."]'::jsonb, '24 December is National Consumers’ Day in India, and 15 March is World Consumer Rights Day.', '[{"heading":"Who is a consumer?","text":"Anyone who buys goods or services for their own use is a consumer. We are consumers when we buy groceries, take a bus, see a doctor or recharge a phone. Sellers and producers are usually bigger and better informed than individual buyers. Some take advantage of this by selling less than they charge for, mixing cheap things into food, charging more than the printed price, or making false claims in advertisements."},{"heading":"The consumer movement","text":"In the past, consumers who were cheated had little help. Gradually, consumer groups began to spread awareness and fight cases on behalf of buyers. In India, the government passed the Consumer Protection Act in 1986, often called COPRA, and replaced it with a new Consumer Protection Act in 2019, which also covers online shopping. 24 December is celebrated as National Consumers’ Day."},{"heading":"Your rights","text":"Consumers have several rights. The right to safety protects us from goods that are dangerous to life and health. The right to information means we must be told about ingredients, price, expiry date and the manufacturer. The right to choose lets us pick from different products and sellers. The right to seek redress lets us get compensation if we are cheated. We also have the right to be heard and to consumer education."},{"heading":"Where to complain","text":"If a product is faulty or a service is poor, a consumer can file a complaint with the consumer commissions. There are commissions at three levels: district, state and national, depending on the value of the claim. The process is meant to be simple and inexpensive, and consumers can argue their own case without a lawyer. Keeping the bill or receipt is very important, as it proves the purchase."},{"heading":"Marks of quality","text":"Standard marks help consumers choose safe, good-quality products. The ISI mark, given by the Bureau of Indian Standards, appears on electrical goods and many other items. Agmark certifies farm products like honey, spices and pulses. Hallmark shows the purity of gold and silver jewellery. The printed Maximum Retail Price (MRP) is the highest price a seller may charge, though a buyer can always ask for less."},{"heading":"Being an alert consumer","text":"Laws help only if consumers know and use them. An alert consumer checks weights, expiry dates and quality marks, compares prices, asks for a bill, and reads the fine print of offers. If cheated, they complain instead of keeping quiet. The Right to Information Act (2005) also lets citizens ask government departments for information about public services. Informed, active consumers push businesses to be honest and fair."},{"heading":"Consumers and producers","text":"Consumer protection is good for honest businesses too. When buyers trust that products are safe and fairly priced, they buy more, and good producers gain. Strong consumer laws push all sellers to improve quality and service. In this way, alert consumers, fair businesses and an active government together build a healthy market where everyone benefits."}]'::jsonb, '[{"topic":"Economy","question":"The first Consumer Protection Act was passed in…","options":["1947","1986","2005","2019"],"correct_index":1,"explanation":"COPRA was passed in 1986; a new Act came in 2019."},{"topic":"Economy","question":"Which mark shows the purity of gold jewellery?","options":["ISI","Agmark","Hallmark","MRP"],"correct_index":2,"explanation":"Hallmark certifies gold and silver."},{"topic":"Economy","question":"National Consumers’ Day in India is on…","options":["15 March","24 December","5 June","1 May"],"correct_index":1,"explanation":"It is celebrated on 24 December."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-polity', 'Indian Polity', 'Politics', 'explore', '', 'General Knowledge', 'The Constitution, our rights and duties, and how India is governed.', 18) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-1', 3, 'gk-polity', 'Making of the Constitution', 'The Constitution', 'Politics', 0, 'How do you write the rulebook for a whole country? Let’s see how India did it.', '["The Constitution was written by the Constituent Assembly, which first met on 9 December 1946.","Members of the Assembly were elected indirectly, by the members of the provincial legislative assemblies.","Dr Rajendra Prasad was elected President of the Constituent Assembly.","Dr B. R. Ambedkar chaired the Drafting Committee, set up in August 1947.","The work took about 2 years, 11 months and 18 days.","The Constitution was adopted on 26 November 1949 and came into force on 26 January 1950."]'::jsonb, 'B. N. Rau was the Constitutional Adviser to the Constituent Assembly.', '[{"heading":"Why a constitution?","text":"A constitution is the basic law of a country. It sets out how the government is formed, what powers each part has, and what rights citizens enjoy. Every other law must follow it."},{"heading":"The Constituent Assembly","text":"The Constituent Assembly first met on 9 December 1946. Dr Rajendra Prasad was elected its President. Its members were chosen by the provincial legislative assemblies, and they debated every part of the draft openly."},{"heading":"From draft to law","text":"The Drafting Committee, chaired by Dr B. R. Ambedkar, prepared the text. The Assembly adopted the Constitution on 26 November 1949, now marked as Constitution Day. It came into force on 26 January 1950, which we celebrate as Republic Day."}]'::jsonb, '[{"topic":"Politics","question":"Who chaired the Drafting Committee of the Constitution?","options":["Jawaharlal Nehru","Dr B. R. Ambedkar","Dr Rajendra Prasad","Sardar Patel"],"correct_index":1,"explanation":"Dr B. R. Ambedkar chaired the Drafting Committee of the Constitution."},{"topic":"Politics","question":"When did the Constituent Assembly adopt the Constitution?","options":["15 August 1947","26 November 1949","26 January 1950","9 December 1946"],"correct_index":1,"explanation":"It was adopted on 26 November 1949 and came into force on 26 January 1950."},{"topic":"Politics","question":"Who was the President of the Constituent Assembly?","options":["Dr Rajendra Prasad","Dr B. R. Ambedkar","B. N. Rau","Jawaharlal Nehru"],"correct_index":0,"explanation":"Dr Rajendra Prasad was elected President of the Constituent Assembly."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-2', 3, 'gk-polity', 'Sources and features', 'The Constitution', 'Politics', 1, 'Our Constitution borrowed good ideas from around the world. Let’s find out which ones!', '["India has the longest written constitution of any country in the world.","When adopted it had 395 Articles, 22 Parts and 8 Schedules; today it has 12 Schedules.","The parliamentary system came from Britain, and Fundamental Rights were inspired by the USA.","The Directive Principles came from Ireland, and the Concurrent List from Australia.","A federation with a strong centre was inspired by Canada.","India has a single citizenship for the whole country."]'::jsonb, 'The Government of India Act, 1935 was the largest single source of the Constitution.', '[{"heading":"A long, written document","text":"Unlike Britain, whose constitution is mostly unwritten, India wrote everything down in one long document. When adopted it had 395 Articles in 22 Parts, and 8 Schedules. Amendments have added more, and there are now 12 Schedules."},{"heading":"Borrowed features","text":"The makers studied many constitutions. The parliamentary system came from Britain, the idea of Fundamental Rights from the USA, the Directive Principles from Ireland, the Concurrent List from Australia, and a federation with a strong centre from Canada. Much of the structure came from the Government of India Act, 1935."},{"heading":"Key features","text":"India is a federation with a strong centre: power is shared between the Union and the states. Citizens have a single citizenship, courts are independent, and every adult can vote."}]'::jsonb, '[{"topic":"Politics","question":"The Directive Principles were borrowed from which country?","options":["USA","Britain","Ireland","Canada"],"correct_index":2,"explanation":"The idea of Directive Principles came from Ireland."},{"topic":"Politics","question":"The idea of Fundamental Rights was inspired by…","options":["the USA","Australia","Ireland","Japan"],"correct_index":0,"explanation":"Fundamental Rights were inspired by the Bill of Rights of the USA."},{"topic":"Politics","question":"How many Schedules did the Constitution have when adopted?","options":["8","10","12","22"],"correct_index":0,"explanation":"It had 8 Schedules when adopted; there are 12 today."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-3', 3, 'gk-polity', 'The Preamble', 'The Constitution', 'Politics', 2, 'The Preamble is the Constitution’s opening promise. Let’s read it together!', '["The Preamble is the introduction to the Constitution and states its ideals.","It begins with “We, the people of India”: power comes from the people.","It calls India a Sovereign, Socialist, Secular, Democratic Republic.","It promises Justice, Liberty, Equality and Fraternity.","It is based on the Objectives Resolution moved by Jawaharlal Nehru on 13 December 1946.","In the Kesavananda Bharati case (1973), the Supreme Court held that the Preamble is part of the Constitution."]'::jsonb, 'The Preamble has been amended only once, by the 42nd Amendment in 1976, which added “Socialist”, “Secular” and “Integrity”.', '[{"heading":"We, the people","text":"The Preamble opens with “We, the people of India”. This shows that the Constitution gets its authority from the people. It grew out of the Objectives Resolution that Jawaharlal Nehru moved in the Constituent Assembly in December 1946."},{"heading":"What India is","text":"It describes India as Sovereign (free to decide for itself), Socialist, Secular (no official religion), Democratic (rule by elected representatives) and a Republic (the head of state is elected, not a king or queen)."},{"heading":"What it promises","text":"It promises citizens Justice (social, economic and political), Liberty (of thought, expression, belief, faith and worship), Equality (of status and opportunity) and Fraternity (the dignity of each person and the unity and integrity of the nation)."}]'::jsonb, '[{"topic":"Politics","question":"Which amendment added “Socialist” and “Secular” to the Preamble?","options":["1st","24th","42nd","44th"],"correct_index":2,"explanation":"The 42nd Amendment (1976) added “Socialist”, “Secular” and “Integrity”."},{"topic":"Politics","question":"Who moved the Objectives Resolution?","options":["Dr B. R. Ambedkar","Jawaharlal Nehru","Dr Rajendra Prasad","Mahatma Gandhi"],"correct_index":1,"explanation":"Jawaharlal Nehru moved the Objectives Resolution in December 1946."},{"topic":"Politics","question":"In which case did the Supreme Court say the Preamble is part of the Constitution?","options":["Kesavananda Bharati","Berubari Union","Golaknath","Minerva Mills"],"correct_index":0,"explanation":"In Kesavananda Bharati (1973), the Court held the Preamble is part of the Constitution."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-4', 3, 'gk-polity', 'Fundamental Rights', 'Rights and Duties', 'Politics', 3, 'These are the rights every Indian citizen can go to court to protect. Let’s learn all six!', '["Fundamental Rights are in Part III of the Constitution, Articles 12 to 35.","There are six: Equality, Freedom, Against Exploitation, Freedom of Religion, Cultural and Educational, and Constitutional Remedies.","The Right to Property was removed from this list by the 44th Amendment (1978); it is now a legal right under Article 300A.","Article 21A, the right to education for children aged 6 to 14, was added by the 86th Amendment (2002).","Dr Ambedkar called Article 32, the right to go to the Supreme Court, the “heart and soul” of the Constitution.","Courts protect these rights with five writs, such as habeas corpus and mandamus."]'::jsonb, 'Article 17 abolishes untouchability.', '[{"heading":"Six rights","text":"Part III lists six groups of rights: the Right to Equality (Articles 14 to 18), the Right to Freedom (19 to 22), the Right against Exploitation (23 and 24), the Right to Freedom of Religion (25 to 28), Cultural and Educational Rights (29 and 30), and the Right to Constitutional Remedies (32)."},{"heading":"Changes over time","text":"The Right to Property was once a Fundamental Right. The 44th Amendment in 1978 removed it from Part III; it is now a legal right under Article 300A. The 86th Amendment in 2002 added Article 21A: free and compulsory education for children aged 6 to 14."},{"heading":"Going to court","text":"If a Fundamental Right is taken away, a person can go straight to the Supreme Court under Article 32. Courts can issue five kinds of orders, called writs: habeas corpus, mandamus, prohibition, certiorari and quo warranto."}]'::jsonb, '[{"topic":"Politics","question":"Which Article did Dr Ambedkar call the “heart and soul” of the Constitution?","options":["Article 14","Article 19","Article 21","Article 32"],"correct_index":3,"explanation":"Article 32, the right to constitutional remedies, was called its “heart and soul”."},{"topic":"Politics","question":"The Right to Property is now a legal right under which Article?","options":["Article 31","Article 300A","Article 19","Article 51A"],"correct_index":1,"explanation":"Since the 44th Amendment (1978), it is a legal right under Article 300A."},{"topic":"Politics","question":"How many groups of Fundamental Rights are there today?","options":["Five","Six","Seven","Eleven"],"correct_index":1,"explanation":"There are six; there were seven before the Right to Property was removed."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-5', 3, 'gk-polity', 'Directive Principles and Fundamental Duties', 'Rights and Duties', 'Politics', 4, 'Rights come with goals for the government, and duties for us. Let’s look at both.', '["The Directive Principles of State Policy are in Part IV, Articles 36 to 51.","They are goals for the government; courts cannot enforce them, but they are fundamental in governing the country (Article 37).","Examples: equal pay for equal work, village panchayats (Article 40) and a uniform civil code (Article 44).","Fundamental Duties are in Article 51A, added by the 42nd Amendment (1976) on the Swaran Singh Committee’s advice.","There were 10 duties at first; the 11th, about educating children aged 6 to 14, was added in 2002."]'::jsonb, 'The idea of Directive Principles was borrowed from the Irish Constitution.', '[{"heading":"Goals for the government","text":"The Directive Principles (Part IV) tell the government what kind of society to work towards: fair wages, equal pay for equal work, health, education, village panchayats and protecting the environment. A citizen cannot go to court to enforce them, but governments must keep them in mind when making laws."},{"heading":"Some examples","text":"Article 40 asks the state to organise village panchayats, Article 44 to work towards a uniform civil code, Article 48A to protect the environment and wildlife, Article 50 to keep the judiciary separate from the executive, and Article 51 to promote international peace."},{"heading":"Our duties","text":"Fundamental Duties were added in 1976 as Article 51A, on the recommendation of the Swaran Singh Committee. They include respecting the Constitution, the national flag and anthem, protecting the environment and developing a scientific temper. An eleventh duty, for parents to give children aged 6 to 14 a chance to study, was added in 2002."}]'::jsonb, '[{"topic":"Politics","question":"Fundamental Duties were added on the advice of which committee?","options":["Sarkaria Commission","Swaran Singh Committee","Balwant Rai Mehta Committee","Kothari Commission"],"correct_index":1,"explanation":"The Swaran Singh Committee recommended adding Fundamental Duties in 1976."},{"topic":"Politics","question":"In which Article are the Fundamental Duties listed?","options":["Article 32","Article 44","Article 51A","Article 21A"],"correct_index":2,"explanation":"The Fundamental Duties are listed in Article 51A."},{"topic":"Politics","question":"Which Article asks the state to work towards a uniform civil code?","options":["Article 40","Article 44","Article 48A","Article 50"],"correct_index":1,"explanation":"Article 44 is the Directive Principle about a uniform civil code."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-6', 3, 'gk-polity', 'The President', 'Union Government', 'Politics', 5, 'The President is the head of our country. Let’s see how one is chosen and what they do.', '["The President is the head of state; the executive power of the Union is vested in the President (Article 53).","The President is elected by an electoral college of the elected members of both Houses of Parliament and of the state Legislative Assemblies.","The term is five years, and a President can be re-elected.","A candidate must be at least 35 years old.","A President can be removed only by impeachment, for violating the Constitution (Article 61).","Dr Rajendra Prasad was the first President, and the only one elected twice."]'::jsonb, 'The President takes the oath of office before the Chief Justice of India.', '[{"heading":"Head of state","text":"The President is the head of the Indian state and the supreme commander of the armed forces. Laws are made and government work is done in the President’s name, but in practice the President acts on the advice of the Council of Ministers."},{"heading":"How a President is chosen","text":"The people do not vote directly. An electoral college made up of the elected members of both Houses of Parliament and of the state Legislative Assemblies (including Delhi and Puducherry) elects the President for five years. A candidate must be at least 35 years old."},{"heading":"Special powers","text":"The President can declare a national emergency (Article 352), President’s rule in a state (Article 356) and a financial emergency (Article 360). The President can also grant pardons. Removal is only through impeachment by Parliament."}]'::jsonb, '[{"topic":"Politics","question":"What is the minimum age to become President of India?","options":["25 years","30 years","35 years","40 years"],"correct_index":2,"explanation":"A candidate for President must be at least 35."},{"topic":"Politics","question":"Which Article deals with impeaching the President?","options":["Article 52","Article 61","Article 72","Article 352"],"correct_index":1,"explanation":"Article 61 sets out how a President is impeached."},{"topic":"Politics","question":"Who was the first President of India?","options":["Dr S. Radhakrishnan","Dr Rajendra Prasad","Dr Zakir Husain","V. V. Giri"],"correct_index":1,"explanation":"Dr Rajendra Prasad was the first President, elected twice."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-7', 3, 'gk-polity', 'Prime Minister and Council of Ministers', 'Union Government', 'Politics', 6, 'The President is head of state, but who actually runs the government? Let’s find out.', '["The real executive power lies with the Prime Minister and the Council of Ministers.","The Council of Ministers aids and advises the President (Article 74).","The President appoints the Prime Minister, usually the leader of the majority in the Lok Sabha (Article 75).","The Council of Ministers is collectively responsible to the Lok Sabha.","Since the 91st Amendment (2003), the Council can have at most 15% of the Lok Sabha’s strength.","A minister who is not an MP must become one within six months."]'::jsonb, 'Jawaharlal Nehru was India’s first Prime Minister, from 1947 to 1964.', '[{"heading":"Who really governs","text":"India has a parliamentary system. The President is the formal head, but the Prime Minister and the Council of Ministers take the real decisions. Under Article 74, they aid and advise the President."},{"heading":"Choosing the Prime Minister","text":"After a general election, the President invites the leader of the party or alliance with a majority in the Lok Sabha to become Prime Minister. Other ministers are appointed on the Prime Minister’s advice."},{"heading":"Responsible to the Lok Sabha","text":"The Council of Ministers is collectively responsible to the Lok Sabha: if the Lok Sabha passes a vote of no confidence, the whole government must resign. Since 2003, the Council can have at most 15% as many members as the Lok Sabha."}]'::jsonb, '[{"topic":"Politics","question":"The Council of Ministers is collectively responsible to…","options":["the President","the Rajya Sabha","the Lok Sabha","the Supreme Court"],"correct_index":2,"explanation":"Under Article 75, it is collectively responsible to the Lok Sabha."},{"topic":"Politics","question":"The Council of Ministers can be at most what share of the Lok Sabha?","options":["10%","15%","20%","25%"],"correct_index":1,"explanation":"The 91st Amendment (2003) set the limit at 15%."},{"topic":"Politics","question":"A minister who is not an MP must become one within…","options":["three months","six months","one year","two years"],"correct_index":1,"explanation":"They must become a Member of Parliament within six months."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-8', 3, 'gk-polity', 'Parliament', 'Union Government', 'Politics', 7, 'Parliament makes the country’s laws. Let’s visit both its Houses!', '["Parliament is made up of the President, the Rajya Sabha and the Lok Sabha (Article 79).","The Lok Sabha has 543 elected seats and a five-year term, unless it is dissolved earlier.","The Rajya Sabha is a permanent House: it is never dissolved, and one-third of its members retire every two years.","The Rajya Sabha can have at most 250 members: 238 elected and 12 nominated by the President.","A Money Bill can be introduced only in the Lok Sabha.","The Speaker presides over the Lok Sabha; the Vice-President chairs the Rajya Sabha."]'::jsonb, 'The minimum age is 25 to be a Lok Sabha member and 30 for the Rajya Sabha.', '[{"heading":"Two Houses","text":"The Lok Sabha, or House of the People, is directly elected by the people and has 543 elected seats. The Rajya Sabha, or Council of States, is mostly elected by the state Legislative Assemblies, and 12 members are nominated by the President for their work in fields like art, science and social service."},{"heading":"How long they last","text":"The Lok Sabha’s term is five years, but it can be dissolved earlier. The Rajya Sabha is never dissolved: its members serve six years, and one-third of them retire every two years."},{"heading":"Making laws","text":"A bill becomes law after both Houses pass it and the President agrees. A Money Bill can only start in the Lok Sabha, and the Rajya Sabha can hold it back for at most 14 days. If the Houses disagree on an ordinary bill, the President can call a joint sitting, presided over by the Speaker."}]'::jsonb, '[{"topic":"Politics","question":"What is the minimum age to become a Rajya Sabha member?","options":["21 years","25 years","30 years","35 years"],"correct_index":2,"explanation":"It is 30 for the Rajya Sabha and 25 for the Lok Sabha."},{"topic":"Politics","question":"A Money Bill can be introduced only in…","options":["the Rajya Sabha","the Lok Sabha","either House","a joint sitting"],"correct_index":1,"explanation":"A Money Bill can be introduced only in the Lok Sabha."},{"topic":"Politics","question":"Who chairs the Rajya Sabha?","options":["The Speaker","The Prime Minister","The Vice-President","The President"],"correct_index":2,"explanation":"The Vice-President is the ex officio Chairman of the Rajya Sabha."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-9', 3, 'gk-polity', 'The Judiciary', 'Courts', 'Politics', 8, 'Courts protect the Constitution and our rights. Let’s climb up to the Supreme Court!', '["India has a single, integrated system of courts, with the Supreme Court at the top, then High Courts, then lower courts.","The Supreme Court began work on 28 January 1950 (Article 124).","Supreme Court judges retire at 65; High Court judges at 62.","A judge can be removed only by Parliament, through a special procedure, for proved misbehaviour or incapacity.","The Supreme Court issues writs under Article 32, and High Courts under Article 226.","Courts can strike down laws that go against the Constitution; this is called judicial review."]'::jsonb, 'Under Article 141, the Supreme Court’s decisions are binding on all courts in India.', '[{"heading":"One system of courts","text":"Unlike some federations, India has one connected system of courts. The Supreme Court in New Delhi is at the top. Each state (or group of states) has a High Court, and below them are district and other lower courts."},{"heading":"Independent judges","text":"To keep them independent, judges cannot be removed easily: only Parliament can remove them, by a special majority, for proved misbehaviour or incapacity. Supreme Court judges serve until 65, and High Court judges until 62."},{"heading":"Guarding the Constitution","text":"Courts can declare a law invalid if it goes against the Constitution; this power is called judicial review. Through writs under Articles 32 and 226, and through public interest litigation, they protect people’s rights."}]'::jsonb, '[{"topic":"Politics","question":"At what age do Supreme Court judges retire?","options":["60","62","65","70"],"correct_index":2,"explanation":"Supreme Court judges retire at 65; High Court judges at 62."},{"topic":"Politics","question":"Under which Article do High Courts issue writs?","options":["Article 32","Article 124","Article 141","Article 226"],"correct_index":3,"explanation":"High Courts issue writs under Article 226."},{"topic":"Politics","question":"The power of courts to strike down unconstitutional laws is called…","options":["judicial review","impeachment","quo warranto","a joint sitting"],"correct_index":0,"explanation":"Judicial review lets courts declare such laws invalid."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-10', 3, 'gk-polity', 'Panchayati Raj and municipalities', 'Local Government', 'Politics', 9, 'Democracy starts in your own village or town. Let’s see how local government works!', '["The 73rd Amendment (1992) gave Panchayati Raj a place in the Constitution, in Part IX.","It came into force on 24 April 1993, now marked as National Panchayati Raj Day.","There are three levels: gram panchayat (village), panchayat samiti (block) and zila parishad (district).","At least one-third of the seats are reserved for women.","Panchayat elections are held every five years by the State Election Commission.","The 74th Amendment (1992) did the same for towns and cities, in Part IXA."]'::jsonb, 'Panchayati Raj was first launched at Nagaur in Rajasthan on 2 October 1959.', '[{"heading":"Where it began","text":"In 1957, the Balwant Rai Mehta Committee recommended a three-level system of local self-government. Rajasthan was the first state to start it, at Nagaur on 2 October 1959."},{"heading":"Part of the Constitution","text":"The 73rd Amendment of 1992 made panchayats part of the Constitution (Part IX), from 24 April 1993. It set up three levels, elections every five years, a State Election Commission, and reserved at least one-third of seats for women. The Eleventh Schedule lists 29 subjects panchayats can look after."},{"heading":"Towns and cities","text":"The 74th Amendment of 1992 did the same for urban areas, adding Part IXA on municipalities: nagar panchayats, municipal councils and municipal corporations. The Twelfth Schedule lists 18 subjects they handle."}]'::jsonb, '[{"topic":"Politics","question":"Which amendment gave Panchayati Raj a place in the Constitution?","options":["42nd","61st","73rd","86th"],"correct_index":2,"explanation":"The 73rd Amendment (1992) added Part IX on panchayats."},{"topic":"Politics","question":"Where was Panchayati Raj first launched in 1959?","options":["Nagaur, Rajasthan","Anand, Gujarat","Patna, Bihar","Pune, Maharashtra"],"correct_index":0,"explanation":"It began at Nagaur in Rajasthan on 2 October 1959."},{"topic":"Politics","question":"What share of panchayat seats is reserved for women?","options":["At least one-quarter","At least one-third","At least half","None"],"correct_index":1,"explanation":"At least one-third of the seats are reserved for women."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-medieval-india', 'Medieval India', 'History', 'explore', '', 'General Knowledge', 'Rajputs, Cholas, the Delhi Sultanate, the Mughals and the Marathas.', 19) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-1', 3, 'gk-medieval-india', 'Rajputs and the struggle for Kannauj', 'Early medieval kingdoms', 'History', 0, 'After the Guptas, many kingdoms rose and fought for power. Let’s meet the big players!', '["Three dynasties fought for the city of Kannauj: the Palas, the Pratiharas and the Rashtrakutas. This is called the tripartite struggle.","The Palas ruled Bengal; their king Dharmapala founded the Vikramashila university.","The Rashtrakutas of the Deccan built the Kailasa temple at Ellora, cut out of a single rock.","Mahmud of Ghazni raided India many times and attacked the Somnath temple in 1025.","Prithviraj Chauhan defeated Muhammad Ghori in the First Battle of Tarain (1191) but lost the second one (1192)."]'::jsonb, 'The Kailasa temple at Ellora was built under the Rashtrakuta king Krishna I.', '[{"heading":"Many kingdoms","text":"From about the 8th century, no single empire ruled northern India. Powerful families, many of them Rajput clans such as the Pratiharas and Chauhans, ruled different regions and often fought one another."},{"heading":"The fight for Kannauj","text":"Kannauj, on the Ganga, was a rich and famous city. The Palas from the east, the Pratiharas from the west and the Rashtrakutas from the south fought over it for nearly two hundred years. Historians call this the tripartite (three-sided) struggle."},{"heading":"Raids from the north-west","text":"Mahmud of Ghazni raided India again and again in the early 11th century, carrying away great wealth, including from Somnath in 1025. Later, Muhammad Ghori lost to Prithviraj Chauhan at Tarain in 1191, but won the second battle there in 1192. This opened the way for the Delhi Sultanate."}]'::jsonb, '[{"topic":"History","question":"Which three dynasties fought over Kannauj?","options":["Cholas, Cheras, Pandyas","Palas, Pratiharas, Rashtrakutas","Mughals, Rajputs, Marathas","Khaljis, Tughlaqs, Lodis"],"correct_index":1,"explanation":"The Palas, Pratiharas and Rashtrakutas fought the tripartite struggle for Kannauj."},{"topic":"History","question":"Who won the Second Battle of Tarain in 1192?","options":["Prithviraj Chauhan","Mahmud of Ghazni","Muhammad Ghori","Qutb-ud-din Aibak"],"correct_index":2,"explanation":"Muhammad Ghori defeated Prithviraj Chauhan in the second battle."},{"topic":"History","question":"Which Pala king founded the Vikramashila university?","options":["Gopala","Dharmapala","Devapala","Mahipala"],"correct_index":1,"explanation":"Dharmapala founded Vikramashila in Bihar."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-2', 3, 'gk-medieval-india', 'The Cholas', 'Early medieval kingdoms', 'History', 1, 'The Cholas built giant temples and sent ships across the sea. Let’s sail with them!', '["The Chola empire was based in the Kaveri delta of Tamil Nadu; Vijayalaya started its rise in the 9th century.","Rajaraja I built the Brihadeeswarar temple at Thanjavur, completed around 1010.","His son Rajendra I marched to the Ganga and took the title “Gangaikondachola”.","Rajendra I also sent a navy to South-East Asia, against the Srivijaya kingdom.","Chola villages ran their own affairs through assemblies; inscriptions at Uttaramerur describe how members were chosen.","Chola artists are famous for bronze statues, especially of Shiva as Nataraja."]'::jsonb, 'Rajendra I built a new capital called Gangaikondacholapuram.', '[{"heading":"Rise of the Cholas","text":"The Cholas were an old Tamil family. From the 9th century, starting with Vijayalaya, they grew into a great power in the Kaveri delta. Rajaraja I and his son Rajendra I made it one of the strongest empires in Indian history."},{"heading":"Power on land and sea","text":"Rajendra I led an army north to the Ganga and took the title Gangaikondachola, “the Chola who took the Ganga”. He also sent a navy to South-East Asia. Few Indian kings ever fought so far across the sea."},{"heading":"Temples, bronzes and villages","text":"The huge Brihadeeswarar temple at Thanjavur was built by Rajaraja I. Chola metal workers made beautiful bronze statues. Villages had assemblies, called sabhas and urs, that looked after local work; the Uttaramerur inscriptions explain their rules."}]'::jsonb, '[{"topic":"History","question":"Who built the Brihadeeswarar temple at Thanjavur?","options":["Vijayalaya","Rajaraja I","Rajendra I","Krishnadeva Raya"],"correct_index":1,"explanation":"Rajaraja I built it; it was completed around 1010."},{"topic":"History","question":"Which Chola king took the title “Gangaikondachola”?","options":["Rajendra I","Rajaraja I","Vijayalaya","Parantaka I"],"correct_index":0,"explanation":"Rajendra I took it after his army reached the Ganga."},{"topic":"History","question":"The Uttaramerur inscriptions tell us about…","options":["Chola village assemblies","Mughal coins","Buddhist monasteries","Maratha forts"],"correct_index":0,"explanation":"They describe how members of village assemblies were chosen."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-3', 3, 'gk-medieval-india', 'The Delhi Sultanate', 'The Sultanate age', 'History', 2, 'Five dynasties ruled from Delhi for over 300 years. Let’s go through them one by one!', '["The Delhi Sultanate lasted from 1206 to 1526, under five dynasties: Mamluk (Slave), Khalji, Tughlaq, Sayyid and Lodi.","Qutb-ud-din Aibak founded it in 1206 and began the Qutb Minar; Iltutmish completed it.","Razia Sultan was the only woman to rule from the throne of Delhi.","Alauddin Khalji fixed prices in the markets of Delhi and beat back Mongol attacks.","Muhammad bin Tughlaq moved the capital to Daulatabad and tried token coins of copper and brass.","The last Sultan, Ibrahim Lodi, lost to Babur at the First Battle of Panipat in 1526."]'::jsonb, 'Timur (Tamerlane) attacked Delhi in 1398, during Tughlaq rule.', '[{"heading":"Five dynasties","text":"After Muhammad Ghori, his general Qutb-ud-din Aibak became the first Sultan of Delhi in 1206. The Mamluk, or Slave, dynasty was followed by the Khaljis (1290), the Tughlaqs (1320), the Sayyids (1414) and the Lodis (1451)."},{"heading":"Famous Sultans","text":"Iltutmish made the Sultanate strong and finished the Qutb Minar. His daughter Razia ruled from 1236 to 1240. Alauddin Khalji kept a large army and controlled market prices to pay for it. Muhammad bin Tughlaq tried bold ideas, such as moving the capital to Daulatabad, but many failed."},{"heading":"The end","text":"Timur’s attack in 1398 weakened Delhi badly. The Lodis were the last dynasty; Sikandar Lodi founded the city of Agra. In 1526, Babur defeated Ibrahim Lodi at Panipat and the Mughal Empire began."}]'::jsonb, '[{"topic":"History","question":"Who founded the Delhi Sultanate in 1206?","options":["Iltutmish","Alauddin Khalji","Qutb-ud-din Aibak","Balban"],"correct_index":2,"explanation":"Qutb-ud-din Aibak became the first Sultan in 1206."},{"topic":"History","question":"Which was the LAST dynasty of the Delhi Sultanate?","options":["Tughlaq","Sayyid","Khalji","Lodi"],"correct_index":3,"explanation":"The Lodis were last; Ibrahim Lodi lost to Babur in 1526."},{"topic":"History","question":"Which Sultan moved the capital to Daulatabad?","options":["Firoz Shah Tughlaq","Muhammad bin Tughlaq","Alauddin Khalji","Sikandar Lodi"],"correct_index":1,"explanation":"Muhammad bin Tughlaq moved the capital from Delhi to Daulatabad."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-4', 3, 'gk-medieval-india', 'Vijayanagara and the Bahmani kingdom', 'The Sultanate age', 'History', 3, 'In the south, two great kingdoms grew side by side. Let’s visit Hampi!', '["The Vijayanagara empire was founded in 1336 by the brothers Harihara and Bukka.","Its capital, Vijayanagara, is today’s Hampi in Karnataka, a UNESCO World Heritage Site.","Its greatest king, Krishnadeva Raya, wrote the Telugu poem Amuktamalyada.","The Bahmani kingdom was founded in 1347 by Alauddin Hasan Bahman Shah; Mahmud Gawan was its famous minister.","The Bahmani kingdom later split into five Deccan Sultanates, such as Bijapur and Golconda.","The Deccan Sultanates together defeated Vijayanagara at the Battle of Talikota in 1565."]'::jsonb, 'The Gol Gumbaz, a huge domed tomb, stands at Bijapur.', '[{"heading":"City of Victory","text":"Vijayanagara means “city of victory”. Founded in 1336 by Harihara and Bukka on the Tungabhadra river, it grew rich from trade in cotton, spices and horses. Foreign visitors wrote with wonder about its markets."},{"heading":"Krishnadeva Raya","text":"Krishnadeva Raya ruled in the early 16th century. He won many wars, built temples and supported poets in Telugu, Kannada, Tamil and Sanskrit. He wrote Amuktamalyada himself."},{"heading":"The Bahmanis and Talikota","text":"North of the Krishna river, the Bahmani kingdom was set up in 1347. It later broke into five Sultanates: Bijapur, Golconda, Ahmadnagar, Berar and Bidar. In 1565, four of them joined together and defeated Vijayanagara at Talikota, and the great city was ruined."}]'::jsonb, '[{"topic":"History","question":"Who founded the Vijayanagara empire?","options":["Harihara and Bukka","Krishnadeva Raya","Mahmud Gawan","Rajendra I"],"correct_index":0,"explanation":"The brothers Harihara and Bukka founded it in 1336."},{"topic":"History","question":"In which year was the Battle of Talikota fought?","options":["1336","1526","1565","1576"],"correct_index":2,"explanation":"The Deccan Sultanates defeated Vijayanagara at Talikota in 1565."},{"topic":"History","question":"The ruins of Vijayanagara are at…","options":["Hampi","Bidar","Thanjavur","Golconda"],"correct_index":0,"explanation":"Vijayanagara’s ruins are at Hampi in Karnataka."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-5', 3, 'gk-medieval-india', 'Babur to Akbar', 'The Mughal Empire', 'History', 4, 'The Mughals ruled for more than 300 years. Let’s meet the first great ones!', '["Babur founded the Mughal Empire after winning the First Battle of Panipat in 1526.","Babur wrote his memoirs, the Baburnama, in Turki.","Sher Shah Suri drove out Humayun in 1540; he issued a silver coin called the rupiya and improved the road we call the Grand Trunk Road.","Akbar became emperor in 1556 and won the Second Battle of Panipat against Hemu that year.","Akbar created the mansabdari system, removed the jizya tax and built Fatehpur Sikri.","Abul Fazl wrote the Akbarnama, and Todar Mal reformed land revenue."]'::jsonb, 'The Battle of Haldighati (1576) was fought between Akbar’s army and Maharana Pratap of Mewar.', '[{"heading":"Babur and Humayun","text":"Babur, from Central Asia, defeated Ibrahim Lodi at Panipat in 1526 and Rana Sanga at Khanwa in 1527. His son Humayun lost the throne to Sher Shah Suri in 1540, and won it back only in 1555, shortly before his death."},{"heading":"Sher Shah Suri","text":"Sher Shah ruled for only five years but made lasting changes. He issued the silver rupiya, measured land for fair taxes, and improved roads with rest houses, including the road from Bengal to the north-west now called the Grand Trunk Road."},{"heading":"Akbar the Great","text":"Akbar became emperor at 13. He gave every officer a rank (mansab), removed the jizya tax on non-Muslims, invited scholars of all religions to debate, and married into Rajput families. His court had famous figures such as Birbal, the singer Tansen, Abul Fazl and Todar Mal."}]'::jsonb, '[{"topic":"History","question":"Who issued the silver coin called the rupiya?","options":["Babur","Akbar","Sher Shah Suri","Alauddin Khalji"],"correct_index":2,"explanation":"Sher Shah Suri issued the silver rupiya."},{"topic":"History","question":"Who wrote the Akbarnama?","options":["Birbal","Abul Fazl","Todar Mal","Tansen"],"correct_index":1,"explanation":"Abul Fazl wrote the Akbarnama, the history of Akbar’s rule."},{"topic":"History","question":"Akbar defeated Hemu in which battle?","options":["First Battle of Panipat","Second Battle of Panipat","Battle of Khanwa","Battle of Haldighati"],"correct_index":1,"explanation":"Akbar’s army defeated Hemu at Panipat in 1556."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-6', 3, 'gk-medieval-india', 'Jahangir to Aurangzeb', 'The Mughal Empire', 'History', 5, 'Paintings, the Taj Mahal and a giant empire. Let’s see the later Mughals!', '["Jahangir was known for his “chain of justice”; the Englishman Sir Thomas Roe visited his court in 1615.","Jahangir’s queen Nur Jahan had great influence at court.","Shah Jahan built the Taj Mahal at Agra for his wife Mumtaz Mahal, and the Red Fort in Delhi.","Under Aurangzeb, the empire reached its largest size.","Aurangzeb brought back the jizya tax in 1679; he died in 1707.","After 1707 the empire weakened; Nadir Shah of Persia sacked Delhi in 1739 and took the Peacock Throne."]'::jsonb, 'The Peacock Throne was made for Shah Jahan.', '[{"heading":"Jahangir","text":"Jahangir loved painting and nature, and Mughal miniature painting flowered in his time. A “chain of justice” was hung so that people could ring it and ask for his help. His wife Nur Jahan shared in ruling, and even had coins struck in her name."},{"heading":"Shah Jahan the builder","text":"Shah Jahan’s rule is remembered for its buildings: the Taj Mahal at Agra, and in his new city of Shahjahanabad (Delhi), the Red Fort and the Jama Masjid. In his last years his son Aurangzeb took the throne and kept him a prisoner in Agra Fort."},{"heading":"Aurangzeb and after","text":"Aurangzeb spent many years fighting in the Deccan, against the Deccan Sultanates and the Marathas. The empire was at its largest, but costly wars and revolts weakened it. After his death in 1707, governors became almost independent, and Delhi was looted by Nadir Shah in 1739."}]'::jsonb, '[{"topic":"History","question":"Which Mughal emperor built the Taj Mahal?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"correct_index":2,"explanation":"Shah Jahan built it in memory of Mumtaz Mahal."},{"topic":"History","question":"Sir Thomas Roe came to the court of…","options":["Babur","Jahangir","Shah Jahan","Aurangzeb"],"correct_index":1,"explanation":"Sir Thomas Roe visited Jahangir’s court in 1615."},{"topic":"History","question":"Who took the Peacock Throne from Delhi in 1739?","options":["Ahmad Shah Abdali","Timur","Nadir Shah","Mahmud of Ghazni"],"correct_index":2,"explanation":"Nadir Shah of Persia sacked Delhi in 1739."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-7', 3, 'gk-medieval-india', 'Bhakti and Sufi movements', 'Religion and culture', 'History', 6, 'Saints and poets taught love and devotion in simple words. Let’s listen to them!', '["The Bhakti movement taught that God can be reached by love and devotion, not only by rituals.","In the Tamil region, the Alvars sang for Vishnu and the Nayanars for Shiva.","Kabir and Guru Nanak taught that God is one and rejected caste divisions.","Guru Nanak (1469–1539) was the founder of Sikhism.","Mirabai sang for Krishna, and Tulsidas wrote the Ramcharitmanas in Awadhi.","Among the Sufis, the Chishti order was the best known: Khwaja Moinuddin Chishti at Ajmer and Nizamuddin Auliya in Delhi."]'::jsonb, 'The poet Amir Khusrau was a follower of Nizamuddin Auliya.', '[{"heading":"Devotion over ritual","text":"Bhakti means devotion. Its saints sang in the languages people spoke every day, and welcomed people of every caste. It began with the Alvars and Nayanars in the Tamil region and spread across India over many centuries."},{"heading":"Saints across India","text":"Basavanna led the Lingayat (Virashaiva) movement in Karnataka. Namdev and Tukaram sang in Marathi, Chaitanya in Bengal, and Kabir, Surdas and Tulsidas in Hindi dialects. Guru Nanak founded Sikhism; Guru Arjan Dev later compiled the Adi Granth."},{"heading":"The Sufis","text":"Sufis were Muslim mystics who sought closeness to God through love, music and service. Their teachers lived in khanqahs (hospices). The tombs (dargahs) of Chishti saints, such as at Ajmer and Delhi, are still visited by people of all faiths."}]'::jsonb, '[{"topic":"History","question":"Who wrote the Ramcharitmanas?","options":["Kabir","Surdas","Tulsidas","Tukaram"],"correct_index":2,"explanation":"Tulsidas wrote the Ramcharitmanas in Awadhi."},{"topic":"History","question":"The dargah of Khwaja Moinuddin Chishti is at…","options":["Delhi","Ajmer","Agra","Lahore"],"correct_index":1,"explanation":"His dargah is at Ajmer in Rajasthan."},{"topic":"History","question":"The Alvars were devotees of…","options":["Shiva","Vishnu","the Buddha","Mahavira"],"correct_index":1,"explanation":"The Alvars sang for Vishnu; the Nayanars for Shiva."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-medieval-8', 3, 'gk-medieval-india', 'Shivaji and the Marathas', 'Rise of the Marathas', 'History', 7, 'From hill forts in Maharashtra rose a new power. Let’s meet Shivaji Maharaj!', '["Shivaji was born in 1630 at the fort of Shivneri, near Pune.","He was crowned Chhatrapati at Raigad in 1674.","He was helped by a council of eight ministers, the Ashtapradhan.","The Marathas collected taxes called chauth and sardeshmukhi.","After Shivaji, the Peshwas (chief ministers), such as Baji Rao I, made Maratha power spread across India.","The Marathas lost to Ahmad Shah Abdali at the Third Battle of Panipat in 1761."]'::jsonb, 'Shivaji escaped from Aurangzeb’s court at Agra in 1666.', '[{"heading":"Shivaji","text":"Shivaji built a kingdom using hill forts and fast-moving soldiers. He fought the Sultan of Bijapur and the Mughals. He signed the Treaty of Purandar with the Mughals in 1665, and later escaped from Agra. In 1674 he was crowned Chhatrapati at Raigad."},{"heading":"Ruling the kingdom","text":"Shivaji ruled with the help of eight ministers, the Ashtapradhan. The Marathas took chauth (a quarter of the revenue) and sardeshmukhi (an extra tenth) from nearby lands. He also built a navy to guard the coast."},{"heading":"The Peshwas and Panipat","text":"In the 18th century the Peshwas, starting with Balaji Vishwanath, led the Marathas from Pune. Under Baji Rao I they spread north. In 1761 they lost the Third Battle of Panipat to Ahmad Shah Abdali of Afghanistan, a heavy defeat."}]'::jsonb, '[{"topic":"History","question":"Where was Shivaji crowned in 1674?","options":["Shivneri","Raigad","Pune","Purandar"],"correct_index":1,"explanation":"Shivaji was crowned Chhatrapati at Raigad."},{"topic":"History","question":"Shivaji’s council of eight ministers was called…","options":["Navaratna","Ashtapradhan","Panchayat","Sabha"],"correct_index":1,"explanation":"The Ashtapradhan was his council of eight ministers."},{"topic":"History","question":"Who defeated the Marathas at Panipat in 1761?","options":["Nadir Shah","Aurangzeb","Ahmad Shah Abdali","Babur"],"correct_index":2,"explanation":"Ahmad Shah Abdali won the Third Battle of Panipat in 1761."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-modern-india', 'Modern India', 'History', 'explore', '', 'General Knowledge', 'From the first European traders to the freedom struggle and 1947.', 20) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-1', 3, 'gk-modern-india', 'Traders from Europe', 'Coming of the Europeans', 'History', 0, 'Spices brought Europeans to India by sea. Let’s see who came first!', '["Vasco da Gama of Portugal reached Calicut by sea in 1498.","The Portuguese captured Goa in 1510, under Afonso de Albuquerque.","The English East India Company got its charter from Queen Elizabeth I on 31 December 1600.","The Dutch company was formed in 1602 and the French company in 1664.","The English set up a factory (trading post) at Surat in 1613.","The English beat the French in the Carnatic Wars; the Battle of Wandiwash (1760) ended French hopes in India."]'::jsonb, 'The Portuguese were the first Europeans to come and the last to leave: Goa was freed in 1961.', '[{"heading":"A sea route to India","text":"European traders wanted Indian spices and cloth without going through Arab and Venetian middlemen. In 1498, Vasco da Gama sailed around Africa and landed at Calicut on the Malabar coast."},{"heading":"The trading companies","text":"The Portuguese took Goa in 1510. The English East India Company was formed in 1600, the Dutch in 1602 and the French in 1664. They built factories, which were trading posts with warehouses, at places like Surat, Madras, Bombay, Calcutta and Pondicherry."},{"heading":"English against French","text":"In the 18th century, the English and French fought three Carnatic Wars in South India. The English won at Wandiwash in 1760, and the French were left with only a few small towns such as Pondicherry."}]'::jsonb, '[{"topic":"History","question":"Where did Vasco da Gama land in 1498?","options":["Goa","Calicut","Surat","Madras"],"correct_index":1,"explanation":"Vasco da Gama reached Calicut in 1498."},{"topic":"History","question":"In which year did the English East India Company get its charter?","options":["1498","1600","1613","1757"],"correct_index":1,"explanation":"Queen Elizabeth I gave the charter on 31 December 1600."},{"topic":"History","question":"Which battle ended French hopes in India?","options":["Plassey","Buxar","Wandiwash","Panipat"],"correct_index":2,"explanation":"The English beat the French at Wandiwash in 1760."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-2', 3, 'gk-modern-india', 'How the British took power', 'Coming of the Europeans', 'History', 1, 'A trading company slowly became a ruler. Let’s see how it happened!', '["At the Battle of Plassey (1757), Robert Clive defeated Siraj-ud-Daulah of Bengal, helped by Mir Jafar’s betrayal.","At the Battle of Buxar (1764), the Company beat Mir Qasim, Shuja-ud-Daulah and the Mughal emperor Shah Alam II.","In 1765 the Company got the Diwani: the right to collect revenue in Bengal, Bihar and Orissa.","Tipu Sultan of Mysore died fighting the British at Srirangapatna in 1799.","Lord Wellesley’s Subsidiary Alliance made Indian rulers keep British troops and pay for them.","Lord Dalhousie’s Doctrine of Lapse took over states whose rulers died without a natural heir, such as Satara and Jhansi."]'::jsonb, 'Warren Hastings was the first Governor-General of Bengal, under the Regulating Act of 1773.', '[{"heading":"Plassey and Buxar","text":"In 1757 the Company fought Siraj-ud-Daulah, the Nawab of Bengal, at Plassey. His commander Mir Jafar changed sides, and the Company won. At Buxar in 1764, it defeated three rulers together. The next year it got the Diwani of Bengal, Bihar and Orissa."},{"heading":"Wars across India","text":"The Company fought four wars with Mysore, where Hyder Ali and his son Tipu Sultan resisted strongly. It also fought the Marathas and, later, the Sikhs in Punjab. By the mid-19th century most of India was under its rule."},{"heading":"Taking states without war","text":"Under the Subsidiary Alliance (from 1798), a ruler kept a British army in his state, paid for it, and could not make treaties without the British. Hyderabad was the first to join. Under the Doctrine of Lapse, Dalhousie took over states like Satara (1848) and Jhansi."}]'::jsonb, '[{"topic":"History","question":"Who led the Company’s army at Plassey?","options":["Warren Hastings","Robert Clive","Lord Dalhousie","Lord Wellesley"],"correct_index":1,"explanation":"Robert Clive won the Battle of Plassey in 1757."},{"topic":"History","question":"The Doctrine of Lapse is linked with…","options":["Lord Wellesley","Lord Cornwallis","Lord Dalhousie","Lord Curzon"],"correct_index":2,"explanation":"Lord Dalhousie used the Doctrine of Lapse."},{"topic":"History","question":"Tipu Sultan was the ruler of…","options":["Hyderabad","Mysore","Awadh","Bengal"],"correct_index":1,"explanation":"Tipu Sultan ruled Mysore and died fighting in 1799."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-3', 3, 'gk-modern-india', 'The Revolt of 1857', 'The Revolt of 1857', 'History', 2, 'In 1857, soldiers and people rose against Company rule. Let’s see what happened!', '["The revolt began at Meerut on 10 May 1857, when sepoys rose up and marched to Delhi.","Rumours that the new Enfield rifle cartridges were greased with cow and pig fat angered the sepoys.","Earlier, on 29 March 1857, Mangal Pandey attacked British officers at Barrackpore.","The rebels declared Bahadur Shah Zafar, the old Mughal king, their emperor.","Leaders included Rani Lakshmibai (Jhansi), Nana Saheb (Kanpur), Begum Hazrat Mahal (Lucknow) and Kunwar Singh (Bihar).","After the revolt, the Government of India Act 1858 ended Company rule; the British Crown took over."]'::jsonb, 'Bahadur Shah Zafar was sent away to Rangoon (Yangon), where he died.', '[{"heading":"Why people were angry","text":"Farmers suffered from heavy taxes, rulers had lost their states, and soldiers were unhappy with pay and treatment. The greased cartridges, which had to be bitten open, were the spark."},{"heading":"The revolt spreads","text":"From Meerut, the sepoys reached Delhi and made Bahadur Shah Zafar their leader. The revolt spread to Kanpur, Lucknow, Jhansi, Bihar and many other places. Rani Lakshmibai and Tantia Tope fought bravely until 1858."},{"heading":"After 1857","text":"The British crushed the revolt by 1858. The Government of India Act of 1858 ended the East India Company’s rule, and India came under the British Crown. Lord Canning became the first Viceroy."}]'::jsonb, '[{"topic":"History","question":"Where did the Revolt of 1857 begin on 10 May?","options":["Delhi","Meerut","Kanpur","Barrackpore"],"correct_index":1,"explanation":"It began at Meerut on 10 May 1857."},{"topic":"History","question":"Who led the revolt in Lucknow?","options":["Rani Lakshmibai","Begum Hazrat Mahal","Nana Saheb","Kunwar Singh"],"correct_index":1,"explanation":"Begum Hazrat Mahal led the revolt in Lucknow."},{"topic":"History","question":"Who became the first Viceroy of India?","options":["Lord Dalhousie","Lord Canning","Lord Curzon","Warren Hastings"],"correct_index":1,"explanation":"Lord Canning became the first Viceroy in 1858."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-4', 3, 'gk-modern-india', 'Social and religious reformers', 'Reform movements', 'History', 3, 'Brave reformers fought for women, education and equality. Let’s meet them!', '["Raja Ram Mohan Roy founded the Brahmo Samaj in 1828 and fought against sati.","Sati was banned in 1829 by Governor-General Lord William Bentinck.","Ishwar Chandra Vidyasagar’s efforts led to the Hindu Widows’ Remarriage Act of 1856.","Swami Dayananda Saraswati founded the Arya Samaj in 1875 and wrote Satyarth Prakash.","Jyotiba Phule founded the Satyashodhak Samaj in 1873; with Savitribai Phule he opened a school for girls in Pune in 1848.","Swami Vivekananda spoke at Chicago in 1893 and founded the Ramakrishna Mission in 1897."]'::jsonb, 'Sir Syed Ahmad Khan set up the college at Aligarh in 1875 that later became Aligarh Muslim University.', '[{"heading":"Raja Ram Mohan Roy","text":"Often called the father of modern India’s reform movement, Raja Ram Mohan Roy wanted reason and fairness in religion and society. He founded the Brahmo Samaj in 1828 and campaigned against sati, which was banned in 1829."},{"heading":"For women and the poor","text":"Vidyasagar worked for widow remarriage and girls’ education. Jyotiba and Savitribai Phule opened schools for girls and for lower-caste children, and Jyotiba’s Satyashodhak Samaj worked for equality."},{"heading":"New religious movements","text":"Dayananda Saraswati’s Arya Samaj called people to go back to the Vedas and worked against untouchability. Swami Vivekananda, a disciple of Ramakrishna Paramahamsa, spoke at the Parliament of Religions in Chicago in 1893 and set up the Ramakrishna Mission to serve people."}]'::jsonb, '[{"topic":"History","question":"Who founded the Brahmo Samaj?","options":["Swami Dayananda Saraswati","Raja Ram Mohan Roy","Swami Vivekananda","Jyotiba Phule"],"correct_index":1,"explanation":"Raja Ram Mohan Roy founded the Brahmo Samaj in 1828."},{"topic":"History","question":"Who wrote Satyarth Prakash?","options":["Swami Dayananda Saraswati","Ishwar Chandra Vidyasagar","Swami Vivekananda","Sir Syed Ahmad Khan"],"correct_index":0,"explanation":"Swami Dayananda Saraswati, founder of the Arya Samaj."},{"topic":"History","question":"In which year was sati banned?","options":["1828","1829","1856","1875"],"correct_index":1,"explanation":"Lord William Bentinck banned sati in 1829."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-5', 3, 'gk-modern-india', 'The Indian National Congress', 'Freedom struggle: early years', 'History', 4, 'In 1885, Indians came together to speak with one voice. Let’s see how the Congress began!', '["The Indian National Congress was founded on 28 December 1885 in Bombay.","A. O. Hume, a retired British officer, helped found it; W. C. Bonnerjee was its first president.","Early leaders, called Moderates, asked for reforms through petitions and speeches.","Dadabhai Naoroji, the “Grand Old Man of India”, explained the “drain of wealth” from India to Britain.","Leaders such as Lala Lajpat Rai, Bal Gangadhar Tilak and Bipin Chandra Pal (Lal-Bal-Pal) wanted stronger action.","Tilak said: “Swaraj is my birthright and I shall have it.”"]'::jsonb, 'About 72 delegates attended the first Congress session in Bombay.', '[{"heading":"A national body","text":"Educated Indians had formed many local groups. In December 1885, delegates from across India met in Bombay and formed the Indian National Congress. W. C. Bonnerjee presided."},{"heading":"The Moderates","text":"Leaders like Dadabhai Naoroji, Gopal Krishna Gokhale and Pherozeshah Mehta believed in polite requests. They asked for Indians in councils and services, and showed with facts how British rule drained India’s wealth."},{"heading":"A stronger voice","text":"By 1900, many felt requests were not enough. Lal-Bal-Pal and others wanted self-rule (swaraj), boycott of British goods and more people taking part. They were called the Extremists, or Assertives."}]'::jsonb, '[{"topic":"History","question":"Who was the first president of the Indian National Congress?","options":["A. O. Hume","Dadabhai Naoroji","W. C. Bonnerjee","Gopal Krishna Gokhale"],"correct_index":2,"explanation":"W. C. Bonnerjee presided over the first session in 1885."},{"topic":"History","question":"Who is called the “Grand Old Man of India”?","options":["Bal Gangadhar Tilak","Dadabhai Naoroji","Lala Lajpat Rai","Pherozeshah Mehta"],"correct_index":1,"explanation":"Dadabhai Naoroji, who explained the “drain of wealth”."},{"topic":"History","question":"Who said “Swaraj is my birthright and I shall have it”?","options":["Mahatma Gandhi","Bal Gangadhar Tilak","Bipin Chandra Pal","Subhas Chandra Bose"],"correct_index":1,"explanation":"Bal Gangadhar Tilak said it."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-6', 3, 'gk-modern-india', 'Partition of Bengal and Swadeshi', 'Freedom struggle: early years', 'History', 5, 'When Bengal was split in two, the whole country protested. Let’s find out why!', '["Lord Curzon divided Bengal; the partition came into effect on 16 October 1905.","People answered with the Swadeshi movement: using Indian goods and boycotting British ones.","The All-India Muslim League was founded in 1906 at Dhaka.","The Congress split into Moderates and Extremists at Surat in 1907.","The partition was cancelled in 1911, and the capital was moved from Calcutta to Delhi.","In 1916, Tilak and Annie Besant started Home Rule Leagues, and the Congress and League signed the Lucknow Pact."]'::jsonb, 'The Morley-Minto Reforms of 1909 gave Muslims separate electorates.', '[{"heading":"Dividing Bengal","text":"The British said Bengal was too big to govern. But many saw the partition as a way to divide Hindus and Muslims and weaken the national movement in Bengal. On 16 October 1905, people tied rakhis to one another as a sign of unity."},{"heading":"Swadeshi and boycott","text":"People burned foreign cloth, set up Indian factories and national schools. Rabindranath Tagore wrote songs for the movement. The protests forced the British to cancel the partition in 1911, when the capital also moved to Delhi."},{"heading":"New groups and pacts","text":"The Muslim League was formed in 1906. The Congress split at Surat in 1907 but came together again in 1916, when it also signed the Lucknow Pact with the League. That year Tilak and Annie Besant started Home Rule Leagues to demand self-government."}]'::jsonb, '[{"topic":"History","question":"Which Viceroy partitioned Bengal in 1905?","options":["Lord Curzon","Lord Minto","Lord Canning","Lord Hardinge"],"correct_index":0,"explanation":"Lord Curzon divided Bengal in 1905."},{"topic":"History","question":"Where was the Muslim League founded in 1906?","options":["Lahore","Aligarh","Dhaka","Lucknow"],"correct_index":2,"explanation":"The All-India Muslim League was founded at Dhaka."},{"topic":"History","question":"At which session did the Congress split in 1907?","options":["Surat","Lucknow","Lahore","Bombay"],"correct_index":0,"explanation":"The Congress split at Surat in 1907."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-7', 3, 'gk-modern-india', 'Gandhi and Non-Cooperation', 'The Gandhian era', 'History', 6, 'Gandhiji brought ordinary people into the freedom struggle. Let’s see how!', '["Gandhi returned to India from South Africa on 9 January 1915.","His first satyagrahas in India were at Champaran (1917), Kheda (1918) and Ahmedabad (1918).","On 13 April 1919, General Dyer’s troops fired on a peaceful crowd at Jallianwala Bagh in Amritsar.","The Non-Cooperation Movement began in 1920, joined with the Khilafat movement.","Gandhi stopped it after a crowd burned a police station at Chauri Chaura on 5 February 1922.","Rabindranath Tagore gave up his knighthood to protest the Jallianwala Bagh massacre."]'::jsonb, '9 January is celebrated as Pravasi Bharatiya Divas, marking Gandhi’s return to India.', '[{"heading":"First struggles","text":"In Champaran, Bihar, Gandhi helped indigo farmers forced to grow indigo. In Kheda, Gujarat, he supported farmers who could not pay taxes after crops failed, and in Ahmedabad he helped mill workers. His method was satyagraha: non-violent resistance."},{"heading":"Rowlatt Act and Jallianwala Bagh","text":"The Rowlatt Act of 1919 let the British jail people without trial. On 13 April 1919, at Jallianwala Bagh in Amritsar, General Dyer ordered troops to fire on an unarmed crowd, killing hundreds. The country was shocked."},{"heading":"Non-Cooperation","text":"From 1920, Indians left government schools, courts and jobs, and boycotted foreign cloth. Hindus and Muslims worked together with the Khilafat movement. When violence broke out at Chauri Chaura in 1922, Gandhi called the movement off."}]'::jsonb, '[{"topic":"History","question":"Gandhi’s first satyagraha in India was at…","options":["Kheda","Champaran","Dandi","Bardoli"],"correct_index":1,"explanation":"Champaran, Bihar, in 1917, for indigo farmers."},{"topic":"History","question":"When did the Jallianwala Bagh massacre take place?","options":["13 April 1919","15 August 1920","5 February 1922","26 January 1930"],"correct_index":0,"explanation":"It happened on 13 April 1919, in Amritsar."},{"topic":"History","question":"Why was the Non-Cooperation Movement stopped in 1922?","options":["Gandhi was jailed","The violence at Chauri Chaura","The British gave freedom","The Simon Commission came"],"correct_index":1,"explanation":"Gandhi stopped it after the violence at Chauri Chaura."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-8', 3, 'gk-modern-india', 'Purna Swaraj and the Salt March', 'The Gandhian era', 'History', 7, 'A handful of salt shook an empire. Let’s walk to Dandi!', '["The Simon Commission (1928) had no Indian member, so people greeted it with “Simon, go back!”","At the Lahore session in 1929, under Jawaharlal Nehru, the Congress demanded Purna Swaraj (complete independence).","26 January 1930 was celebrated as Independence Day.","Gandhi’s Salt March began from Sabarmati on 12 March 1930 and reached Dandi on 6 April, starting the Civil Disobedience Movement.","Bhagat Singh, Sukhdev and Rajguru were hanged on 23 March 1931.","The Poona Pact (1932) between Gandhi and Dr Ambedkar settled seats for the Depressed Classes."]'::jsonb, 'The Constitution came into force on 26 January because of the 1930 Purna Swaraj Day.', '[{"heading":"Simon, go back!","text":"In 1928 the British sent the Simon Commission to suggest reforms, but it had no Indian members. It was met with black flags. Lala Lajpat Rai was hurt in a police lathi charge in Lahore and died soon after."},{"heading":"Complete independence","text":"At Lahore in December 1929, with Nehru as president, the Congress set Purna Swaraj as its goal. On 26 January 1930, people across India took a pledge for complete independence."},{"heading":"Salt and civil disobedience","text":"Salt was taxed by the British, and everyone needed it. Gandhi walked about 385 km from Sabarmati to Dandi and made salt from sea water on 6 April 1930. Millions broke unjust laws peacefully. The Gandhi-Irwin Pact of 1931 paused the movement, and Gandhi went to the Second Round Table Conference in London."}]'::jsonb, '[{"topic":"History","question":"Who presided over the Lahore session of 1929?","options":["Mahatma Gandhi","Jawaharlal Nehru","Motilal Nehru","Subhas Chandra Bose"],"correct_index":1,"explanation":"Jawaharlal Nehru presided; Purna Swaraj was declared."},{"topic":"History","question":"The Salt March started from…","options":["Dandi","Champaran","Sabarmati Ashram","Wardha"],"correct_index":2,"explanation":"It began at Sabarmati Ashram on 12 March 1930."},{"topic":"History","question":"The Poona Pact of 1932 was between Gandhi and…","options":["Lord Irwin","Dr B. R. Ambedkar","Muhammad Ali Jinnah","Jawaharlal Nehru"],"correct_index":1,"explanation":"It was signed by Gandhi and Dr B. R. Ambedkar."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-9', 3, 'gk-modern-india', 'Quit India and Netaji Bose', 'Road to freedom', 'History', 8, '“Do or die!” and “Delhi chalo!” Let’s see the last big pushes for freedom!', '["The Cripps Mission of 1942 offered India dominion status after the war; the Congress rejected it.","The Quit India resolution was passed in Bombay on 8 August 1942; Gandhi gave the call “Do or die”.","Almost all Congress leaders were arrested at once, but people kept the movement going.","Subhas Chandra Bose led the Indian National Army (Azad Hind Fauj) and formed the Azad Hind government in Singapore in October 1943.","Bose’s slogans included “Delhi chalo” and “Give me blood, and I will give you freedom”.","The sailors of the Royal Indian Navy revolted in Bombay in February 1946."]'::jsonb, '9 August is remembered as August Kranti Day, after the Quit India Movement.', '[{"heading":"Quit India","text":"During the Second World War, the British wanted Indian support but would not promise freedom. On 8 August 1942, the Congress asked the British to quit India. Leaders were jailed the next morning, yet strikes, protests and underground work spread everywhere."},{"heading":"Netaji and the INA","text":"Subhas Chandra Bose escaped from house arrest in 1941 and went abroad. In 1943 he took charge of the Indian National Army in South-East Asia and set up the Azad Hind government. The INA fought alongside Japan towards India’s north-east."},{"heading":"The end draws near","text":"The INA trials at the Red Fort in 1945 stirred the whole country. In 1946, sailors of the Royal Indian Navy rebelled in Bombay. The British realised they could no longer hold India, and sent the Cabinet Mission in 1946 to plan the handover of power."}]'::jsonb, '[{"topic":"History","question":"When was the Quit India resolution passed?","options":["8 August 1942","15 August 1947","26 January 1930","9 January 1915"],"correct_index":0,"explanation":"It was passed in Bombay on 8 August 1942."},{"topic":"History","question":"Who said “Give me blood, and I will give you freedom”?","options":["Bhagat Singh","Subhas Chandra Bose","Bal Gangadhar Tilak","Chandra Shekhar Azad"],"correct_index":1,"explanation":"Netaji Subhas Chandra Bose."},{"topic":"History","question":"The Azad Hind government was formed in…","options":["Tokyo","Rangoon","Singapore","Berlin"],"correct_index":2,"explanation":"Bose formed it in Singapore in October 1943."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-modern-10', 3, 'gk-modern-india', 'Independence and Partition', 'Road to freedom', 'History', 9, 'Freedom came on 15 August 1947, with joy and great sorrow. Let’s learn how.', '["Lord Mountbatten announced his plan for freedom and partition on 3 June 1947.","The British Parliament passed the Indian Independence Act in July 1947.","India became independent on 15 August 1947; Pakistan was created a day earlier.","The border was drawn by a commission led by Cyril Radcliffe (the Radcliffe Line).","Sardar Vallabhbhai Patel, helped by V. P. Menon, brought more than 500 princely states into India.","Mahatma Gandhi was assassinated on 30 January 1948."]'::jsonb, 'C. Rajagopalachari was the first and only Indian Governor-General of independent India.', '[{"heading":"Freedom with partition","text":"The Congress and the Muslim League could not agree on one free India. Mountbatten’s plan of 3 June 1947 divided British India into India and Pakistan. On the night of 14–15 August 1947, Nehru gave his “Tryst with Destiny” speech."},{"heading":"The pain of partition","text":"Punjab and Bengal were split by the Radcliffe Line. Millions of people had to leave their homes and cross the new borders, and terrible violence took many lives."},{"heading":"Uniting the states","text":"About a third of India was made of princely states ruled by kings and nawabs. Sardar Patel and V. P. Menon persuaded almost all of them to sign the Instrument of Accession. Junagadh, Hyderabad and Kashmir took longer. For this work, Patel is called the Iron Man of India."}]'::jsonb, '[{"topic":"History","question":"Who drew the border between India and Pakistan?","options":["Lord Mountbatten","Cyril Radcliffe","V. P. Menon","Lord Wavell"],"correct_index":1,"explanation":"A commission led by Cyril Radcliffe drew the line."},{"topic":"History","question":"Who brought the princely states into India?","options":["Jawaharlal Nehru","Sardar Vallabhbhai Patel","Dr Rajendra Prasad","Maulana Azad"],"correct_index":1,"explanation":"Sardar Patel, helped by V. P. Menon, united the princely states."},{"topic":"History","question":"Who was the only Indian Governor-General of free India?","options":["C. Rajagopalachari","Dr Rajendra Prasad","Lord Mountbatten","Sardar Patel"],"correct_index":0,"explanation":"C. Rajagopalachari succeeded Mountbatten in 1948."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-indian-geography', 'Indian Geography', 'Geography', 'explore', '', 'General Knowledge', 'Mountains, rivers, climate, soils, forests and resources of India.', 21) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-1', 3, 'gk-indian-geography', 'India: location and size', 'Location and landforms', 'Geography', 0, 'Where exactly is India on the globe, and how big is it? Let’s find out!', '["India is the 7th largest country in the world by area, about 3.28 million square km.","It lies wholly in the Northern Hemisphere, and the Tropic of Cancer (23.5° N) passes through 8 states.","Indian Standard Time is based on 82.5° E longitude, and is 5 hours 30 minutes ahead of GMT.","India shares land borders with Pakistan, Afghanistan, China, Nepal, Bhutan, Bangladesh and Myanmar.","The longest border is with Bangladesh.","India’s southernmost point is Indira Point in the Nicobar Islands; on the mainland it is Kanyakumari."]'::jsonb, 'The Palk Strait separates India from Sri Lanka.', '[{"heading":"A big country","text":"India covers about 2.4% of the world’s land, yet is home to a much bigger share of its people. From north to south it stretches about 3,200 km, and from east to west about 2,900 km."},{"heading":"Latitude and time","text":"The Tropic of Cancer runs through the middle of India, through Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram. Because India is so wide, the whole country follows one standard time, based on 82.5° E, which passes near Mirzapur in Uttar Pradesh."},{"heading":"Neighbours","text":"India has seven neighbours on land. Across the sea are Sri Lanka, separated by the Palk Strait, and the Maldives. The Indian Ocean is the only ocean named after a country."}]'::jsonb, '[{"topic":"Geography","question":"Through how many Indian states does the Tropic of Cancer pass?","options":["6","7","8","10"],"correct_index":2,"explanation":"It passes through 8 states, from Gujarat to Mizoram."},{"topic":"Geography","question":"India shares its longest land border with…","options":["China","Pakistan","Nepal","Bangladesh"],"correct_index":3,"explanation":"India’s longest land border is with Bangladesh."},{"topic":"Geography","question":"Indian Standard Time is ahead of GMT by…","options":["4 hours","5 hours","5 hours 30 minutes","6 hours"],"correct_index":2,"explanation":"IST, based on 82.5° E, is 5 hours 30 minutes ahead."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-2', 3, 'gk-indian-geography', 'The Himalayas', 'Location and landforms', 'Geography', 1, 'The Himalayas are young, high and still rising! Let’s climb them.', '["The Himalayas are young fold mountains, formed when the Indian plate pushed into the Eurasian plate.","They have three parallel ranges: the Greater Himalaya (Himadri), the Lesser Himalaya (Himachal) and the Shiwaliks.","Most hill stations, such as Shimla and Mussoorie, are in the Lesser Himalaya.","Flat valleys between the Lesser Himalaya and the Shiwaliks are called duns, like Dehradun.","Kangchenjunga (8,586 m), on the Sikkim–Nepal border, is the third highest mountain in the world.","Important passes include Zoji La (Srinagar to Leh), Shipki La (Himachal Pradesh) and Nathu La (Sikkim)."]'::jsonb, 'The eastern hills along the Myanmar border, such as the Patkai, Naga and Mizo hills, are called the Purvanchal.', '[{"heading":"How they formed","text":"Millions of years ago the Indian plate moved north and pressed into Asia. The rocks in between were folded and pushed up to form the Himalayas. The plates are still moving, which is why the region has earthquakes."},{"heading":"Three ranges","text":"The Greater Himalaya, or Himadri, is the highest range and is always covered in snow. South of it is the Lesser Himalaya, or Himachal, with the famous hill stations. The outermost range is the Shiwaliks, low hills made of loose sediments."},{"heading":"Why they matter","text":"The Himalayas block cold winds from Central Asia and stop the monsoon winds, making them shed rain over India. Their glaciers feed great rivers like the Ganga, Indus and Brahmaputra."}]'::jsonb, '[{"topic":"Geography","question":"The outermost range of the Himalayas is called…","options":["Himadri","Himachal","Shiwaliks","Purvanchal"],"correct_index":2,"explanation":"The Shiwaliks are the outermost, lowest range."},{"topic":"Geography","question":"Which pass connects Srinagar and Leh?","options":["Nathu La","Zoji La","Shipki La","Bomdi La"],"correct_index":1,"explanation":"Zoji La is on the road from Srinagar to Leh."},{"topic":"Geography","question":"Dehradun is an example of a…","options":["dun","delta","plateau","pass"],"correct_index":0,"explanation":"Duns are flat valleys between the Lesser Himalaya and Shiwaliks."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-3', 3, 'gk-indian-geography', 'Plains, plateaus, deserts and islands', 'Location and landforms', 'Geography', 2, 'From flat plains to ancient plateaus and coral islands, India has it all. Let’s tour them!', '["The Northern Plains were made by soil brought down by the Indus, Ganga and Brahmaputra rivers.","The Peninsular Plateau is made of very old rocks, part of the ancient land of Gondwana.","The Western Ghats are continuous; the Eastern Ghats are broken by rivers. Anamudi in Kerala is the highest peak of South India.","The Aravallis are among the oldest mountains in the world; Guru Shikhar at Mount Abu is their highest point.","The Thar Desert lies in western Rajasthan, west of the Aravallis.","The Andaman and Nicobar Islands are in the Bay of Bengal; Lakshadweep, made of coral, is in the Arabian Sea."]'::jsonb, 'Barren Island in the Andamans is India’s only active volcano.', '[{"heading":"The great plains","text":"Between the Himalayas and the plateau lie some of the most fertile plains on Earth. Older alluvium on higher ground is called bhangar; newer alluvium near rivers, laid down every flood, is called khadar. These plains feed a huge population."},{"heading":"The plateau and the Ghats","text":"South of the plains is the Peninsular Plateau, the oldest part of India. The Deccan Plateau is edged by the Western Ghats (Sahyadri) and the Eastern Ghats, which meet in the Nilgiri hills. The coast on the west has the Konkan and Malabar coasts; on the east lies the Coromandel coast."},{"heading":"Desert and islands","text":"The Thar Desert gets very little rain and has sand dunes. Far out at sea are two island groups: the Andaman and Nicobar Islands, separated by the Ten Degree Channel, and the coral islands of Lakshadweep, with Kavaratti as their capital."}]'::jsonb, '[{"topic":"Geography","question":"Which is the highest peak of South India?","options":["Doddabetta","Anamudi","Guru Shikhar","Mahendragiri"],"correct_index":1,"explanation":"Anamudi, in Kerala, is the highest peak of South India."},{"topic":"Geography","question":"India’s only active volcano is on…","options":["Barren Island","Kavaratti","Great Nicobar","Majuli"],"correct_index":0,"explanation":"Barren Island is in the Andaman Sea."},{"topic":"Geography","question":"Newer alluvium on the Northern Plains is called…","options":["bhangar","khadar","bhabar","regur"],"correct_index":1,"explanation":"Khadar is new alluvium laid down by floods each year."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-4', 3, 'gk-indian-geography', 'Himalayan rivers', 'Rivers', 'Geography', 3, 'These rivers flow all year, fed by snow and rain. Let’s follow them from the mountains!', '["Himalayan rivers are perennial: they flow all year, fed by melting snow and by rain.","The Ganga forms at Devprayag, where the Bhagirathi (from the Gangotri glacier) meets the Alaknanda.","The Ganga is India’s longest river, about 2,525 km.","The Yamuna joins the Ganga at Prayagraj.","The Brahmaputra rises in Tibet, where it is called the Tsangpo, and enters India in Arunachal Pradesh.","The Indus rises in Tibet near Lake Mansarovar; its tributaries are the Jhelum, Chenab, Ravi, Beas and Satluj."]'::jsonb, 'Majuli, in the Brahmaputra in Assam, is one of the largest river islands in the world.', '[{"heading":"The Ganga system","text":"The Bhagirathi starts at Gaumukh, at the snout of the Gangotri glacier, and joins the Alaknanda at Devprayag to form the Ganga. Along the way it is joined by the Yamuna, Ghaghara, Gandak, Kosi and Son. It ends in the Bay of Bengal."},{"heading":"The Brahmaputra","text":"The Brahmaputra flows east across Tibet as the Tsangpo, turns sharply south into Arunachal Pradesh, and flows through Assam. Together the Ganga and Brahmaputra form the Sundarbans delta, the largest delta in the world."},{"heading":"The Indus","text":"The Indus flows through Ladakh into Pakistan. Its five big tributaries give Punjab its name, “land of five rivers”. Under the Indus Waters Treaty of 1960 with Pakistan, India uses the waters of the eastern rivers: the Ravi, Beas and Satluj."}]'::jsonb, '[{"topic":"Geography","question":"The Ganga is formed at Devprayag by the Bhagirathi and…","options":["the Yamuna","the Alaknanda","the Son","the Kosi"],"correct_index":1,"explanation":"The Bhagirathi and Alaknanda meet at Devprayag."},{"topic":"Geography","question":"In Tibet, the Brahmaputra is called…","options":["Tsangpo","Siang","Dihang","Lohit"],"correct_index":0,"explanation":"It is called the Tsangpo in Tibet."},{"topic":"Geography","question":"The Indus Waters Treaty was signed in…","options":["1947","1950","1960","1972"],"correct_index":2,"explanation":"India and Pakistan signed it in 1960."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-5', 3, 'gk-indian-geography', 'Peninsular rivers', 'Rivers', 'Geography', 4, 'The rivers of the south depend on the rain. Let’s see where they flow!', '["Peninsular rivers are mostly fed by rain, so many shrink in the dry season.","The Godavari is the longest peninsular river, often called the “Dakshin Ganga”; it rises near Nashik.","The Mahanadi, Godavari, Krishna and Kaveri flow east and form deltas on the Bay of Bengal.","The Narmada and Tapi flow west, through rift valleys, and form estuaries instead of deltas.","The Narmada rises at Amarkantak; the Kaveri rises at Talakaveri in the Brahmagiri hills of Karnataka.","The Hirakud Dam is on the Mahanadi in Odisha; the Sardar Sarovar Dam is on the Narmada in Gujarat."]'::jsonb, 'The Narmada flows through the marble rocks at Bhedaghat, near Jabalpur, and forms the Dhuandhar Falls.', '[{"heading":"East-flowing rivers","text":"Most rivers of the plateau rise in the Western Ghats and flow east to the Bay of Bengal. The Godavari, Krishna, Kaveri and Mahanadi build large, fertile deltas where they meet the sea, which are major rice-growing areas."},{"heading":"West-flowing rivers","text":"The Narmada and Tapi flow west into the Arabian Sea. They run through narrow rift valleys and are fast, so they don’t drop much sediment and form estuaries. Many short rivers also rush down the Western Ghats to the sea."},{"heading":"Dams and waterfalls","text":"Big dams store water for farms and power: Hirakud on the Mahanadi, Nagarjuna Sagar on the Krishna, and Sardar Sarovar on the Narmada. Jog Falls on the Sharavati river in Karnataka is one of India’s highest waterfalls."}]'::jsonb, '[{"topic":"Geography","question":"Which river is called the “Dakshin Ganga”?","options":["Krishna","Kaveri","Godavari","Narmada"],"correct_index":2,"explanation":"The Godavari, the longest peninsular river."},{"topic":"Geography","question":"Which of these rivers flows west and forms an estuary?","options":["Mahanadi","Narmada","Krishna","Kaveri"],"correct_index":1,"explanation":"The Narmada flows west through a rift valley."},{"topic":"Geography","question":"The Hirakud Dam is built on which river?","options":["Mahanadi","Godavari","Narmada","Tapi"],"correct_index":0,"explanation":"Hirakud is on the Mahanadi in Odisha."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-6', 3, 'gk-indian-geography', 'Climate and the monsoon', 'Climate', 'Geography', 5, 'Everyone in India waits for the monsoon! Let’s learn how it works.', '["India has a tropical monsoon climate: the winds change direction with the seasons.","The four seasons are winter (Dec–Feb), summer (Mar–May), the south-west monsoon (Jun–Sep) and the retreating monsoon (Oct–Nov).","The south-west monsoon usually reaches Kerala around 1 June.","Mawsynram in Meghalaya is one of the wettest places on Earth.","The Tamil Nadu coast gets much of its rain in October–December, from the retreating (north-east) monsoon.","The “loo” is a hot, dry wind that blows over the northern plains in summer."]'::jsonb, 'Pre-monsoon showers in Kerala and Karnataka are called “mango showers”, as they help mangoes ripen.', '[{"heading":"What is a monsoon?","text":"Monsoon means a seasonal change of wind. In summer the land heats up, and moist winds blow in from the Indian Ocean from the south-west, bringing heavy rain. In winter the winds blow the other way, from land to sea, and are mostly dry."},{"heading":"Where the rain falls","text":"The Western Ghats and the north-east get very heavy rain, while western Rajasthan stays dry. Mawsynram and Cherrapunji (Sohra) in Meghalaya get some of the highest rainfall in the world."},{"heading":"Local winds","text":"In summer, the loo blows over the northern plains. Bengal and Assam get stormy evening showers called Kalbaisakhi (Nor’westers). In winter, western disturbances bring light rain to the north-west, which helps the wheat crop."}]'::jsonb, '[{"topic":"Geography","question":"The south-west monsoon usually reaches Kerala around…","options":["1 April","1 June","1 August","1 October"],"correct_index":1,"explanation":"It usually arrives in Kerala around 1 June."},{"topic":"Geography","question":"Mawsynram, one of the wettest places on Earth, is in…","options":["Assam","Kerala","Meghalaya","Sikkim"],"correct_index":2,"explanation":"Mawsynram is in Meghalaya."},{"topic":"Geography","question":"The hot, dry summer wind of the northern plains is called…","options":["Loo","Kalbaisakhi","Mango shower","Western disturbance"],"correct_index":0,"explanation":"The loo blows in May and June over the northern plains."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-7', 3, 'gk-indian-geography', 'Soils of India', 'Soils, forests and wildlife', 'Geography', 6, 'Different soils grow different crops. Let’s dig in!', '["Alluvial soil, brought by rivers, covers the largest area and is very fertile.","Black soil, also called regur, formed from lava rock in the Deccan; it holds moisture and is best for cotton.","Red soil gets its colour from iron oxide.","Laterite soil forms where heavy rain washes nutrients away; it is good for cashew, tea and coffee.","Desert (arid) soil is sandy and salty, and found in western Rajasthan.","Soil erosion is the loss of the top soil by wind and water; planting trees and terrace farming help prevent it."]'::jsonb, 'Black soil is also called “black cotton soil”.', '[{"heading":"Alluvial soil","text":"Rivers carry fine soil down from the mountains and spread it over the plains and deltas. This alluvial soil is rich in potash and grows rice, wheat, sugarcane and pulses. It covers the Northern Plains and the coastal deltas."},{"heading":"Black, red and laterite","text":"Black soil covers much of Maharashtra, Gujarat and Madhya Pradesh. It is sticky when wet and cracks when dry. Red soil is found in drier parts of the plateau. Laterite soil, found in high-rainfall areas like Kerala and the Western Ghats, is also used to make bricks."},{"heading":"Protecting soil","text":"Top soil takes hundreds of years to form but can be lost quickly. Farmers protect it with terrace farming on slopes, contour ploughing, rows of trees as wind breaks, and by not letting animals overgraze."}]'::jsonb, '[{"topic":"Geography","question":"Which soil is best for growing cotton?","options":["Alluvial","Black","Laterite","Desert"],"correct_index":1,"explanation":"Black (regur) soil holds moisture and suits cotton."},{"topic":"Geography","question":"Red soil is red because of…","options":["iron oxide","lava","salt","potash"],"correct_index":0,"explanation":"Iron oxide gives red soil its colour."},{"topic":"Geography","question":"Which soil covers the largest area of India?","options":["Black","Red","Alluvial","Laterite"],"correct_index":2,"explanation":"Alluvial soil covers the largest area."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-8', 3, 'gk-indian-geography', 'Forests and wildlife', 'Soils, forests and wildlife', 'Geography', 7, 'Tigers, rhinos, lions and elephants all live in India! Let’s visit their homes.', '["Tropical deciduous (monsoon) forests are the most common in India; teak and sal grow in them.","Tropical evergreen forests grow where it rains heavily, in the Western Ghats, the north-east and the Andamans.","Mangrove forests grow on coasts and deltas; the Sundarbans are the largest, home of the Royal Bengal tiger.","Jim Corbett National Park (1936) in Uttarakhand was India’s first national park.","Project Tiger began in 1973; the Wildlife (Protection) Act was passed in 1972.","Kaziranga (Assam) protects the one-horned rhino, and Gir (Gujarat) is the only wild home of the Asiatic lion."]'::jsonb, 'About one-fifth of India’s land is under forest, and Madhya Pradesh has the largest forest area of any state.', '[{"heading":"Kinds of forest","text":"The kind of forest depends on rain. Heavy rain gives tall, green evergreen forests. Moderate rain gives deciduous forests, whose trees shed leaves in the dry season. Little rain gives thorny scrub, and high mountains have pine and deodar forests."},{"heading":"Saving animals","text":"India set up national parks and wildlife sanctuaries to protect animals in their homes. The Wildlife (Protection) Act of 1972 made hunting of protected animals a crime. Project Tiger (1973) and Project Elephant (1992) protect two of our most famous animals."},{"heading":"Famous parks","text":"Jim Corbett National Park was the first, started in 1936. Kaziranga in Assam has most of the world’s one-horned rhinos. Gir in Gujarat is the last wild home of the Asiatic lion. The Sundarbans protect tigers that swim between mangrove islands."}]'::jsonb, '[{"topic":"Geography","question":"Which was India’s first national park?","options":["Kaziranga","Gir","Jim Corbett","Sundarbans"],"correct_index":2,"explanation":"Jim Corbett National Park was started in 1936."},{"topic":"Geography","question":"The Asiatic lion lives in the wild only in…","options":["Gir","Kanha","Ranthambore","Periyar"],"correct_index":0,"explanation":"Gir in Gujarat is its only wild home."},{"topic":"Geography","question":"In which year did Project Tiger begin?","options":["1947","1972","1973","1992"],"correct_index":2,"explanation":"Project Tiger began in 1973."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-9', 3, 'gk-indian-geography', 'Agriculture', 'Resources', 'Geography', 8, 'Farming feeds over a billion people. Let’s learn India’s crop seasons!', '["Kharif crops are sown with the monsoon (June–July): rice, maize, cotton, jowar and soybean.","Rabi crops are sown in winter (October–December) and harvested in spring: wheat, gram, barley and mustard.","Zaid crops grow in the short summer season: watermelon, cucumber and muskmelon.","The Green Revolution of the 1960s used high-yielding seeds to raise wheat and rice output, first in Punjab and Haryana.","India is the world’s largest producer of milk, thanks to Operation Flood (the White Revolution).","Assam grows the most tea, and Karnataka the most coffee."]'::jsonb, 'Jute is called the “golden fibre”; West Bengal grows the most.', '[{"heading":"Three crop seasons","text":"Kharif crops need the monsoon rain and are harvested in autumn. Rabi crops grow in the cool, dry winter and are harvested around March–April. Between them comes the short zaid season, for quick summer crops like melons."},{"heading":"The Green Revolution","text":"In the 1960s India faced food shortages. Scientists such as M. S. Swaminathan helped bring high-yielding seeds, more irrigation and fertilisers. Wheat production rose sharply, and India soon grew enough grain for itself."},{"heading":"Milk and more","text":"Operation Flood, led by Dr Verghese Kurien from 1970, built a network of dairy co-operatives, and India became the world’s largest milk producer. India also grows a lot of tea, spices, sugarcane, cotton and jute."}]'::jsonb, '[{"topic":"Geography","question":"Which of these is a rabi crop?","options":["Rice","Cotton","Wheat","Maize"],"correct_index":2,"explanation":"Wheat is sown in winter and is a rabi crop."},{"topic":"Geography","question":"Who led Operation Flood, the White Revolution?","options":["M. S. Swaminathan","Dr Verghese Kurien","Norman Borlaug","C. Subramaniam"],"correct_index":1,"explanation":"Dr Verghese Kurien led Operation Flood."},{"topic":"Geography","question":"Which fibre is called the “golden fibre”?","options":["Cotton","Silk","Jute","Wool"],"correct_index":2,"explanation":"Jute is the golden fibre."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-geography-10', 3, 'gk-indian-geography', 'Minerals and energy', 'Resources', 'Geography', 9, 'Coal, iron, oil and sunshine power India. Let’s see where they come from!', '["Most of India’s coal comes from Jharkhand, Odisha and Chhattisgarh; Jharia is a famous coalfield.","Iron ore is mined in Odisha, Chhattisgarh (Bailadila) and Karnataka.","Digboi in Assam has India’s oldest working oil refinery, from 1901.","Mumbai High is a big offshore oil field in the Arabian Sea.","Tarapur in Maharashtra had India’s first nuclear power station (1969).","Most electricity still comes from coal, but solar and wind power are growing fast."]'::jsonb, 'Odisha has the largest bauxite reserves; bauxite is the ore of aluminium.', '[{"heading":"Minerals in the plateau","text":"Most of India’s minerals are found in the old rocks of the Peninsular Plateau, especially the Chota Nagpur area of Jharkhand, Odisha and Chhattisgarh. This region has coal, iron ore, bauxite and manganese, which is why many steel plants are there."},{"heading":"Oil and gas","text":"Oil was first found in Assam, where the Digboi refinery started in 1901. Later, large fields were found off the coast of Mumbai (Mumbai High) and in Gujarat, and gas in the Krishna–Godavari basin."},{"heading":"Power for the future","text":"Coal-fired (thermal) power stations make most of India’s electricity. Dams give hydro power, and Tarapur started nuclear power in 1969. India now builds big solar parks, such as Bhadla in Rajasthan, and wind farms in states like Gujarat and Tamil Nadu."}]'::jsonb, '[{"topic":"Geography","question":"India’s oldest working oil refinery is at…","options":["Mumbai","Digboi","Jamnagar","Barauni"],"correct_index":1,"explanation":"Digboi in Assam, started in 1901."},{"topic":"Geography","question":"Bauxite is the ore of which metal?","options":["Iron","Copper","Aluminium","Gold"],"correct_index":2,"explanation":"Aluminium is made from bauxite."},{"topic":"Geography","question":"India’s first nuclear power station was at…","options":["Kalpakkam","Kudankulam","Tarapur","Narora"],"correct_index":2,"explanation":"Tarapur in Maharashtra, from 1969."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-world-geography', 'World Geography', 'Geography', 'explore', '', 'General Knowledge', 'The Solar System, the restless Earth, air, oceans and the world map.', 22) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-1', 3, 'gk-world-geography', 'The Solar System', 'Earth and space', 'Geography', 0, 'Let’s zoom out into space and meet the Sun and its eight planets!', '["The Solar System has the Sun at its centre and eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune.","Mercury is the smallest planet and the closest to the Sun.","Venus is the hottest planet and spins in the opposite direction to most planets.","Jupiter is the largest planet; Saturn is famous for its bright rings.","Mars is called the Red Planet because of iron oxide (rust) in its soil.","Pluto was called a planet until 2006, when it was renamed a dwarf planet."]'::jsonb, 'Sunlight takes about 8 minutes 20 seconds to reach the Earth.', '[{"heading":"The Sun","text":"The Sun is a star, a huge ball of hot gas that makes energy by joining hydrogen into helium. It holds almost all the mass of the Solar System, and its gravity keeps the planets in their orbits."},{"heading":"Rocky and giant planets","text":"The four inner planets, Mercury, Venus, Earth and Mars, are small and rocky. Between Mars and Jupiter lies the asteroid belt. The four outer planets are giants made mostly of gas and ice. Uranus spins tipped on its side, and Neptune is the farthest."},{"heading":"Our Moon","text":"The Moon is Earth’s only natural satellite. It always shows the same face to us. In August 2023, India’s Chandrayaan-3 became the first mission to land near the Moon’s south pole; 23 August is now National Space Day."}]'::jsonb, '[{"topic":"Geography","question":"Which is the largest planet in the Solar System?","options":["Saturn","Jupiter","Neptune","Earth"],"correct_index":1,"explanation":"Jupiter is the largest planet."},{"topic":"Geography","question":"Which planet is the hottest?","options":["Mercury","Mars","Venus","Jupiter"],"correct_index":2,"explanation":"Venus is hottest: its thick clouds trap heat, even though Mercury is closer to the Sun."},{"topic":"Geography","question":"In which year was Pluto renamed a dwarf planet?","options":["1930","1990","2006","2015"],"correct_index":2,"explanation":"Astronomers renamed Pluto a dwarf planet in 2006."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-2', 3, 'gk-world-geography', 'The Earth’s motions and time', 'Earth and space', 'Geography', 1, 'The Earth spins and travels at the same time! Let’s see what that does to our days and seasons.', '["The Earth spins on its axis from west to east once a day: this is rotation, and it causes day and night.","It goes around the Sun in about 365¼ days: this is revolution. The extra quarter day gives us a leap year every four years.","Seasons happen because the Earth’s axis is tilted by about 23.5°.","Around 21 June the Northern Hemisphere has its longest day; around 22 December, its shortest.","On the equinoxes, around 21 March and 23 September, day and night are nearly equal everywhere.","The Prime Meridian (0°) passes through Greenwich, London. Every 15° of longitude makes a one-hour time difference."]'::jsonb, 'The International Date Line runs roughly along 180° longitude; crossing it changes the date by one day.', '[{"heading":"Rotation","text":"As the Earth turns, half of it faces the Sun (day) and half faces away (night). Because it spins from west to east, the Sun seems to rise in the east and set in the west."},{"heading":"Revolution and seasons","text":"The tilted Earth travels around the Sun. In June the Northern Hemisphere leans towards the Sun and has summer; in December it leans away and has winter. The Southern Hemisphere has the opposite seasons."},{"heading":"Latitude, longitude and time","text":"Lines of latitude run east–west and measure distance from the Equator. Lines of longitude run from pole to pole. The Earth turns 360° in 24 hours, so every 15° of longitude is one hour, and every 1° is four minutes."}]'::jsonb, '[{"topic":"Geography","question":"What causes day and night?","options":["The Earth’s revolution","The Earth’s rotation","The tilt of the axis","The Moon"],"correct_index":1,"explanation":"Rotation, the Earth spinning on its axis, causes them."},{"topic":"Geography","question":"How many degrees of longitude make a one-hour time difference?","options":["1°","10°","15°","24°"],"correct_index":2,"explanation":"360° in 24 hours means 15° for each hour."},{"topic":"Geography","question":"The longest day in the Northern Hemisphere is around…","options":["21 March","21 June","23 September","22 December"],"correct_index":1,"explanation":"Around 21 June, the summer solstice."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-3', 3, 'gk-world-geography', 'Inside the Earth and rocks', 'The restless Earth', 'Geography', 2, 'What’s under our feet, all the way to the centre? Let’s dig deep!', '["The Earth has three main layers: the crust, the mantle and the core.","The crust is the thin outer layer; it is thicker under the continents than under the oceans.","The core is made mostly of nickel and iron: the outer core is liquid and the inner core is solid.","Igneous rocks form from cooled magma or lava, such as granite and basalt.","Sedimentary rocks form in layers, such as sandstone and limestone; they often contain fossils.","Metamorphic rocks are changed by heat and pressure: limestone becomes marble, and shale becomes slate."]'::jsonb, 'Oxygen is the most common element in the Earth’s crust, followed by silicon; aluminium is the most common metal.', '[{"heading":"Three layers","text":"If the Earth were an apple, the crust would be thinner than its skin. Below it is the thick, hot mantle, where rock flows very slowly. At the centre is the core of iron and nickel, hotter than the surface of the Sun."},{"heading":"How rocks form","text":"Igneous rocks form when molten rock cools, either deep underground (granite) or on the surface (basalt). Sedimentary rocks build up from sand, mud and shells pressed together over millions of years. Metamorphic rocks are older rocks changed by heat and pressure."},{"heading":"The rock cycle","text":"Rocks keep changing from one kind to another. Weather breaks them into pieces, rivers carry the pieces away to form new layers, and heat inside the Earth melts and changes them again."}]'::jsonb, '[{"topic":"Geography","question":"Marble is formed from which rock?","options":["Granite","Limestone","Basalt","Shale"],"correct_index":1,"explanation":"Heat and pressure turn limestone into marble."},{"topic":"Geography","question":"The Earth’s core is made mostly of…","options":["silicon and oxygen","nickel and iron","carbon","aluminium"],"correct_index":1,"explanation":"The core is mostly nickel and iron."},{"topic":"Geography","question":"Which kind of rock often contains fossils?","options":["Igneous","Metamorphic","Sedimentary","Volcanic"],"correct_index":2,"explanation":"Sedimentary rocks form in layers that trap fossils."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-4', 3, 'gk-world-geography', 'Plates, earthquakes and volcanoes', 'The restless Earth', 'Geography', 3, 'The ground is moving, very, very slowly! Let’s see what happens when it moves suddenly.', '["The Earth’s crust is broken into large pieces called plates, which move a few centimetres a year.","Alfred Wegener suggested in 1912 that all continents were once joined in one super-continent, Pangaea.","The point inside the Earth where an earthquake starts is the focus; the point right above it on the surface is the epicentre.","Earthquakes are recorded by a seismograph, and their size is given on the Richter (magnitude) scale.","Most volcanoes and earthquakes happen around the Pacific Ocean, in the “Ring of Fire”.","A tsunami is a giant sea wave set off by an undersea earthquake; one struck the Indian Ocean on 26 December 2004."]'::jsonb, 'The Roman city of Pompeii was buried by the eruption of Mount Vesuvius in 79 CE.', '[{"heading":"Moving plates","text":"Plates float on the soft upper mantle. Where they pull apart, new crust forms; where they push together, mountains like the Himalayas, Alps and Andes rise, or one plate sinks under another."},{"heading":"Earthquakes","text":"When stress builds up along a fault and suddenly slips, the ground shakes. Waves spread out from the focus. Scientists measure them with seismographs, but cannot yet predict exactly when an earthquake will strike."},{"heading":"Volcanoes","text":"A volcano is an opening where magma comes up as lava, ash and gas. Active volcanoes erupt often, dormant ones are sleeping, and extinct ones are not expected to erupt again. Mount Fuji in Japan and Mount Etna in Italy are famous examples."}]'::jsonb, '[{"topic":"Geography","question":"The point on the surface right above an earthquake’s start is the…","options":["focus","epicentre","crater","fault"],"correct_index":1,"explanation":"The epicentre is directly above the focus."},{"topic":"Geography","question":"Who gave the idea of continental drift?","options":["Isaac Newton","Alfred Wegener","Charles Darwin","Charles Richter"],"correct_index":1,"explanation":"Alfred Wegener proposed it in 1912."},{"topic":"Geography","question":"The “Ring of Fire” surrounds which ocean?","options":["Atlantic","Indian","Arctic","Pacific"],"correct_index":3,"explanation":"It runs around the edges of the Pacific Ocean."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-5', 3, 'gk-world-geography', 'The atmosphere', 'Air and weather', 'Geography', 4, 'We live at the bottom of an ocean of air. Let’s go up through its layers!', '["Air is about 78% nitrogen and 21% oxygen, with small amounts of argon, carbon dioxide and other gases.","The lowest layer, the troposphere, is where almost all weather and clouds happen.","The stratosphere above it has the ozone layer, which absorbs harmful ultraviolet rays from the Sun.","Meteors burn up in the mesosphere.","In the thermosphere, the ionosphere reflects radio waves back to Earth; auroras glow here.","The Montreal Protocol (1987) is an agreement to protect the ozone layer."]'::jsonb, '16 September is World Ozone Day.', '[{"heading":"What air is made of","text":"Nitrogen and oxygen make up about 99% of dry air. Carbon dioxide is only a tiny part, but it traps heat. Water vapour, dust and smoke are also mixed in, and help clouds form."},{"heading":"Layers of the atmosphere","text":"From the ground up come the troposphere, stratosphere, mesosphere, thermosphere and exosphere. In the troposphere it gets colder as you go higher. Big jets fly near its top, where the air is calm."},{"heading":"Ozone and greenhouse gases","text":"Gases called CFCs, once used in fridges and sprays, thinned the ozone layer, especially over Antarctica. The Montreal Protocol banned them. Greenhouse gases such as carbon dioxide trap heat; adding too much of them is warming the Earth."}]'::jsonb, '[{"topic":"Geography","question":"Which gas makes up most of the air?","options":["Oxygen","Carbon dioxide","Nitrogen","Argon"],"correct_index":2,"explanation":"Nitrogen is about 78% of the air."},{"topic":"Geography","question":"The ozone layer is in the…","options":["troposphere","stratosphere","mesosphere","exosphere"],"correct_index":1,"explanation":"The ozone layer is in the stratosphere."},{"topic":"Geography","question":"Which layer reflects radio waves?","options":["Ionosphere","Troposphere","Stratosphere","Ozone layer"],"correct_index":0,"explanation":"The ionosphere, in the thermosphere, reflects them."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-6', 3, 'gk-world-geography', 'Winds, cyclones and climate zones', 'Air and weather', 'Geography', 5, 'Why does the wind blow, and what makes a cyclone? Let’s find out!', '["Wind blows from areas of high pressure to areas of low pressure.","The Earth’s spin bends winds to the right in the Northern Hemisphere and to the left in the Southern Hemisphere (the Coriolis effect).","The main planetary winds are the trade winds, the westerlies and the polar easterlies.","The calm belt near the Equator is called the doldrums.","Tropical storms are called hurricanes in the Atlantic, typhoons in the western Pacific and cyclones in the Indian Ocean.","The calm centre of a cyclone is called its eye."]'::jsonb, 'The strong westerlies of the Southern Hemisphere are called the “Roaring Forties”.', '[{"heading":"Pressure and wind","text":"Warm air rises and leaves low pressure behind; cool air sinks and makes high pressure. Air rushes from high to low, and that is wind. Because the Earth spins, the winds curve instead of blowing straight."},{"heading":"Storms","text":"Over warm oceans, rising moist air can grow into a huge spinning storm. Its winds and rain do great damage when it reaches land. The same kind of storm has different names in different oceans."},{"heading":"Local winds and climate zones","text":"Some winds have their own names: the Chinook, which melts snow in the Rockies, the hot dusty Sirocco from the Sahara, and the dry Harmattan of West Africa. Broadly, the world has hot equatorial and tropical zones, mild temperate zones and cold polar zones."}]'::jsonb, '[{"topic":"Geography","question":"In the Atlantic Ocean, tropical storms are called…","options":["typhoons","hurricanes","tornadoes","monsoons"],"correct_index":1,"explanation":"They are called hurricanes in the Atlantic."},{"topic":"Geography","question":"The calm belt near the Equator is called the…","options":["doldrums","Roaring Forties","trade winds","eye"],"correct_index":0,"explanation":"The doldrums are the calm belt near the Equator."},{"topic":"Geography","question":"Wind blows from…","options":["low pressure to high pressure","high pressure to low pressure","east to west always","the poles to the Moon"],"correct_index":1,"explanation":"Air moves from high pressure towards low pressure."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-7', 3, 'gk-world-geography', 'Oceans, tides and currents', 'Oceans', 'Geography', 6, 'Most of our planet is blue! Let’s dive into the oceans.', '["Oceans cover about 71% of the Earth’s surface.","There are five oceans: the Pacific, Atlantic, Indian, Southern and Arctic.","The Pacific is the largest and deepest; the Arctic is the smallest and shallowest.","The Mariana Trench in the Pacific is the deepest place in the oceans, about 11 km deep.","Tides are caused mainly by the pull of the Moon’s gravity.","The warm Gulf Stream keeps north-western Europe milder than other places so far north."]'::jsonb, 'The Great Barrier Reef off Australia is the world’s largest coral reef system.', '[{"heading":"The five oceans","text":"The Pacific is bigger than all the land on Earth put together. The Atlantic is shaped like a long S. The Indian Ocean is the only one named after a country. The Southern Ocean surrounds Antarctica, and the Arctic Ocean is around the North Pole."},{"heading":"Tides","text":"The Moon’s gravity pulls the ocean water into bulges, so most coasts get two high tides and two low tides a day. When the Sun and Moon line up, at new moon and full moon, we get extra-high spring tides; at half moon we get smaller neap tides."},{"heading":"Ocean currents","text":"Currents are rivers of water inside the ocean. Warm currents, like the Gulf Stream and the Kuroshio, carry heat from the tropics. Cold currents, like the Labrador Current, flow from the poles. Where warm and cold currents meet, near Newfoundland, there is thick fog and rich fishing."}]'::jsonb, '[{"topic":"Geography","question":"Which is the largest ocean?","options":["Atlantic","Indian","Pacific","Southern"],"correct_index":2,"explanation":"The Pacific is the largest and deepest ocean."},{"topic":"Geography","question":"Tides are caused mainly by…","options":["wind","the Moon’s gravity","earthquakes","rivers"],"correct_index":1,"explanation":"The Moon’s pull is the main cause of tides."},{"topic":"Geography","question":"The deepest place in the oceans is the…","options":["Mariana Trench","Java Trench","Puerto Rico Trench","Dead Sea"],"correct_index":0,"explanation":"The Mariana Trench, in the Pacific, about 11 km deep."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-8', 3, 'gk-world-geography', 'The seven continents', 'The world map', 'Geography', 7, 'Seven big pieces of land make up our world map. Let’s visit each!', '["The seven continents, from largest to smallest: Asia, Africa, North America, South America, Antarctica, Europe and Australia.","Asia is the largest continent and has the most people.","Africa is crossed by the Equator and both the Tropics.","Antarctica is the coldest continent and has no permanent population; India’s research stations there are Maitri and Bharati.","The Ural Mountains are seen as the border between Europe and Asia.","The Suez Canal (1869) joins the Mediterranean and Red Seas; the Panama Canal (1914) joins the Atlantic and Pacific."]'::jsonb, 'The Bering Strait separates Asia from North America.', '[{"heading":"The big ones","text":"Asia covers nearly a third of the world’s land and has the highest mountains. Africa has the Sahara Desert and the Nile. North America has the Rocky Mountains and the Great Lakes."},{"heading":"The rest","text":"South America has the Andes and the Amazon rainforest. Antarctica is almost entirely covered by thick ice. Europe is small but has many countries. Australia is the smallest continent, and also a single country."},{"heading":"Short cuts for ships","text":"Canals save ships long journeys. The Suez Canal in Egypt lets ships go from Europe to Asia without sailing around Africa. The Panama Canal saves the long trip around South America. The Strait of Gibraltar separates Europe from Africa."}]'::jsonb, '[{"topic":"Geography","question":"Which is the smallest continent?","options":["Europe","Antarctica","Australia","South America"],"correct_index":2,"explanation":"Australia is the smallest continent."},{"topic":"Geography","question":"The Suez Canal joins the Mediterranean Sea and the…","options":["Black Sea","Red Sea","Arabian Sea","Caspian Sea"],"correct_index":1,"explanation":"It joins the Mediterranean and the Red Sea."},{"topic":"Geography","question":"Which of these is an Indian research station in Antarctica?","options":["Maitri","Himadri","Aryabhata","Sagar"],"correct_index":0,"explanation":"Maitri and Bharati are India’s stations there."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-9', 3, 'gk-world-geography', 'Nature’s record breakers', 'The world map', 'Geography', 8, 'Highest, longest, deepest! Let’s learn the world’s record-breaking places.', '["Mount Everest, on the Nepal–China border, is the highest mountain, about 8,849 m.","The Nile is usually counted as the longest river; the Amazon carries the most water.","The Sahara is the largest hot desert; Antarctica, the largest desert of all, is cold.","The Caspian Sea is the largest lake; Lake Baikal in Russia is the deepest.","The shore of the Dead Sea is the lowest place on land.","Angel Falls in Venezuela is the highest waterfall, and Greenland is the largest island."]'::jsonb, 'The Andes in South America are the longest mountain range on land.', '[{"heading":"Mountains","text":"Everest was measured again in 2020 at about 8,849 m. Mountaineers Tenzing Norgay and Edmund Hillary first climbed it in 1953. The world’s longest mountain chain on land is the Andes."},{"heading":"Water","text":"The Nile flows north through Africa into the Mediterranean. The Amazon, in South America, carries more water than any other river. The Caspian Sea, between Europe and Asia, is the largest lake, and Lake Baikal holds more fresh water than any other lake."},{"heading":"Deserts and islands","text":"A desert is a place that gets very little rain, so Antarctica counts as one. The Sahara, in North Africa, is the biggest hot desert. Greenland is the largest island; Australia is bigger but is counted as a continent."}]'::jsonb, '[{"topic":"Geography","question":"Which is the deepest lake in the world?","options":["Caspian Sea","Lake Superior","Lake Baikal","Dead Sea"],"correct_index":2,"explanation":"Lake Baikal in Russia is the deepest lake."},{"topic":"Geography","question":"Which is the largest island in the world?","options":["Greenland","Borneo","Madagascar","Sri Lanka"],"correct_index":0,"explanation":"Greenland is the largest island."},{"topic":"Geography","question":"The highest waterfall in the world is…","options":["Niagara Falls","Victoria Falls","Angel Falls","Jog Falls"],"correct_index":2,"explanation":"Angel Falls is in Venezuela."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-world-geo-10', 3, 'gk-world-geography', 'Countries, borders and nicknames', 'The world map', 'Geography', 9, 'Which country is the Land of the Rising Sun? Let’s learn famous borders and nicknames!', '["Russia is the largest country by area, and Vatican City is the smallest.","India became the most populous country in 2023, passing China.","The McMahon Line is the India–China border in the east; the Durand Line separates Afghanistan and Pakistan.","The 49th parallel forms much of the USA–Canada border; the 38th parallel is linked with the line between North and South Korea.","Japan is the “Land of the Rising Sun”, and Norway the “Land of the Midnight Sun”.","Bhutan is the “Land of the Thunder Dragon”, and Finland the “Land of a Thousand Lakes”."]'::jsonb, 'The Pamir Knot in Central Asia is called the “Roof of the World”.', '[{"heading":"Big and small","text":"Russia stretches across Europe and Asia and has eleven time zones. Vatican City, inside Rome, is smaller than many parks. Canada has the longest coastline of any country."},{"heading":"Famous border lines","text":"Some borders are named after the people who drew them: the McMahon Line (India–China), the Durand Line (Afghanistan–Pakistan) and the Radcliffe Line (India–Pakistan). Others follow lines of latitude, like the 49th parallel between the USA and Canada."},{"heading":"Nicknames","text":"Japan sees the sunrise early, so it is the Land of the Rising Sun. In northern Norway the summer Sun does not set, so it is the Land of the Midnight Sun. Cuba was called the “Sugar Bowl of the World” for its sugarcane."}]'::jsonb, '[{"topic":"Geography","question":"Which is called the “Land of the Rising Sun”?","options":["China","Japan","Norway","Bhutan"],"correct_index":1,"explanation":"Japan is the Land of the Rising Sun."},{"topic":"Geography","question":"The McMahon Line is the border between India and…","options":["Pakistan","Nepal","China","Bangladesh"],"correct_index":2,"explanation":"It is the India–China border in the east."},{"topic":"Geography","question":"Which is the smallest country in the world?","options":["Monaco","Vatican City","Maldives","San Marino"],"correct_index":1,"explanation":"Vatican City is the smallest country."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-indian-economy', 'Indian Economy', 'Economy', 'explore', '', 'General Knowledge', 'Planning, banking, inflation, the Budget, GST and welfare schemes.', 23) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-1', 3, 'gk-indian-economy', 'What is an economy?', 'Basics', 'Economy', 0, 'Everything we make, buy and sell is part of the economy. Let’s learn the basic words!', '["An economy is how a country produces, shares and uses goods and services.","The primary sector uses nature directly: farming, fishing, mining.","The secondary sector makes things: factories, building, electricity.","The tertiary (service) sector gives services: banks, shops, transport, schools, IT. It is the biggest part of India’s GDP.","GDP (Gross Domestic Product) is the value of all final goods and services made inside a country in a year.","India is a mixed economy: both the government and private businesses run industries."]'::jsonb, 'Per capita income is a country’s national income divided by its population.', '[{"heading":"Three sectors","text":"A farmer growing wheat is in the primary sector. A factory turning wheat into biscuits is in the secondary sector. The truck driver and shopkeeper who bring biscuits to you are in the tertiary sector. In India, services make up the largest share of GDP, but farming still employs the largest share of workers."},{"heading":"Measuring the economy","text":"GDP counts what is produced inside the country. GNP (Gross National Product) adds what citizens earn abroad and takes away what foreigners earn here. Dividing national income by the number of people gives per capita income, a rough idea of the average income."},{"heading":"Kinds of economies","text":"In a capitalist economy, private owners run most businesses. In a socialist economy, the state owns most of them. India chose a mixed economy, where both work side by side."}]'::jsonb, '[{"topic":"Economy","question":"Fishing and mining belong to which sector?","options":["Primary","Secondary","Tertiary","Quaternary"],"correct_index":0,"explanation":"They use nature directly, so they are primary."},{"topic":"Economy","question":"GDP measures the value of goods and services made…","options":["by citizens anywhere in the world","inside the country","only by the government","only in factories"],"correct_index":1,"explanation":"GDP counts everything produced inside the country."},{"topic":"Economy","question":"India’s economy is described as…","options":["capitalist","socialist","mixed","barter"],"correct_index":2,"explanation":"Both government and private businesses take part."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-2', 3, 'gk-indian-economy', 'Planning and the 1991 reforms', 'Basics', 'Economy', 1, 'After 1947 India planned its growth five years at a time. Then in 1991 things changed! Let’s see how.', '["The Planning Commission was set up in 1950, with the Prime Minister as its chairman.","The First Five-Year Plan (1951–56) focused on agriculture.","The Second Plan (1956–61), based on the Mahalanobis model, focused on heavy industry.","The Twelfth Plan (2012–17) was the last Five-Year Plan.","NITI Aayog replaced the Planning Commission on 1 January 2015.","The 1991 reforms opened up the economy: Liberalisation, Privatisation and Globalisation (LPG)."]'::jsonb, 'The 1991 reforms were introduced when P. V. Narasimha Rao was Prime Minister and Dr Manmohan Singh was Finance Minister.', '[{"heading":"Five-Year Plans","text":"India borrowed the idea of five-year plans from the Soviet Union, to decide where to spend money first. The early plans built dams, steel plants and farms. In all, there were twelve plans, ending in 2017."},{"heading":"NITI Aayog","text":"In 2015, the Planning Commission was replaced by NITI Aayog (National Institution for Transforming India). It acts as a think tank: it advises the Union and state governments instead of handing out money through plans."},{"heading":"The 1991 crisis and reforms","text":"In 1991 India had very little foreign money left to pay for imports. The government cut red tape and licences (liberalisation), let private firms into more areas (privatisation), and welcomed foreign trade and investment (globalisation). Growth sped up after this."}]'::jsonb, '[{"topic":"Economy","question":"NITI Aayog replaced the Planning Commission in…","options":["1991","2005","2015","2017"],"correct_index":2,"explanation":"NITI Aayog came into being on 1 January 2015."},{"topic":"Economy","question":"The Second Five-Year Plan was based on whose model?","options":["Harrod-Domar","P. C. Mahalanobis","Amartya Sen","M. S. Swaminathan"],"correct_index":1,"explanation":"It followed the Mahalanobis model, stressing industry."},{"topic":"Economy","question":"In the 1991 reforms, what does the “L” in LPG stand for?","options":["Loans","Liberalisation","Licensing","Labour"],"correct_index":1,"explanation":"Liberalisation, Privatisation and Globalisation."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-3', 3, 'gk-indian-economy', 'The Reserve Bank of India', 'Money and banking', 'Economy', 2, 'Who prints our notes and looks after all the banks? Let’s visit the RBI!', '["The Reserve Bank of India (RBI) is India’s central bank; it started on 1 April 1935 and was nationalised in 1949.","Its headquarters are in Mumbai.","The RBI issues all currency notes except the ₹1 note, which is issued by the Government of India (Ministry of Finance).","It is the “banker’s bank” and the government’s banker.","The repo rate is the rate at which the RBI lends money to banks.","A Monetary Policy Committee of six members, headed by the RBI Governor, decides the repo rate."]'::jsonb, 'The rupee symbol ₹ was adopted in 2010; it was designed by D. Udaya Kumar.', '[{"heading":"A bank for banks","text":"You keep money in a bank; banks keep some of theirs with the RBI. The RBI makes the rules for banks, checks that they are safe, and lends to them when they are short of money."},{"heading":"Managing money","text":"The RBI controls how much money flows in the economy. When prices rise too fast, it raises the repo rate, making loans costlier so people spend less. When growth is slow, it cuts the rate to encourage borrowing."},{"heading":"Our currency","text":"The RBI prints and issues our banknotes and manages India’s foreign exchange reserves. Coins and the ₹1 note come from the Government of India; the ₹1 note carries the Finance Secretary’s signature instead of the RBI Governor’s."}]'::jsonb, '[{"topic":"Economy","question":"When was the RBI set up?","options":["1 April 1935","15 August 1947","1 January 1949","1969"],"correct_index":0,"explanation":"The RBI started on 1 April 1935."},{"topic":"Economy","question":"Which note is NOT issued by the RBI?","options":["₹1","₹10","₹100","₹500"],"correct_index":0,"explanation":"The ₹1 note is issued by the Government of India."},{"topic":"Economy","question":"The rate at which the RBI lends to banks is the…","options":["bank account rate","repo rate","GST rate","tax rate"],"correct_index":1,"explanation":"That is the repo rate."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-4', 3, 'gk-indian-economy', 'Banks, markets and digital money', 'Money and banking', 'Economy', 3, 'From big banks to UPI on your phone, let’s see how money moves in India!', '["14 large private banks were nationalised on 19 July 1969, and 6 more in 1980.","The State Bank of India was formed in 1955 from the Imperial Bank of India.","NABARD (1982) is the top bank for farming and rural development.","SEBI regulates the stock markets; it got legal powers in 1992.","The Bombay Stock Exchange (BSE), set up in 1875, is the oldest in Asia; its index is the Sensex. The NSE’s index is the Nifty.","UPI, launched in 2016 by NPCI, lets people pay instantly from their phones."]'::jsonb, 'The Pradhan Mantri Jan Dhan Yojana (2014) opened bank accounts for millions of families.', '[{"heading":"Banks for everyone","text":"Before 1969, most banks were privately owned and few served villages. Nationalisation put big banks under the government so that farmers and small businesses could get loans. Regional rural banks and NABARD were set up for villages."},{"heading":"Stock markets","text":"Companies sell shares on stock exchanges to raise money, and people buy them hoping to share in profits. The BSE and NSE are in Mumbai. SEBI makes the rules to protect investors."},{"heading":"Going digital","text":"The National Payments Corporation of India (NPCI) built RuPay cards and UPI. With UPI, you can send money with a QR code or a phone number in seconds. India now makes a huge number of digital payments every day."}]'::jsonb, '[{"topic":"Economy","question":"When were 14 major banks nationalised?","options":["1955","1969","1980","1991"],"correct_index":1,"explanation":"On 19 July 1969."},{"topic":"Economy","question":"Which body regulates India’s stock markets?","options":["RBI","NABARD","SEBI","NITI Aayog"],"correct_index":2,"explanation":"SEBI regulates the stock markets."},{"topic":"Economy","question":"The Sensex is the index of which stock exchange?","options":["NSE","BSE","New York","London"],"correct_index":1,"explanation":"The Sensex is the BSE’s index; the Nifty is the NSE’s."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-5', 3, 'gk-indian-economy', 'Inflation', 'Money and banking', 'Economy', 4, 'Why does a chocolate cost more today than when your parents were young? Let’s understand inflation!', '["Inflation is a general rise in prices over time; your money buys less.","Deflation is the opposite: a general fall in prices.","The Consumer Price Index (CPI) measures prices that families pay; the Wholesale Price Index (WPI) measures prices in bulk trade.","Since 2016, the RBI has been asked to keep CPI inflation near 4%, within a band of 2% to 6%.","Inflation can be caused by too much money chasing too few goods, or by rising costs, such as fuel.","Stagflation is when prices rise while growth is slow and jobs are scarce."]'::jsonb, 'Rising interest rates are one of the main tools used to bring inflation down.', '[{"heading":"What inflation means","text":"If prices rise by 5% in a year, something that cost ₹100 last year now costs ₹105. A little inflation is normal in a growing economy, but high inflation hurts poor families most, as their income does not rise as fast."},{"heading":"Measuring it","text":"The government tracks the prices of a fixed basket of goods, like food, fuel, clothes and rent. The CPI follows what shoppers pay, and the WPI follows prices between businesses. The RBI uses the CPI for its inflation target."},{"heading":"Why prices rise","text":"Demand-pull inflation happens when people want to buy more than is available. Cost-push inflation happens when costs, like oil or wages, go up and businesses pass them on to buyers."}]'::jsonb, '[{"topic":"Economy","question":"A general fall in prices is called…","options":["inflation","deflation","stagflation","recession"],"correct_index":1,"explanation":"Deflation is a general fall in prices."},{"topic":"Economy","question":"The RBI’s inflation target is based on which index?","options":["WPI","CPI","Sensex","GDP"],"correct_index":1,"explanation":"It targets CPI inflation, near 4%."},{"topic":"Economy","question":"Rising prices with slow growth and few jobs is called…","options":["stagflation","deflation","boom","devaluation"],"correct_index":0,"explanation":"That combination is called stagflation."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-6', 3, 'gk-indian-economy', 'The Union Budget', 'Government finance', 'Economy', 5, 'Every year the government makes a plan for its money. Let’s open the Budget briefcase!', '["The Constitution calls the Budget the “Annual Financial Statement” (Article 112).","India’s financial year runs from 1 April to 31 March.","Since 2017, the Union Budget is presented on 1 February.","Also since 2017, the Railway Budget has been merged with the Union Budget.","The fiscal deficit is how much more the government spends than it earns, not counting borrowing.","The Finance Commission (Article 280), set up every five years, suggests how tax money is shared between the Union and the states."]'::jsonb, 'The Comptroller and Auditor General (CAG, Article 148) checks the accounts of the Union and state governments.', '[{"heading":"What is in the Budget","text":"The Budget shows how much the government expects to earn from taxes and other sources, and how much it will spend on things like defence, roads, schools, health and subsidies, for the next financial year."},{"heading":"Deficits","text":"When spending is more than income, there is a deficit, which the government fills by borrowing. The fiscal deficit is watched closely: if it is too high, debt keeps growing."},{"heading":"Sharing and checking","text":"The Union collects many taxes, but states run schools, police and hospitals. The Finance Commission recommends a fair share for each state. The CAG audits how public money was spent and reports to Parliament."}]'::jsonb, '[{"topic":"Economy","question":"Since 2017, the Union Budget is presented on…","options":["1 January","1 February","28 February","1 April"],"correct_index":1,"explanation":"It has been presented on 1 February since 2017."},{"topic":"Economy","question":"Which Article calls the Budget the “Annual Financial Statement”?","options":["Article 110","Article 112","Article 280","Article 148"],"correct_index":1,"explanation":"Article 112 of the Constitution."},{"topic":"Economy","question":"India’s financial year begins on…","options":["1 January","1 April","1 July","1 October"],"correct_index":1,"explanation":"It runs from 1 April to 31 March."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-7', 3, 'gk-indian-economy', 'Taxes and GST', 'Government finance', 'Economy', 6, 'Taxes pay for roads, schools and hospitals. Let’s see the kinds of taxes, and the big change called GST!', '["A direct tax is paid straight to the government by the person it is on, such as income tax and corporate tax.","An indirect tax is collected through the price of goods and services, such as GST and customs duty.","The Goods and Services Tax (GST) started on 1 July 2017.","It was made possible by the 101st Constitutional Amendment (2016).","The GST Council, headed by the Union Finance Minister, decides GST rates; state finance ministers are members.","GST has three parts: CGST (Union), SGST (state) and IGST (trade between states)."]'::jsonb, 'GST replaced many older indirect taxes, such as excise duty, service tax and VAT, with one tax.', '[{"heading":"Direct and indirect","text":"Income tax is direct: you pay it on what you earn, and the more you earn, the higher the rate. Indirect taxes are hidden in prices: when you buy a toy, part of the price goes to the government."},{"heading":"One nation, one tax","text":"Before GST, goods were taxed many times by the Union and the states, and trucks waited at state borders. GST joined these into one tax, charged where goods are consumed. It came into force on 1 July 2017."},{"heading":"The GST Council","text":"Because GST is shared by the Union and states, a joint GST Council (Article 279A) decides rates and rules. The Union Finance Minister chairs it, and every state has a voice."}]'::jsonb, '[{"topic":"Economy","question":"When did GST come into force?","options":["1 April 2016","1 July 2017","1 January 2018","2014"],"correct_index":1,"explanation":"GST began on 1 July 2017."},{"topic":"Economy","question":"Which of these is a direct tax?","options":["GST","Customs duty","Income tax","Excise duty"],"correct_index":2,"explanation":"Income tax is paid directly by the earner."},{"topic":"Economy","question":"Who chairs the GST Council?","options":["The Prime Minister","The RBI Governor","The Union Finance Minister","The President"],"correct_index":2,"explanation":"The Union Finance Minister chairs it."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-8', 3, 'gk-indian-economy', 'Farms, factories and revolutions', 'Sectors and people', 'Economy', 7, 'Green, white, blue… India had revolutions of many colours! Let’s find out what each one means.', '["The Green Revolution raised food-grain output, especially wheat.","The White Revolution (Operation Flood) raised milk output.","The Blue Revolution is about fish, and the Yellow Revolution about oilseeds.","The Silver Revolution is linked with eggs and poultry.","The Industrial Policy Resolution of 1956 gave the public sector a leading role in industry.","“Make in India”, launched in 2014, invites companies to make their products in India."]'::jsonb, 'MSMEs (micro, small and medium enterprises) employ a very large number of Indians.', '[{"heading":"Revolutions in farming","text":"Each “revolution” was a big push to grow more of something: grains (Green), milk (White), fish (Blue), oilseeds (Yellow) and eggs (Silver). They helped India feed its people and cut imports."},{"heading":"Building industry","text":"After freedom, the government built big public sector units, such as steel plants and power stations, because private firms were small. Policies in 1948 and 1956 set out which industries the state would run."},{"heading":"Industry today","text":"After 1991, private and foreign companies grew fast. Schemes like Make in India and Startup India encourage factories, new businesses and jobs. Small businesses (MSMEs) are the backbone of many towns."}]'::jsonb, '[{"topic":"Economy","question":"The Blue Revolution is connected with…","options":["milk","fish","oilseeds","eggs"],"correct_index":1,"explanation":"The Blue Revolution is about fish production."},{"topic":"Economy","question":"The Yellow Revolution is connected with…","options":["oilseeds","gold","bananas","honey"],"correct_index":0,"explanation":"It aimed to grow more oilseeds."},{"topic":"Economy","question":"When was “Make in India” launched?","options":["1991","2005","2014","2020"],"correct_index":2,"explanation":"Make in India was launched in 2014."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-9', 3, 'gk-indian-economy', 'Poverty, jobs and welfare schemes', 'Sectors and people', 'Economy', 8, 'An economy is about people, not just money. Let’s see how India fights poverty!', '["The Human Development Index (HDI), published by the UNDP since 1990, measures health, education and income.","The HDI was developed by Mahbub ul Haq, working with Amartya Sen.","Amartya Sen won the Nobel Prize in Economics in 1998.","MGNREGA (2005) promises at least 100 days of paid work a year to rural households who ask for it.","PM-KISAN (2019) gives eligible farmer families ₹6,000 a year.","Ayushman Bharat (2018) gives health cover to poor families."]'::jsonb, 'Disguised unemployment is when more people work on a job, such as a family farm, than are really needed.', '[{"heading":"More than income","text":"A country can be rich on average but still have many poor people. The HDI looks at how long people live, how much schooling they get and their income, to judge real progress."},{"heading":"Kinds of unemployment","text":"Some people cannot find work at all. Others work only in certain seasons, like farm workers (seasonal unemployment). On many small farms, more family members work than are needed: this is disguised unemployment."},{"heading":"Helping hands","text":"MGNREGA gives a legal right to paid work in villages. PM-KISAN sends money straight to farmers’ bank accounts. Ayushman Bharat pays for hospital care. Direct Benefit Transfer sends help straight to bank accounts, cutting out middlemen."}]'::jsonb, '[{"topic":"Economy","question":"MGNREGA promises how many days of work a year?","options":["50","100","150","365"],"correct_index":1,"explanation":"At least 100 days of paid work for rural households."},{"topic":"Economy","question":"Who publishes the Human Development Index?","options":["World Bank","IMF","UNDP","WTO"],"correct_index":2,"explanation":"The UNDP has published it since 1990."},{"topic":"Economy","question":"Amartya Sen won the Nobel Prize in Economics in…","options":["1979","1998","2001","2019"],"correct_index":1,"explanation":"He won it in 1998."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-economy-10', 3, 'gk-indian-economy', 'World economic organisations', 'India and the world', 'Economy', 9, 'Countries trade and lend to each other. Let’s meet the big world organisations!', '["The IMF and the World Bank came out of the Bretton Woods conference of 1944; both are based in Washington, D.C.","The IMF helps countries with money troubles; the World Bank lends for development projects.","The World Trade Organization (WTO) began on 1 January 1995, replacing GATT; it is based in Geneva.","The Asian Development Bank is based in Manila.","The BRICS countries set up the New Development Bank, based in Shanghai.","India held the G20 presidency in 2023 and hosted its summit in New Delhi."]'::jsonb, 'India was a founding member of both the IMF and the World Bank.', '[{"heading":"Bretton Woods twins","text":"In 1944, near the end of the Second World War, countries met at Bretton Woods in the USA to plan a stable world economy. They created the IMF, to keep currencies steady and help countries in crisis, and the World Bank, to rebuild and develop."},{"heading":"Rules for trade","text":"GATT, signed in 1947, cut tariffs on goods. In 1995 it was replaced by the WTO, which covers goods, services and ideas, and settles trade disputes between countries."},{"heading":"Groups of countries","text":"The G20 brings together the world’s major economies. BRICS began with Brazil, Russia, India, China and South Africa, and set up its own New Development Bank. India hosted the G20 summit in New Delhi in September 2023."}]'::jsonb, '[{"topic":"Economy","question":"The WTO replaced which agreement?","options":["GATT","NAFTA","SAARC","BRICS"],"correct_index":0,"explanation":"The WTO replaced GATT on 1 January 1995."},{"topic":"Economy","question":"Where is the WTO based?","options":["New York","Washington, D.C.","Geneva","Paris"],"correct_index":2,"explanation":"The WTO is based in Geneva, Switzerland."},{"topic":"Economy","question":"The IMF and World Bank came from which 1944 conference?","options":["Yalta","Bretton Woods","Potsdam","Bandung"],"correct_index":1,"explanation":"Both came from the Bretton Woods conference."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
